insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (117, 8, 41, 54, 'سورة الأنفال ٤١ – ٥٤', 'قسمة الغنائم و«يوم الفرقان»، عوامل النصر «إذا لقيتم فئة فاثبتوا»، و«حتى يغيّروا ما بأنفسهم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 117) = $j$[{"lbl": "الآيات ٤١ – ٤٤", "q": "۞وَٱعۡلَمُوٓاْ أَنَّمَا غَنِمۡتُم مِّن شَيۡءٖ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلۡنَا عَلَىٰ عَبۡدِنَا يَوۡمَ ٱلۡفُرۡقَانِ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿٤١﴾ إِذۡ أَنتُم بِٱلۡعُدۡوَةِ ٱلدُّنۡيَا وَهُم بِٱلۡعُدۡوَةِ ٱلۡقُصۡوَىٰ وَٱلرَّكۡبُ أَسۡفَلَ مِنكُمۡۚ وَلَوۡ تَوَاعَدتُّمۡ لَٱخۡتَلَفۡتُمۡ فِي ٱلۡمِيعَٰدِ وَلَٰكِن لِّيَقۡضِيَ ٱللَّهُ أَمۡرٗا كَانَ مَفۡعُولٗا لِّيَهۡلِكَ مَنۡ هَلَكَ عَنۢ بَيِّنَةٖ وَيَحۡيَىٰ مَنۡ حَيَّ عَنۢ بَيِّنَةٖۗ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ ﴿٤٢﴾ إِذۡ يُرِيكَهُمُ ٱللَّهُ فِي مَنَامِكَ قَلِيلٗاۖ وَلَوۡ أَرَىٰكَهُمۡ كَثِيرٗا لَّفَشِلۡتُمۡ وَلَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَلَٰكِنَّ ٱللَّهَ سَلَّمَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٤٣﴾ وَإِذۡ يُرِيكُمُوهُمۡ إِذِ ٱلۡتَقَيۡتُمۡ فِيٓ أَعۡيُنِكُمۡ قَلِيلٗا وَيُقَلِّلُكُمۡ فِيٓ أَعۡيُنِهِمۡ لِيَقۡضِيَ ٱللَّهُ أَمۡرٗا كَانَ مَفۡعُولٗاۗ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ﴿٤٤﴾", "w": [["أنما غنمتم من شيء", "ما أخذتموه من مال الكافر قهراً لهم وغلبة، قليلاً كان أو كثيراً."], ["فأن لله خمسه", "خمس الخمسة أقسام يكون لله والرسول ومن ذُكر بعدهما."], ["ولذي القربى", "قرابة الرسول ﷺ من بني هاشم وبني المطلب."], ["وما أنزلنا على عبدنا", "من الملائكة والآيات."], ["يوم الفرقان", "يوم بدر، السابع عشر من رمضان، إذ فرّق الله فيه بين الحق والباطل."], ["التقى الجمعان", "جمع المؤمنين وجمع الكافرين ببدر."], ["بالعدوة الدنيا", "العدوة: حافة الوادي وجانبه، والدنيا: القريبة إلى المدينة."], ["بالعدوة القصوى", "البعيدة من المدينة، حافة الوادي الأخرى."], ["والركب أسفل منكم", "ركب أبي سفيان، وهي العير التي خرجوا من أجلها."], ["عن بيّنة", "عن حجة ظاهرة."], ["لتنازعتم في الأمر", "اختلفتم."], ["ويقلّلكم في أعينهم", "هذا قبل الالتحام، أما بعده فقد رأوهم مثليهم حتى تتم الهزيمة."]], "m": "نزلت في بيان قسمة الغنائم بعدما حصل فيها من نزاع: واعلموا أنما غنمتم من مال الكفار المحاربين غلبة وقهراً فأن لله خمسه وللرسول ولذي القربى واليتامى والمساكين وابن السبيل، والأربعة الأخماس الباقية للمجاهدين، للراجل سهم وللفارس سهمان لتأثيره في الحرب وحاجة فرسه إلى العلف. فما لله يُنفق في المصالح العامة، كالكعبة وسائر المساجد، وما للرسول ينفقه على عياله، وما لذي القربى لقرابته الذين تحرم عليهم الزكاة لشرفهم، واليتامى والمساكين لفقراء المسلمين، وابن السبيل للمسافرين المنقطعين المحتاجين، إن كنتم آمنتم بالله وما أنزلنا على عبدنا من الملائكة والآيات يوم الفرقان يوم التقى الجمعان ببدر، والله على كل شيء قدير. إذ أنتم بالعدوة الدنيا وهم بالعدوة القصوى والركب أسفل منكم، ولو تواعدتم أنتم والمشركون على اللقاء لاختلفتم في الميعاد لقلّتكم وكثرتهم، ولكن ليقضي الله أمراً كان مفعولاً: نصركم وهزيمة عدوكم، ليهلك بالكفر من هلك عن بيّنة، ويحيا بالإيمان من حيّ عن بيّنة، إذ أراهم الآيات. إذ يريكهم الله في منامك قليلاً، فأخبرت أصحابك فسرّوا ووطّنوا أنفسهم للقتال، ولو أراكهم كثيراً لفشلتم ولتنازعتم، ولكن الله سلّم، إنه عليم بذات الصدور. وإذ يريكموهم إذ التقيتم في أعينكم قليلاً، كأنهم سبعون أو مائة، ويقلّلكم في أعينهم حتى لا يهابوكم، ليقضي الله أمراً كان مفعولاً، وإلى الله تُرجع الأمور.", "h": ["بيان قسمة الغنائم على الوجه الذي رضيه الله تعالى.", "التذكير بالإيمان، إذ هو الطاقة الموجّهة، باعتبار أن المؤمن حي بإيمانه يقدر على الفعل والترك، والكافر ميت فلا يُكلّف.", "فضيلة غزوة بدر وفضل أهلها.", "بيان تدبير الله تعالى في نصر أوليائه وهزيمة أعدائه.", "بيان أن مردّ الأمور نجاحاً وخيبة لله تعالى، ليس لأحد فيها تأثير إلا بإذنه."], "k": "«ولكن الله سلّم»… كم من شر صرفه الله عني بتدبير خفي لم أعلمه إلا بعد حين؟"}, {"lbl": "الآيات ٤٥ – ٤٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمۡ فِئَةٗ فَٱثۡبُتُواْ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ ﴿٤٥﴾ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ وَتَذۡهَبَ رِيحُكُمۡۖ وَٱصۡبِرُوٓاْۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ ﴿٤٦﴾ وَلَا تَكُونُواْ كَٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِم بَطَرٗا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۚ وَٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطٞ ﴿٤٧﴾ وَإِذۡ زَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ وَقَالَ لَا غَالِبَ لَكُمُ ٱلۡيَوۡمَ مِنَ ٱلنَّاسِ وَإِنِّي جَارٞ لَّكُمۡۖ فَلَمَّا تَرَآءَتِ ٱلۡفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيۡهِ وَقَالَ إِنِّي بَرِيٓءٞ مِّنكُمۡ إِنِّيٓ أَرَىٰ مَا لَا تَرَوۡنَ إِنِّيٓ أَخَافُ ٱللَّهَۚ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ ﴿٤٨﴾ إِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٌ غَرَّ هَـٰٓؤُلَآءِ دِينُهُمۡۗ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ﴿٤٩﴾", "w": [["فئة", "طائفة مقاتلة."], ["فاثبتوا", "لقتالها واصمدوا."], ["واذكروا الله كثيراً", "مهلّلين مكبّرين، راجين النصر طامعين فيه، سائلين الله تعالى إياه."], ["تفلحون", "تفوزون بالنصر في الدنيا والجنة في الآخرة، بعد النجاة من الهزيمة في الدنيا والنار في الآخرة."], ["ولا تنازعوا", "لا تختلفوا وأنتم في مواجهة العدو أبداً."], ["وتذهب ريحكم", "قوتكم بسبب الخلاف."], ["خرجوا من ديارهم بطراً", "للبطر الذي هو دفع الحق ومنعه."], ["وإني جار لكم", "مجير لكم ومعين على عدوكم."], ["تراءت الفئتان", "التقتا ورأت كل منهما عدوها."], ["نكص على عقبيه", "رجع إلى الوراء هارباً، لأنه جاءهم في صورة سراقة بن مالك."], ["إني أرى ما لا ترون", "من الملائكة."], ["والذين في قلوبهم مرض", "ضعف في إيمانهم وخلل في اعتقادهم."]], "m": "نداء موجّه إلى المؤمنين وقد أُذن لهم في القتال، فهم بحاجة إلى تعليم رباني يعرفون به كيف يخوضون المعارك وينتصرون، وهذه عوامل النصر: الثبات في وجه العدو: يا أيها الذين آمنوا إذا لقيتم فئة فاثبتوا، وذكر الله تهليلاً وتكبيراً ودعاءً: واذكروا الله كثيراً لعلكم تفلحون، وطاعة الله ورسوله، ومنه طاعة قائد المعركة: وأطيعوا الله ورسوله، وعدم التنازع عند التدبير وأثناء الخوض، فنتيجته الفشل وذهاب القوة: ولا تنازعوا فتفشلوا وتذهب ريحكم، والصبر على مواصلة القتال: واصبروا إن الله مع الصابرين، والإخلاص فيه لله: ولا تكونوا كالذين خرجوا من ديارهم بطراً ورئاء الناس ويصدّون عن سبيل الله. ثم ذكّرهم بحادثة غريبة يوم بدر: وإذ زيّن لهم الشيطان أعمالهم، وكان في صورة سراقة بن مالك، وقال: لا غالب لكم اليوم من الناس وإني جار لكم، فلما تراءت الفئتان رأى جبريل في صفوف الملائكة فنكص على عقبيه، وكان آخذاً بيد الحارث بن هشام، فقال له: ما بك؟ فقال وهو هارب: إني بريء منكم، إني أرى ما لا ترون، إني أخاف الله والله شديد العقاب، وصدق وهو كذوب. إذ يقول المنافقون والذين في قلوبهم مرض: غرّ هؤلاء دينهم حتى خرجوا لقريش وهي تفوقهم عدداً وعدة، فلا يفتّ هذا في أعضادكم، ومن يتوكل على الله فإن الله عزيز حكيم يضع النصر في المتأهّلين له.", "h": ["بيان أسباب النصر وعوامله، ووجوب الأخذ بها في كل معركة، وهي: الثبات، وذكر الله تعالى، وطاعة الله ورسوله وطاعة القيادة، وترك النزاع والخلاف، والصبر، والإخلاص.", "بيان عوامل الفشل والخيبة، وهي: النزاع والاختلاف، والبطر، والرياء، والاغترار.", "بيان عمل الشيطان في نفوس الكافرين بتزيينه لهم الحرب، ووعده وتمنيته لهم.", "وجوب التوكل على الله والاعتماد عليه مهما كانت دعاوى المبطلين والمثبّطين."], "k": "«ولا تنازعوا فتفشلوا وتذهب ريحكم»… في بيتي أو عملي، هل أُطفئ الخلاف أم أُشعله؟"}, {"lbl": "الآيات ٥٠ – ٥٤", "q": "وَلَوۡ تَرَىٰٓ إِذۡ يَتَوَفَّى ٱلَّذِينَ كَفَرُواْ ٱلۡمَلَـٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَٰرَهُمۡ وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ ﴿٥٠﴾ ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّـٰمٖ لِّلۡعَبِيدِ ﴿٥١﴾ كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۚ إِنَّ ٱللَّهَ قَوِيّٞ شَدِيدُ ٱلۡعِقَابِ ﴿٥٢﴾ ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمۡ يَكُ مُغَيِّرٗا نِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ﴿٥٣﴾ كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِ رَبِّهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَۚ وَكُلّٞ كَانُواْ ظَٰلِمِينَ ﴿٥٤﴾", "w": [["إذ يتوفّى", "يقبض أرواحهم لإماتتهم."], ["وجوههم وأدبارهم", "يضربونهم من أمامهم ومن خلفهم."], ["بظلّام للعبيد", "ليس بذي ظلم للعبيد، كقوله: «ولا يظلم ربك أحداً»."], ["كدأب آل فرعون", "دأب كفار قريش كدأب آل فرعون في الكفر والتكذيب، والدأب: العادة."], ["لم يك مغيّراً نعمة", "تغيير النعمة: تبديلها بنقمة، بسلبها أو تعذيب أهلها."], ["آل فرعون", "كل من كان على دينه من الأقباط مشاركاً له في ظلمه وكفره."]], "m": "ولو ترى إذ يتوفّى الذين كفروا الملائكة يضربون وجوههم وأدبارهم، ويقولون: وذوقوا عذاب الحريق، لرأيت أمراً فظيعاً، ذلك بما قدّمت أيديكم من الكفر والظلم والفساد، وأن الله ليس بظلّام للعبيد. دأب هؤلاء المشركين كدأب آل فرعون والذين من قبلهم، كفروا بآيات الله فأخذهم الله بذنوبهم، إن الله قوي شديد العقاب، يشهد له فعله بعاد وثمود وقوم إبراهيم وأصحاب مدين والمؤتفكات، وأخيراً أخذه كفار قريش في بدر. ذلك بأن الله لم يك مغيّراً نعمة أنعمها على قوم، كالأمن والرخاء أو الطهر والصفاء، حتى يغيّروا ما بأنفسهم بالكفر والتكذيب والظلم والفسق، وعندئذ يبدّلها نقماً: الخوف والغلاء، والخبث والشر، إن لم يأخذهم بالاستئصال التام، وأن الله سميع عليم فيتم الجزاء عادلاً. كدأب آل فرعون والذين من قبلهم كذّبوا بآيات ربهم فأهلكناهم بذنوبهم وأغرقنا آل فرعون وكلٌّ كانوا ظالمين، وتخالف الآية السابقة في أن الذنب هنا التكذيب، ونوع العذاب الإغراق، وسُجّل على الكل ذنب الظلم.", "h": ["تقرير عذاب القبر، بتقرير العذاب عند النزع.", "هذه الآية نظيرها آية الأنعام: «ولو ترى إذ الظالمون في غمرات الموت والملائكة باسطو أيديهم»، أي بالضرب.", "تنزّه الخالق عز وجل عن الظلم لأحد.", "سنة الله تعالى في أخذ الظالمين، وإبدال النعم بالنقم.", "التنديد بالظلم وأهله، وأنه الذنب الذي يُطلق على سائر الذنوب."], "k": "«حتى يغيّروا ما بأنفسهم»… نعمة أخشى زوالها؛ فهل غيّرت شيئاً في نفسي يهدّدها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 117;
insert into public.tdb_cards(topic, i, body) select 117, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤١ – ٤٤", "q": "۞وَٱعۡلَمُوٓاْ أَنَّمَا غَنِمۡتُم مِّن شَيۡءٖ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلۡنَا عَلَىٰ عَبۡدِنَا يَوۡمَ ٱلۡفُرۡقَانِ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿٤١﴾ إِذۡ أَنتُم بِٱلۡعُدۡوَةِ ٱلدُّنۡيَا وَهُم بِٱلۡعُدۡوَةِ ٱلۡقُصۡوَىٰ وَٱلرَّكۡبُ أَسۡفَلَ مِنكُمۡۚ وَلَوۡ تَوَاعَدتُّمۡ لَٱخۡتَلَفۡتُمۡ فِي ٱلۡمِيعَٰدِ وَلَٰكِن لِّيَقۡضِيَ ٱللَّهُ أَمۡرٗا كَانَ مَفۡعُولٗا لِّيَهۡلِكَ مَنۡ هَلَكَ عَنۢ بَيِّنَةٖ وَيَحۡيَىٰ مَنۡ حَيَّ عَنۢ بَيِّنَةٖۗ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ ﴿٤٢﴾ إِذۡ يُرِيكَهُمُ ٱللَّهُ فِي مَنَامِكَ قَلِيلٗاۖ وَلَوۡ أَرَىٰكَهُمۡ كَثِيرٗا لَّفَشِلۡتُمۡ وَلَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَلَٰكِنَّ ٱللَّهَ سَلَّمَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿٤٣﴾ وَإِذۡ يُرِيكُمُوهُمۡ إِذِ ٱلۡتَقَيۡتُمۡ فِيٓ أَعۡيُنِكُمۡ قَلِيلٗا وَيُقَلِّلُكُمۡ فِيٓ أَعۡيُنِهِمۡ لِيَقۡضِيَ ٱللَّهُ أَمۡرٗا كَانَ مَفۡعُولٗاۗ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ﴿٤٤﴾", "w": [["أنما غنمتم من شيء", "ما أخذتموه من مال الكافر قهراً لهم وغلبة، قليلاً كان أو كثيراً."], ["فأن لله خمسه", "خمس الخمسة أقسام يكون لله والرسول ومن ذُكر بعدهما."], ["ولذي القربى", "قرابة الرسول ﷺ من بني هاشم وبني المطلب."], ["وما أنزلنا على عبدنا", "من الملائكة والآيات."], ["يوم الفرقان", "يوم بدر، السابع عشر من رمضان، إذ فرّق الله فيه بين الحق والباطل."], ["التقى الجمعان", "جمع المؤمنين وجمع الكافرين ببدر."], ["بالعدوة الدنيا", "العدوة: حافة الوادي وجانبه، والدنيا: القريبة إلى المدينة."], ["بالعدوة القصوى", "البعيدة من المدينة، حافة الوادي الأخرى."], ["والركب أسفل منكم", "ركب أبي سفيان، وهي العير التي خرجوا من أجلها."], ["عن بيّنة", "عن حجة ظاهرة."], ["لتنازعتم في الأمر", "اختلفتم."], ["ويقلّلكم في أعينهم", "هذا قبل الالتحام، أما بعده فقد رأوهم مثليهم حتى تتم الهزيمة."]], "m": "نزلت في بيان قسمة الغنائم بعدما حصل فيها من نزاع: واعلموا أنما غنمتم من مال الكفار المحاربين غلبة وقهراً فأن لله خمسه وللرسول ولذي القربى واليتامى والمساكين وابن السبيل، والأربعة الأخماس الباقية للمجاهدين، للراجل سهم وللفارس سهمان لتأثيره في الحرب وحاجة فرسه إلى العلف. فما لله يُنفق في المصالح العامة، كالكعبة وسائر المساجد، وما للرسول ينفقه على عياله، وما لذي القربى لقرابته الذين تحرم عليهم الزكاة لشرفهم، واليتامى والمساكين لفقراء المسلمين، وابن السبيل للمسافرين المنقطعين المحتاجين، إن كنتم آمنتم بالله وما أنزلنا على عبدنا من الملائكة والآيات يوم الفرقان يوم التقى الجمعان ببدر، والله على كل شيء قدير. إذ أنتم بالعدوة الدنيا وهم بالعدوة القصوى والركب أسفل منكم، ولو تواعدتم أنتم والمشركون على اللقاء لاختلفتم في الميعاد لقلّتكم وكثرتهم، ولكن ليقضي الله أمراً كان مفعولاً: نصركم وهزيمة عدوكم، ليهلك بالكفر من هلك عن بيّنة، ويحيا بالإيمان من حيّ عن بيّنة، إذ أراهم الآيات. إذ يريكهم الله في منامك قليلاً، فأخبرت أصحابك فسرّوا ووطّنوا أنفسهم للقتال، ولو أراكهم كثيراً لفشلتم ولتنازعتم، ولكن الله سلّم، إنه عليم بذات الصدور. وإذ يريكموهم إذ التقيتم في أعينكم قليلاً، كأنهم سبعون أو مائة، ويقلّلكم في أعينهم حتى لا يهابوكم، ليقضي الله أمراً كان مفعولاً، وإلى الله تُرجع الأمور.", "h": ["بيان قسمة الغنائم على الوجه الذي رضيه الله تعالى.", "التذكير بالإيمان، إذ هو الطاقة الموجّهة، باعتبار أن المؤمن حي بإيمانه يقدر على الفعل والترك، والكافر ميت فلا يُكلّف.", "فضيلة غزوة بدر وفضل أهلها.", "بيان تدبير الله تعالى في نصر أوليائه وهزيمة أعدائه.", "بيان أن مردّ الأمور نجاحاً وخيبة لله تعالى، ليس لأحد فيها تأثير إلا بإذنه."], "k": "«ولكن الله سلّم»… كم من شر صرفه الله عني بتدبير خفي لم أعلمه إلا بعد حين؟"}, {"lbl": "الآيات ٤٥ – ٤٩", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمۡ فِئَةٗ فَٱثۡبُتُواْ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ ﴿٤٥﴾ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ وَتَذۡهَبَ رِيحُكُمۡۖ وَٱصۡبِرُوٓاْۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ ﴿٤٦﴾ وَلَا تَكُونُواْ كَٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِم بَطَرٗا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۚ وَٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطٞ ﴿٤٧﴾ وَإِذۡ زَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ وَقَالَ لَا غَالِبَ لَكُمُ ٱلۡيَوۡمَ مِنَ ٱلنَّاسِ وَإِنِّي جَارٞ لَّكُمۡۖ فَلَمَّا تَرَآءَتِ ٱلۡفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيۡهِ وَقَالَ إِنِّي بَرِيٓءٞ مِّنكُمۡ إِنِّيٓ أَرَىٰ مَا لَا تَرَوۡنَ إِنِّيٓ أَخَافُ ٱللَّهَۚ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ ﴿٤٨﴾ إِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٌ غَرَّ هَـٰٓؤُلَآءِ دِينُهُمۡۗ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ﴿٤٩﴾", "w": [["فئة", "طائفة مقاتلة."], ["فاثبتوا", "لقتالها واصمدوا."], ["واذكروا الله كثيراً", "مهلّلين مكبّرين، راجين النصر طامعين فيه، سائلين الله تعالى إياه."], ["تفلحون", "تفوزون بالنصر في الدنيا والجنة في الآخرة، بعد النجاة من الهزيمة في الدنيا والنار في الآخرة."], ["ولا تنازعوا", "لا تختلفوا وأنتم في مواجهة العدو أبداً."], ["وتذهب ريحكم", "قوتكم بسبب الخلاف."], ["خرجوا من ديارهم بطراً", "للبطر الذي هو دفع الحق ومنعه."], ["وإني جار لكم", "مجير لكم ومعين على عدوكم."], ["تراءت الفئتان", "التقتا ورأت كل منهما عدوها."], ["نكص على عقبيه", "رجع إلى الوراء هارباً، لأنه جاءهم في صورة سراقة بن مالك."], ["إني أرى ما لا ترون", "من الملائكة."], ["والذين في قلوبهم مرض", "ضعف في إيمانهم وخلل في اعتقادهم."]], "m": "نداء موجّه إلى المؤمنين وقد أُذن لهم في القتال، فهم بحاجة إلى تعليم رباني يعرفون به كيف يخوضون المعارك وينتصرون، وهذه عوامل النصر: الثبات في وجه العدو: يا أيها الذين آمنوا إذا لقيتم فئة فاثبتوا، وذكر الله تهليلاً وتكبيراً ودعاءً: واذكروا الله كثيراً لعلكم تفلحون، وطاعة الله ورسوله، ومنه طاعة قائد المعركة: وأطيعوا الله ورسوله، وعدم التنازع عند التدبير وأثناء الخوض، فنتيجته الفشل وذهاب القوة: ولا تنازعوا فتفشلوا وتذهب ريحكم، والصبر على مواصلة القتال: واصبروا إن الله مع الصابرين، والإخلاص فيه لله: ولا تكونوا كالذين خرجوا من ديارهم بطراً ورئاء الناس ويصدّون عن سبيل الله. ثم ذكّرهم بحادثة غريبة يوم بدر: وإذ زيّن لهم الشيطان أعمالهم، وكان في صورة سراقة بن مالك، وقال: لا غالب لكم اليوم من الناس وإني جار لكم، فلما تراءت الفئتان رأى جبريل في صفوف الملائكة فنكص على عقبيه، وكان آخذاً بيد الحارث بن هشام، فقال له: ما بك؟ فقال وهو هارب: إني بريء منكم، إني أرى ما لا ترون، إني أخاف الله والله شديد العقاب، وصدق وهو كذوب. إذ يقول المنافقون والذين في قلوبهم مرض: غرّ هؤلاء دينهم حتى خرجوا لقريش وهي تفوقهم عدداً وعدة، فلا يفتّ هذا في أعضادكم، ومن يتوكل على الله فإن الله عزيز حكيم يضع النصر في المتأهّلين له.", "h": ["بيان أسباب النصر وعوامله، ووجوب الأخذ بها في كل معركة، وهي: الثبات، وذكر الله تعالى، وطاعة الله ورسوله وطاعة القيادة، وترك النزاع والخلاف، والصبر، والإخلاص.", "بيان عوامل الفشل والخيبة، وهي: النزاع والاختلاف، والبطر، والرياء، والاغترار.", "بيان عمل الشيطان في نفوس الكافرين بتزيينه لهم الحرب، ووعده وتمنيته لهم.", "وجوب التوكل على الله والاعتماد عليه مهما كانت دعاوى المبطلين والمثبّطين."], "k": "«ولا تنازعوا فتفشلوا وتذهب ريحكم»… في بيتي أو عملي، هل أُطفئ الخلاف أم أُشعله؟"}, {"lbl": "الآيات ٥٠ – ٥٤", "q": "وَلَوۡ تَرَىٰٓ إِذۡ يَتَوَفَّى ٱلَّذِينَ كَفَرُواْ ٱلۡمَلَـٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَٰرَهُمۡ وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ ﴿٥٠﴾ ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّـٰمٖ لِّلۡعَبِيدِ ﴿٥١﴾ كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۚ إِنَّ ٱللَّهَ قَوِيّٞ شَدِيدُ ٱلۡعِقَابِ ﴿٥٢﴾ ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمۡ يَكُ مُغَيِّرٗا نِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ﴿٥٣﴾ كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِ رَبِّهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَۚ وَكُلّٞ كَانُواْ ظَٰلِمِينَ ﴿٥٤﴾", "w": [["إذ يتوفّى", "يقبض أرواحهم لإماتتهم."], ["وجوههم وأدبارهم", "يضربونهم من أمامهم ومن خلفهم."], ["بظلّام للعبيد", "ليس بذي ظلم للعبيد، كقوله: «ولا يظلم ربك أحداً»."], ["كدأب آل فرعون", "دأب كفار قريش كدأب آل فرعون في الكفر والتكذيب، والدأب: العادة."], ["لم يك مغيّراً نعمة", "تغيير النعمة: تبديلها بنقمة، بسلبها أو تعذيب أهلها."], ["آل فرعون", "كل من كان على دينه من الأقباط مشاركاً له في ظلمه وكفره."]], "m": "ولو ترى إذ يتوفّى الذين كفروا الملائكة يضربون وجوههم وأدبارهم، ويقولون: وذوقوا عذاب الحريق، لرأيت أمراً فظيعاً، ذلك بما قدّمت أيديكم من الكفر والظلم والفساد، وأن الله ليس بظلّام للعبيد. دأب هؤلاء المشركين كدأب آل فرعون والذين من قبلهم، كفروا بآيات الله فأخذهم الله بذنوبهم، إن الله قوي شديد العقاب، يشهد له فعله بعاد وثمود وقوم إبراهيم وأصحاب مدين والمؤتفكات، وأخيراً أخذه كفار قريش في بدر. ذلك بأن الله لم يك مغيّراً نعمة أنعمها على قوم، كالأمن والرخاء أو الطهر والصفاء، حتى يغيّروا ما بأنفسهم بالكفر والتكذيب والظلم والفسق، وعندئذ يبدّلها نقماً: الخوف والغلاء، والخبث والشر، إن لم يأخذهم بالاستئصال التام، وأن الله سميع عليم فيتم الجزاء عادلاً. كدأب آل فرعون والذين من قبلهم كذّبوا بآيات ربهم فأهلكناهم بذنوبهم وأغرقنا آل فرعون وكلٌّ كانوا ظالمين، وتخالف الآية السابقة في أن الذنب هنا التكذيب، ونوع العذاب الإغراق، وسُجّل على الكل ذنب الظلم.", "h": ["تقرير عذاب القبر، بتقرير العذاب عند النزع.", "هذه الآية نظيرها آية الأنعام: «ولو ترى إذ الظالمون في غمرات الموت والملائكة باسطو أيديهم»، أي بالضرب.", "تنزّه الخالق عز وجل عن الظلم لأحد.", "سنة الله تعالى في أخذ الظالمين، وإبدال النعم بالنقم.", "التنديد بالظلم وأهله، وأنه الذنب الذي يُطلق على سائر الذنوب."], "k": "«حتى يغيّروا ما بأنفسهم»… نعمة أخشى زوالها؛ فهل غيّرت شيئاً في نفسي يهدّدها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (118, 8, 55, 66, 'سورة الأنفال ٥٥ – ٦٦', '«إن شر الدواب»، «وأعدّوا لهم ما استطعتم من قوة»، «وإن جنحوا للسلم»، و«حسبك الله»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 118) = $j$[{"lbl": "الآيات ٥٥ – ٥٩", "q": "إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُواْ فَهُمۡ لَا يُؤۡمِنُونَ ﴿٥٥﴾ ٱلَّذِينَ عَٰهَدتَّ مِنۡهُمۡ ثُمَّ يَنقُضُونَ عَهۡدَهُمۡ فِي كُلِّ مَرَّةٖ وَهُمۡ لَا يَتَّقُونَ ﴿٥٦﴾ فَإِمَّا تَثۡقَفَنَّهُمۡ فِي ٱلۡحَرۡبِ فَشَرِّدۡ بِهِم مَّنۡ خَلۡفَهُمۡ لَعَلَّهُمۡ يَذَّكَّرُونَ ﴿٥٧﴾ وَإِمَّا تَخَافَنَّ مِن قَوۡمٍ خِيَانَةٗ فَٱنۢبِذۡ إِلَيۡهِمۡ عَلَىٰ سَوَآءٍۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡخَآئِنِينَ ﴿٥٨﴾ وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُواْ سَبَقُوٓاْۚ إِنَّهُمۡ لَا يُعۡجِزُونَ ﴿٥٩﴾", "w": [["شر الدواب", "من إنسان أو حيوان: الذين ذكر الله وصفهم، وهم بنو قريظة."], ["الخائنين", "الغادرين بعهودهم."], ["سبقوا", "فاتوا الله ولم يتمكّن منهم."]], "m": "بمناسبة ذكر خصوم الدعوة، ذكر الله خصماً آخر غير مشركي قريش، وهم بنو قريظة من اليهود: إن شر الدواب عند الله في حكمه وعلمه الذين كفروا فهم لا يؤمنون لتوغّلهم في الشر، الذين عاهدت منهم ثم ينقضون عهدهم في كل مرة وهم لا يتقون عاقبة النقض: عاهدهم النبي ﷺ ألا يحاربوه ولا يعينوا عليه، فأعانوا قريشاً بالسلاح، ثم اعتذروا وعاهدوا ثانية، فنقضوا وانضمّوا إلى الأحزاب في الخندق. فإما تثقفنّهم في الحرب فاضربهم بعنف وشدة حتى تشرّد بهم من خلفهم من أعداء الإسلام المتربّصين لعلهم يذّكّرون فلا يفكّروا في حربك، ويشهد لكفرهم أنهم لما نزلوا من حصونهم مستسلمين كان يُعرض على أحدهم الإسلام فيؤثر القتل عليه. وإما تخافنّ من قوم معاهدين خيانة ظهرت أماراتها، فانبذ إليهم على سواء: اطرح المعاهدة معلناً إلغاءها حتى لا يتّهموك بالغدر، إن الله لا يحب الخائنين، وهذا من الحزم، لافتكاك عنصر المباغتة من يد العدو. ولا يحسبنّ الذين كفروا ممن هرب من بدر أنهم سبقوا وفاتوا، إنهم لا يعجزون الله بحال.", "h": ["بيان أن شر الدواب هم الكفار من أهل الكتاب والمشركين، بل هم شر البرية.", "سنة الله فيمن توغّل في الظلم والشر والفساد: يُحرم التوبة فلا يموت إلا كافراً.", "من السياسة الحربية النافعة أن يضرب القائد عدوه بعنف وشدة ليكون نكالاً لغيره.", "جواز إعلان إلغاء المعاهدة وضرب العدو إن بدرت منه بوادر واضحة بأنه عازم على نقضها."], "k": "«إن الله لا يحب الخائنين»… حتى مع العدو لا غدر؛ فكيف بعهودي مع أهلي وأصحابي؟"}, {"lbl": "الآيات ٦٠ – ٦٣", "q": "وَأَعِدُّواْ لَهُم مَّا ٱسۡتَطَعۡتُم مِّن قُوَّةٖ وَمِن رِّبَاطِ ٱلۡخَيۡلِ تُرۡهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمۡ وَءَاخَرِينَ مِن دُونِهِمۡ لَا تَعۡلَمُونَهُمُ ٱللَّهُ يَعۡلَمُهُمۡۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فِي سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ ﴿٦٠﴾ ۞وَإِن جَنَحُواْ لِلسَّلۡمِ فَٱجۡنَحۡ لَهَا وَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٦١﴾ وَإِن يُرِيدُوٓاْ أَن يَخۡدَعُوكَ فَإِنَّ حَسۡبَكَ ٱللَّهُۚ هُوَ ٱلَّذِيٓ أَيَّدَكَ بِنَصۡرِهِۦ وَبِٱلۡمُؤۡمِنِينَ ﴿٦٢﴾ وَأَلَّفَ بَيۡنَ قُلُوبِهِمۡۚ لَوۡ أَنفَقۡتَ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا مَّآ أَلَّفۡتَ بَيۡنَ قُلُوبِهِمۡ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيۡنَهُمۡۚ إِنَّهُۥ عَزِيزٌ حَكِيمٞ ﴿٦٣﴾", "w": [["وأعدّوا", "هيّئوا وأحضروا."], ["من قوة", "قوة حربية من سلاح على اختلاف أنواعه."], ["يوفّ إليكم", "أجره وثوابه."], ["وإن جنحوا للسلم", "مالوا إلى عدم الحرب ورغبوا في ذلك."]], "m": "بعد هزيمة المشركين في بدر وعودتهم إلى مكة متغيّظين، وأخذ أبو سفيان يُعدّ العدة للانتقام، وما كانت أحد إلا نتيجة ذلك، أمر الله بإعداد القوة: وأعدّوا لهم ما استطعتم من قوة، وفسّرها النبي ﷺ بقوله: «ألا إن القوة الرمي» قالها ثلاثاً، ومن رباط الخيل معدّة للجهاد ترهبون به عدو الله وعدوكم فلا يفكّروا في غزوكم، وهذا ما يُعرف بالسلم المسلّح، فالأمة القادرة يرهبها أعداؤها، والعاجزة يغريهم عجزها بقتالها، وآخرين من دونهم لا تعلمونهم الله يعلمهم، يجوز أن يكونوا اليهود أو المجوس أو المنافقين أو الجن، ولا يُجزم بهم ما دام الله لم يسمّهم. وما تنفقوا من شيء في سبيل الله يوفّ إليكم كاملاً وأنتم لا تُظلمون. وإن جنحوا للسلم بصدق فاجنح لها، فهو ﷺ رسول رحمة، وتوكّل على الله إنه هو السميع العليم، وإن يريدوا أن يخدعوك بطلب السلم فإن حسبك الله، هو الذي أيّدك بنصره في بدر وبالمؤمنين، وألّف بين قلوبهم المتنافرة، فقد كان الأنصار في حرب بينهم مائة وعشرين سنة، فلما أسلموا اصطلحوا وأصبحوا جسماً واحداً، لو أنفقت ما في الأرض جميعاً ما ألّفت بين قلوبهم، ولكن الله ألّف بينهم إنه عزيز حكيم.", "h": ["وجوب إعداد القوة، وهي في كل زمان بحسبه، فإن كانت في الماضي الرمح والسيف ورباط الخيل، فهي اليوم النفّاثة المقاتلة والصاروخ والهيدروجين والدبابة والغواصة.", "تقرير مبدأ السلم المسلّح.", "لا يخلو المسلمون من أعداء ما داموا بحق مسلمين، لأن قوى الشر من إنس وجن لا ترضى بالحق.", "نفقة الجهاد خير نفقة، وهي مضمونة التضعيف."], "k": "«ولكن الله ألّف بينهم»… قلب بعيد عني أريد صلاحه؛ هل أطلب تأليفه من ربي قبل كل وسيلة؟"}, {"lbl": "الآيات ٦٤ – ٦٦", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ حَسۡبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿٦٤﴾ يَـٰٓأَيُّهَا ٱلنَّبِيُّ حَرِّضِ ٱلۡمُؤۡمِنِينَ عَلَى ٱلۡقِتَالِۚ إِن يَكُن مِّنكُمۡ عِشۡرُونَ صَٰبِرُونَ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُم مِّاْئَةٞ يَغۡلِبُوٓاْ أَلۡفٗا مِّنَ ٱلَّذِينَ كَفَرُواْ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ ﴿٦٥﴾ ٱلۡـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمۡ وَعَلِمَ أَنَّ فِيكُمۡ ضَعۡفٗاۚ فَإِن يَكُن مِّنكُم مِّاْئَةٞ صَابِرَةٞ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُمۡ أَلۡفٞ يَغۡلِبُوٓاْ أَلۡفَيۡنِ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِينَ ﴿٦٦﴾", "w": [["حسبك الله", "كافيك الله كل ما يهمّك من شأن أعدائك وغيرهم."], ["ومن اتبعك من المؤمنين", "الله حسبهم كذلك، أي كافيهم ما يهمّهم."], ["حرّض المؤمنين على القتال", "حثّهم على القتال مرغّباً لهم مرهّباً."], ["صابرون", "على القتال، فلا يضعفون ولا ينهزمون بل يثبتون."], ["لا يفقهون", "لا يعرفون أسرار القتال ونتائجه بعده، ولا فنونه وحذق أساليبه."]], "m": "يا أيها النبي حسبك الله وحسب من اتبعك من المؤمنين. ثم يناديه ليأمره بالأخذ بأسباب النصر: يا أيها النبي حرّض المؤمنين على القتال، إن يكن منكم عشرون صابرون يغلبوا مائتين، وإن يكن منكم مائة يغلبوا ألفاً من الذين كفروا، بأنهم قوم لا يفقهون أسرار القتال: أن يُعبد الله ويُرفع الظلم ويتخذ الله من المؤمنين شهداء، فهم يقاتلون لأجل حياتهم فإذا خافوا عليها تركوا القتال، والمؤمنون علماء بكل شيء، هذا هو المفروض، وإن ضعف الإيمان ضعف تبعاً له الفقه والعلم كما هو مشاهد اليوم. الآن خفّف الله عنكم وعلم أن فيكم ضعفاً، فإن يكن منكم مائة صابرة يغلبوا مائتين، وإن يكن منكم ألف يغلبوا ألفين بإذن الله، فنسخ الحكم الأول بالثاني: فلا يجوز للمؤمن أن يفرّ من اثنين، ويجوز أن يفرّ مما فوق ذلك، رفعاً للحرج، وإلا فقد قاتل ثلاثة آلاف صحابي يوم مؤتة مائة وخمسين ألفاً، والله مع الصابرين بالتأييد والنصر، فمن لم يصبر فليس له على الله وعد بنصره.", "h": ["لا كافي إلا الله تعالى، ومن زعم أن هناك من يكفي سوى الله تعالى فقد أشرك.", "وجوب تحريض المؤمنين على الجهاد وحثّهم عليه في كل زمان ومكان.", "حرمة هزيمة الواحد من الواحد، والواحد من الاثنين، ويجوز ما فوق ذلك.", "وجوب الصبر في ساحة المعارك، وتحرم الهزيمة إذا كان عدد المؤمنين اثني عشر ألف مقاتل أو أكثر، إذ هذا العدد لا يُغلب من قلة بإذن الله تعالى.", "معية الله بالعلم والتأييد والنصر للصابرين دون الجزعين."], "k": "«يا أيها النبي حسبك الله»… إذا كان الله حسبي، فممّ أخاف اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 118;
insert into public.tdb_cards(topic, i, body) select 118, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٥ – ٥٩", "q": "إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُواْ فَهُمۡ لَا يُؤۡمِنُونَ ﴿٥٥﴾ ٱلَّذِينَ عَٰهَدتَّ مِنۡهُمۡ ثُمَّ يَنقُضُونَ عَهۡدَهُمۡ فِي كُلِّ مَرَّةٖ وَهُمۡ لَا يَتَّقُونَ ﴿٥٦﴾ فَإِمَّا تَثۡقَفَنَّهُمۡ فِي ٱلۡحَرۡبِ فَشَرِّدۡ بِهِم مَّنۡ خَلۡفَهُمۡ لَعَلَّهُمۡ يَذَّكَّرُونَ ﴿٥٧﴾ وَإِمَّا تَخَافَنَّ مِن قَوۡمٍ خِيَانَةٗ فَٱنۢبِذۡ إِلَيۡهِمۡ عَلَىٰ سَوَآءٍۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡخَآئِنِينَ ﴿٥٨﴾ وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُواْ سَبَقُوٓاْۚ إِنَّهُمۡ لَا يُعۡجِزُونَ ﴿٥٩﴾", "w": [["شر الدواب", "من إنسان أو حيوان: الذين ذكر الله وصفهم، وهم بنو قريظة."], ["الخائنين", "الغادرين بعهودهم."], ["سبقوا", "فاتوا الله ولم يتمكّن منهم."]], "m": "بمناسبة ذكر خصوم الدعوة، ذكر الله خصماً آخر غير مشركي قريش، وهم بنو قريظة من اليهود: إن شر الدواب عند الله في حكمه وعلمه الذين كفروا فهم لا يؤمنون لتوغّلهم في الشر، الذين عاهدت منهم ثم ينقضون عهدهم في كل مرة وهم لا يتقون عاقبة النقض: عاهدهم النبي ﷺ ألا يحاربوه ولا يعينوا عليه، فأعانوا قريشاً بالسلاح، ثم اعتذروا وعاهدوا ثانية، فنقضوا وانضمّوا إلى الأحزاب في الخندق. فإما تثقفنّهم في الحرب فاضربهم بعنف وشدة حتى تشرّد بهم من خلفهم من أعداء الإسلام المتربّصين لعلهم يذّكّرون فلا يفكّروا في حربك، ويشهد لكفرهم أنهم لما نزلوا من حصونهم مستسلمين كان يُعرض على أحدهم الإسلام فيؤثر القتل عليه. وإما تخافنّ من قوم معاهدين خيانة ظهرت أماراتها، فانبذ إليهم على سواء: اطرح المعاهدة معلناً إلغاءها حتى لا يتّهموك بالغدر، إن الله لا يحب الخائنين، وهذا من الحزم، لافتكاك عنصر المباغتة من يد العدو. ولا يحسبنّ الذين كفروا ممن هرب من بدر أنهم سبقوا وفاتوا، إنهم لا يعجزون الله بحال.", "h": ["بيان أن شر الدواب هم الكفار من أهل الكتاب والمشركين، بل هم شر البرية.", "سنة الله فيمن توغّل في الظلم والشر والفساد: يُحرم التوبة فلا يموت إلا كافراً.", "من السياسة الحربية النافعة أن يضرب القائد عدوه بعنف وشدة ليكون نكالاً لغيره.", "جواز إعلان إلغاء المعاهدة وضرب العدو إن بدرت منه بوادر واضحة بأنه عازم على نقضها."], "k": "«إن الله لا يحب الخائنين»… حتى مع العدو لا غدر؛ فكيف بعهودي مع أهلي وأصحابي؟"}, {"lbl": "الآيات ٦٠ – ٦٣", "q": "وَأَعِدُّواْ لَهُم مَّا ٱسۡتَطَعۡتُم مِّن قُوَّةٖ وَمِن رِّبَاطِ ٱلۡخَيۡلِ تُرۡهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمۡ وَءَاخَرِينَ مِن دُونِهِمۡ لَا تَعۡلَمُونَهُمُ ٱللَّهُ يَعۡلَمُهُمۡۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فِي سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ ﴿٦٠﴾ ۞وَإِن جَنَحُواْ لِلسَّلۡمِ فَٱجۡنَحۡ لَهَا وَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٦١﴾ وَإِن يُرِيدُوٓاْ أَن يَخۡدَعُوكَ فَإِنَّ حَسۡبَكَ ٱللَّهُۚ هُوَ ٱلَّذِيٓ أَيَّدَكَ بِنَصۡرِهِۦ وَبِٱلۡمُؤۡمِنِينَ ﴿٦٢﴾ وَأَلَّفَ بَيۡنَ قُلُوبِهِمۡۚ لَوۡ أَنفَقۡتَ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا مَّآ أَلَّفۡتَ بَيۡنَ قُلُوبِهِمۡ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيۡنَهُمۡۚ إِنَّهُۥ عَزِيزٌ حَكِيمٞ ﴿٦٣﴾", "w": [["وأعدّوا", "هيّئوا وأحضروا."], ["من قوة", "قوة حربية من سلاح على اختلاف أنواعه."], ["يوفّ إليكم", "أجره وثوابه."], ["وإن جنحوا للسلم", "مالوا إلى عدم الحرب ورغبوا في ذلك."]], "m": "بعد هزيمة المشركين في بدر وعودتهم إلى مكة متغيّظين، وأخذ أبو سفيان يُعدّ العدة للانتقام، وما كانت أحد إلا نتيجة ذلك، أمر الله بإعداد القوة: وأعدّوا لهم ما استطعتم من قوة، وفسّرها النبي ﷺ بقوله: «ألا إن القوة الرمي» قالها ثلاثاً، ومن رباط الخيل معدّة للجهاد ترهبون به عدو الله وعدوكم فلا يفكّروا في غزوكم، وهذا ما يُعرف بالسلم المسلّح، فالأمة القادرة يرهبها أعداؤها، والعاجزة يغريهم عجزها بقتالها، وآخرين من دونهم لا تعلمونهم الله يعلمهم، يجوز أن يكونوا اليهود أو المجوس أو المنافقين أو الجن، ولا يُجزم بهم ما دام الله لم يسمّهم. وما تنفقوا من شيء في سبيل الله يوفّ إليكم كاملاً وأنتم لا تُظلمون. وإن جنحوا للسلم بصدق فاجنح لها، فهو ﷺ رسول رحمة، وتوكّل على الله إنه هو السميع العليم، وإن يريدوا أن يخدعوك بطلب السلم فإن حسبك الله، هو الذي أيّدك بنصره في بدر وبالمؤمنين، وألّف بين قلوبهم المتنافرة، فقد كان الأنصار في حرب بينهم مائة وعشرين سنة، فلما أسلموا اصطلحوا وأصبحوا جسماً واحداً، لو أنفقت ما في الأرض جميعاً ما ألّفت بين قلوبهم، ولكن الله ألّف بينهم إنه عزيز حكيم.", "h": ["وجوب إعداد القوة، وهي في كل زمان بحسبه، فإن كانت في الماضي الرمح والسيف ورباط الخيل، فهي اليوم النفّاثة المقاتلة والصاروخ والهيدروجين والدبابة والغواصة.", "تقرير مبدأ السلم المسلّح.", "لا يخلو المسلمون من أعداء ما داموا بحق مسلمين، لأن قوى الشر من إنس وجن لا ترضى بالحق.", "نفقة الجهاد خير نفقة، وهي مضمونة التضعيف."], "k": "«ولكن الله ألّف بينهم»… قلب بعيد عني أريد صلاحه؛ هل أطلب تأليفه من ربي قبل كل وسيلة؟"}, {"lbl": "الآيات ٦٤ – ٦٦", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ حَسۡبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ ﴿٦٤﴾ يَـٰٓأَيُّهَا ٱلنَّبِيُّ حَرِّضِ ٱلۡمُؤۡمِنِينَ عَلَى ٱلۡقِتَالِۚ إِن يَكُن مِّنكُمۡ عِشۡرُونَ صَٰبِرُونَ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُم مِّاْئَةٞ يَغۡلِبُوٓاْ أَلۡفٗا مِّنَ ٱلَّذِينَ كَفَرُواْ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ ﴿٦٥﴾ ٱلۡـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمۡ وَعَلِمَ أَنَّ فِيكُمۡ ضَعۡفٗاۚ فَإِن يَكُن مِّنكُم مِّاْئَةٞ صَابِرَةٞ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُمۡ أَلۡفٞ يَغۡلِبُوٓاْ أَلۡفَيۡنِ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِينَ ﴿٦٦﴾", "w": [["حسبك الله", "كافيك الله كل ما يهمّك من شأن أعدائك وغيرهم."], ["ومن اتبعك من المؤمنين", "الله حسبهم كذلك، أي كافيهم ما يهمّهم."], ["حرّض المؤمنين على القتال", "حثّهم على القتال مرغّباً لهم مرهّباً."], ["صابرون", "على القتال، فلا يضعفون ولا ينهزمون بل يثبتون."], ["لا يفقهون", "لا يعرفون أسرار القتال ونتائجه بعده، ولا فنونه وحذق أساليبه."]], "m": "يا أيها النبي حسبك الله وحسب من اتبعك من المؤمنين. ثم يناديه ليأمره بالأخذ بأسباب النصر: يا أيها النبي حرّض المؤمنين على القتال، إن يكن منكم عشرون صابرون يغلبوا مائتين، وإن يكن منكم مائة يغلبوا ألفاً من الذين كفروا، بأنهم قوم لا يفقهون أسرار القتال: أن يُعبد الله ويُرفع الظلم ويتخذ الله من المؤمنين شهداء، فهم يقاتلون لأجل حياتهم فإذا خافوا عليها تركوا القتال، والمؤمنون علماء بكل شيء، هذا هو المفروض، وإن ضعف الإيمان ضعف تبعاً له الفقه والعلم كما هو مشاهد اليوم. الآن خفّف الله عنكم وعلم أن فيكم ضعفاً، فإن يكن منكم مائة صابرة يغلبوا مائتين، وإن يكن منكم ألف يغلبوا ألفين بإذن الله، فنسخ الحكم الأول بالثاني: فلا يجوز للمؤمن أن يفرّ من اثنين، ويجوز أن يفرّ مما فوق ذلك، رفعاً للحرج، وإلا فقد قاتل ثلاثة آلاف صحابي يوم مؤتة مائة وخمسين ألفاً، والله مع الصابرين بالتأييد والنصر، فمن لم يصبر فليس له على الله وعد بنصره.", "h": ["لا كافي إلا الله تعالى، ومن زعم أن هناك من يكفي سوى الله تعالى فقد أشرك.", "وجوب تحريض المؤمنين على الجهاد وحثّهم عليه في كل زمان ومكان.", "حرمة هزيمة الواحد من الواحد، والواحد من الاثنين، ويجوز ما فوق ذلك.", "وجوب الصبر في ساحة المعارك، وتحرم الهزيمة إذا كان عدد المؤمنين اثني عشر ألف مقاتل أو أكثر، إذ هذا العدد لا يُغلب من قلة بإذن الله تعالى.", "معية الله بالعلم والتأييد والنصر للصابرين دون الجزعين."], "k": "«يا أيها النبي حسبك الله»… إذا كان الله حسبي، فممّ أخاف اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (119, 8, 67, 75, 'سورة الأنفال ٦٧ – ٧٥', 'أسرى بدر: «تريدون عرض الدنيا والله يريد الآخرة»، و«إن يعلم الله في قلوبكم خيراً»، وأصناف المؤمنين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 119) = $j$[{"lbl": "الآيات ٦٧ – ٦٩", "q": "مَا كَانَ لِنَبِيٍّ أَن يَكُونَ لَهُۥٓ أَسۡرَىٰ حَتَّىٰ يُثۡخِنَ فِي ٱلۡأَرۡضِۚ تُرِيدُونَ عَرَضَ ٱلدُّنۡيَا وَٱللَّهُ يُرِيدُ ٱلۡأٓخِرَةَۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ ﴿٦٧﴾ لَّوۡلَا كِتَٰبٞ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمۡ فِيمَآ أَخَذۡتُمۡ عَذَابٌ عَظِيمٞ ﴿٦٨﴾ فَكُلُواْ مِمَّا غَنِمۡتُمۡ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٦٩﴾", "w": [["أسرى", "جمع أسير، وأُطلق لفظ الأسير على كل من أُخذ في الحرب."], ["حتى يُثخن في الأرض", "حتى تكون له قوة وشدة يرهب بها العدو."], ["عرض الدنيا", "المال، لأنه عارض يزول فلا يبقى."], ["لولا كتاب من الله سبق", "كتاب المقادير، بأن الله أحل لهذه الأمة الغنائم."], ["فيما أخذتم", "بسبب ما أخذتم من فداء أسرى بدر."], ["حلالاً طيباً", "الحلال هو الطيب، فكلمة «طيباً» تأكيد لحلّية اقتضاها المقام."], ["واتقوا الله", "بطاعته وطاعة رسوله في الأمر والنهي."]], "m": "ما زال السياق في أحداث بدر: رغب أصحاب الرسول ﷺ، إلا عمر وسعد بن معاذ، في مفاداة الأسرى بالمال للظروف المعاشية القاسية، بدون علم من الله بحلّها أو حرمتها، أما عمر فكان لا يعثر على أسير إلا قتله، وقال سعد: الإثخان في القتل أولى من استبقاء الرجال، فلما تم الفداء نزلت تعاتبهم: ما كان لنبي أن يكون له أسرى يُبقيهم ليفاديهم أو يمنّ عليهم حتى يُثخن في أرض العدو قتلاً وتشريداً، فإذا هابه الأعداء جاز له ذلك، تريدون عرض الدنيا من المال، والله يريد الآخرة، فشتان ما بين مرادكم ومراد ربكم لكم، والله عزيز حكيم. لولا كتاب من الله سبق في اللوح المحفوظ بحلّ الغنائم لهذه الأمة لمسّكم فيما أخذتم من الفداء عذاب عظيم. فكلوا مما غنمتم حلالاً طيباً، إذن لأهل بدر حتى فيما فادوا به الأسرى، واتقوا الله، إن الله غفور رحيم، وتجلّى ذلك في رفع العذاب عنهم، وفي الحديث: «لعل الله اطّلع على أهل بدر فقال: اعملوا ما شئتم فقد غفرت لكم».", "h": ["إرشاد الله تعالى لقادة الأمة الإسلامية في الجهاد ألّا يفادوا الأسرى ولا يمنّوا عليهم بإطلاقهم إلا بعد أن يثخنوا في أرض العدو قتلاً وتشريداً، فإذا خافهم العدو ورهبهم أمكنهم أن يفادوا الأسرى أو يمنّوا عليهم.", "التزهيد في الرغبة في الدنيا لحقارتها، والترغيب في الآخرة لعظم أجرها.", "إباحة الغنائم."], "k": "«تريدون عرض الدنيا والله يريد الآخرة»… حين أختار بين أمرين، أيّ الإرادتين أقدّم؟"}, {"lbl": "الآيتان ٧٠ – ٧١", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّمَن فِيٓ أَيۡدِيكُم مِّنَ ٱلۡأَسۡرَىٰٓ إِن يَعۡلَمِ ٱللَّهُ فِي قُلُوبِكُمۡ خَيۡرٗا يُؤۡتِكُمۡ خَيۡرٗا مِّمَّآ أُخِذَ مِنكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٧٠﴾ وَإِن يُرِيدُواْ خِيَانَتَكَ فَقَدۡ خَانُواْ ٱللَّهَ مِن قَبۡلُ فَأَمۡكَنَ مِنۡهُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ ﴿٧١﴾", "w": [["من الأسرى", "أسرى بدر الذين أُخذ منهم الفداء، كالعباس بن عبد المطلب رضي الله عنه."], ["إن يعلم الله في قلوبكم خيراً", "إيماناً صادقاً وإخلاصاً تاماً."], ["مما أُخذ منكم", "من مال الفداء."], ["وإن يريدوا خيانتك", "أي الأسرى."], ["فقد خانوا الله من قبل", "من قبل وقوعهم في الأسر، بكفرهم في مكة."], ["فأمكن منهم", "أمكنكم أنتم أيها المؤمنون منهم فقتلتموهم وأسرتموهم."], ["والله عليم حكيم", "عليم بخلقه، حكيم في صنعه وتدبيره."]], "m": "نزلت في العباس بن عبد المطلب رضي الله عنه، فإنه بعد أن وقع في الأسر أسلم، وطلب من الرسول ﷺ أن يرد عليه ما أُخذ منه من فدية، فأبى، فأنزل الله: يا أيها النبي قل لمن في أيديكم من الأسرى: إن يعلم الله في قلوبكم خيراً، إسلاماً حقيقياً، يؤتكم مالاً خيراً مما أُخذ منكم، ويغفر لكم ذنوبكم التي كانت كفراً ثم حرباً على الله ورسوله، والله غفور رحيم. وإن يريد هؤلاء الأسرى الذين أظهروا إسلامهم خيانتك والعودة إلى كفرهم إذا رجعوا إلى ديارهم، فلا تبالِ بهم، فقد خانوا الله من قبل بكفرهم، فأمكن المؤمنين منهم وجعلهم في قبضتهم، ولو عادوا لأمكنكم منهم ثانية، والله عليم بنياتهم حكيم فيما يحكم به عليهم، فليحسنوا إسلامهم ويصدقوا في إيمانهم فذلك خير لهم.", "h": ["فضل العباس عم رسول الله ﷺ لنزول الآية في حقه وشأنه.", "فضل إضمار الخير والنيات الصالحة.", "إطلاق لفظ الخير على الإسلام والقرآن، وحقاً هما الخير والخير كله.", "ما ترك عبد شيئاً لله إلا عوّضه خيراً منه.", "الله جل جلاله لا يغلبه غالب ولا يفوته هارب، ألا فليُتّقَ وليُتوكّل عليه."], "k": "«إن يعلم الله في قلوبكم خيراً يؤتكم خيراً»… ماذا يعلم الله في قلبي الآن؟"}, {"lbl": "الآيات ٧٢ – ٧٥", "q": "إِنَّ ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَـٰٓئِكَ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَٱلَّذِينَ ءَامَنُواْ وَلَمۡ يُهَاجِرُواْ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَيۡءٍ حَتَّىٰ يُهَاجِرُواْۚ وَإِنِ ٱسۡتَنصَرُوكُمۡ فِي ٱلدِّينِ فَعَلَيۡكُمُ ٱلنَّصۡرُ إِلَّا عَلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿٧٢﴾ وَٱلَّذِينَ كَفَرُواْ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٍۚ إِلَّا تَفۡعَلُوهُ تَكُن فِتۡنَةٞ فِي ٱلۡأَرۡضِ وَفَسَادٞ كَبِيرٞ ﴿٧٣﴾ وَٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَـٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ﴿٧٤﴾ وَٱلَّذِينَ ءَامَنُواْ مِنۢ بَعۡدُ وَهَاجَرُواْ وَجَٰهَدُواْ مَعَكُمۡ فَأُوْلَـٰٓئِكَ مِنكُمۡۚ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمُۢ ﴿٧٥﴾", "w": [["آمنوا", "صدّقوا الله ورسوله، وآمنوا بلقاء الله، وصدّقوا بوعده ووعيده."], ["وهاجروا", "تركوا ديارهم والتحقوا برسول الله ﷺ بالمدينة المنورة."], ["في سبيل الله", "من أجل أن يُعبد الله ولا يُعبد معه غيره، وهو الإسلام."], ["آووا", "آووا المهاجرين فضمّوهم إلى ديارهم، ونصروهم على أعدائهم."], ["وإن استنصروكم", "طلبوا منكم نصرتهم على أعدائهم."], ["ميثاق", "عهد، أي معاهدة سلم وعدم اعتداء."], ["إلا تفعلوه", "إن لم توالوا المسلمين وتقاطعوا الكافرين تكن فتنة."], ["أولو الأرحام", "الأقارب من ذوي النسب."], ["بعضهم أولى ببعض", "في التوارث، أي يرث بعضهم بعضاً."]], "m": "بمناسبة انتهاء أحداث بدر، ذكر الله حال المؤمنين وتفاوتهم في الكمال: الصنف الأول: الذين آمنوا وهاجروا وجاهدوا بأموالهم وأنفسهم في سبيل الله، والثاني: الذين آووا الرسول ﷺ والمهاجرين ونصروهم، وهما أكمل المؤمنين، أولئك بعضهم أولياء بعض في النصرة والموالاة والتوارث، ثم نُسخ التوارث بآخر آية في السياق. والصنف الثالث: الذين آمنوا ولم يهاجروا، ورضوا بالبقاء بين ظهراني الكافرين، فهم ناقصون، ما لكم من ولايتهم من شيء، فلا توارث ولا موالاة حتى يهاجروا، وإن استنصروكم في الدين فعليكم النصر، إلا على قوم بينكم وبينهم ميثاق فأوفوا بعهدكم ولا تغدروا، والله بما تعملون بصير. والذين كفروا بعضهم أولياء بعض يتناصرون ويتوارثون، إلا تفعلوه، من موالاة المؤمنين ومعاداة الكافرين، تكن فتنة في الأرض، وهي الشرك، وفساد كبير، وهو المعاصي. ثم أعاد ذكر الصنف الأول ليذكر جزاءه: أولئك هم المؤمنون حقاً، لهم مغفرة ورزق كريم في الجنة. والصنف الرابع: الذين آمنوا من بعد وهاجروا وجاهدوا معكم فأولئك منكم، دون الأولين لسبقهم، وألحقهم الله بهم. وأولو الأرحام بعضهم أولى ببعض في الإرث، وبها نُسخ التوارث بالهجرة والمعاقدة، واستقر الإرث بالمصاهرة والولاء والنسب، في كتاب الله، إن الله بكل شيء عليم.", "h": ["بيان تفاوت المؤمنين في كمالاتهم وعلو درجاتهم عند ربهم.", "أكمل المؤمنين الذين جمعوا بين الإيمان والهجرة والجهاد وسبقوا لذلك، وهم المهاجرون الأولون، والذين جمعوا بين الإيمان والإيواء والنصرة والجهاد، وهم الأنصار.", "دون ذلك من آمنوا وهاجروا وجاهدوا ولكن بعد صلح الحديبية.", "أدنى أصناف المؤمنين من آمنوا ولم يهاجروا، وهؤلاء على خطر عظيم.", "وجوب نصرة المؤمنين بموالاتهم ومحبتهم، ووجوب معاداة الكافرين وخذلانهم."], "k": "«أولئك هم المؤمنون حقاً»… بأي عمل أقترب من هذا الوصف: إيواء، أو نصرة، أو بذل؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 119;
insert into public.tdb_cards(topic, i, body) select 119, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٧ – ٦٩", "q": "مَا كَانَ لِنَبِيٍّ أَن يَكُونَ لَهُۥٓ أَسۡرَىٰ حَتَّىٰ يُثۡخِنَ فِي ٱلۡأَرۡضِۚ تُرِيدُونَ عَرَضَ ٱلدُّنۡيَا وَٱللَّهُ يُرِيدُ ٱلۡأٓخِرَةَۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ ﴿٦٧﴾ لَّوۡلَا كِتَٰبٞ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمۡ فِيمَآ أَخَذۡتُمۡ عَذَابٌ عَظِيمٞ ﴿٦٨﴾ فَكُلُواْ مِمَّا غَنِمۡتُمۡ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٦٩﴾", "w": [["أسرى", "جمع أسير، وأُطلق لفظ الأسير على كل من أُخذ في الحرب."], ["حتى يُثخن في الأرض", "حتى تكون له قوة وشدة يرهب بها العدو."], ["عرض الدنيا", "المال، لأنه عارض يزول فلا يبقى."], ["لولا كتاب من الله سبق", "كتاب المقادير، بأن الله أحل لهذه الأمة الغنائم."], ["فيما أخذتم", "بسبب ما أخذتم من فداء أسرى بدر."], ["حلالاً طيباً", "الحلال هو الطيب، فكلمة «طيباً» تأكيد لحلّية اقتضاها المقام."], ["واتقوا الله", "بطاعته وطاعة رسوله في الأمر والنهي."]], "m": "ما زال السياق في أحداث بدر: رغب أصحاب الرسول ﷺ، إلا عمر وسعد بن معاذ، في مفاداة الأسرى بالمال للظروف المعاشية القاسية، بدون علم من الله بحلّها أو حرمتها، أما عمر فكان لا يعثر على أسير إلا قتله، وقال سعد: الإثخان في القتل أولى من استبقاء الرجال، فلما تم الفداء نزلت تعاتبهم: ما كان لنبي أن يكون له أسرى يُبقيهم ليفاديهم أو يمنّ عليهم حتى يُثخن في أرض العدو قتلاً وتشريداً، فإذا هابه الأعداء جاز له ذلك، تريدون عرض الدنيا من المال، والله يريد الآخرة، فشتان ما بين مرادكم ومراد ربكم لكم، والله عزيز حكيم. لولا كتاب من الله سبق في اللوح المحفوظ بحلّ الغنائم لهذه الأمة لمسّكم فيما أخذتم من الفداء عذاب عظيم. فكلوا مما غنمتم حلالاً طيباً، إذن لأهل بدر حتى فيما فادوا به الأسرى، واتقوا الله، إن الله غفور رحيم، وتجلّى ذلك في رفع العذاب عنهم، وفي الحديث: «لعل الله اطّلع على أهل بدر فقال: اعملوا ما شئتم فقد غفرت لكم».", "h": ["إرشاد الله تعالى لقادة الأمة الإسلامية في الجهاد ألّا يفادوا الأسرى ولا يمنّوا عليهم بإطلاقهم إلا بعد أن يثخنوا في أرض العدو قتلاً وتشريداً، فإذا خافهم العدو ورهبهم أمكنهم أن يفادوا الأسرى أو يمنّوا عليهم.", "التزهيد في الرغبة في الدنيا لحقارتها، والترغيب في الآخرة لعظم أجرها.", "إباحة الغنائم."], "k": "«تريدون عرض الدنيا والله يريد الآخرة»… حين أختار بين أمرين، أيّ الإرادتين أقدّم؟"}, {"lbl": "الآيتان ٧٠ – ٧١", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّمَن فِيٓ أَيۡدِيكُم مِّنَ ٱلۡأَسۡرَىٰٓ إِن يَعۡلَمِ ٱللَّهُ فِي قُلُوبِكُمۡ خَيۡرٗا يُؤۡتِكُمۡ خَيۡرٗا مِّمَّآ أُخِذَ مِنكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٧٠﴾ وَإِن يُرِيدُواْ خِيَانَتَكَ فَقَدۡ خَانُواْ ٱللَّهَ مِن قَبۡلُ فَأَمۡكَنَ مِنۡهُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ ﴿٧١﴾", "w": [["من الأسرى", "أسرى بدر الذين أُخذ منهم الفداء، كالعباس بن عبد المطلب رضي الله عنه."], ["إن يعلم الله في قلوبكم خيراً", "إيماناً صادقاً وإخلاصاً تاماً."], ["مما أُخذ منكم", "من مال الفداء."], ["وإن يريدوا خيانتك", "أي الأسرى."], ["فقد خانوا الله من قبل", "من قبل وقوعهم في الأسر، بكفرهم في مكة."], ["فأمكن منهم", "أمكنكم أنتم أيها المؤمنون منهم فقتلتموهم وأسرتموهم."], ["والله عليم حكيم", "عليم بخلقه، حكيم في صنعه وتدبيره."]], "m": "نزلت في العباس بن عبد المطلب رضي الله عنه، فإنه بعد أن وقع في الأسر أسلم، وطلب من الرسول ﷺ أن يرد عليه ما أُخذ منه من فدية، فأبى، فأنزل الله: يا أيها النبي قل لمن في أيديكم من الأسرى: إن يعلم الله في قلوبكم خيراً، إسلاماً حقيقياً، يؤتكم مالاً خيراً مما أُخذ منكم، ويغفر لكم ذنوبكم التي كانت كفراً ثم حرباً على الله ورسوله، والله غفور رحيم. وإن يريد هؤلاء الأسرى الذين أظهروا إسلامهم خيانتك والعودة إلى كفرهم إذا رجعوا إلى ديارهم، فلا تبالِ بهم، فقد خانوا الله من قبل بكفرهم، فأمكن المؤمنين منهم وجعلهم في قبضتهم، ولو عادوا لأمكنكم منهم ثانية، والله عليم بنياتهم حكيم فيما يحكم به عليهم، فليحسنوا إسلامهم ويصدقوا في إيمانهم فذلك خير لهم.", "h": ["فضل العباس عم رسول الله ﷺ لنزول الآية في حقه وشأنه.", "فضل إضمار الخير والنيات الصالحة.", "إطلاق لفظ الخير على الإسلام والقرآن، وحقاً هما الخير والخير كله.", "ما ترك عبد شيئاً لله إلا عوّضه خيراً منه.", "الله جل جلاله لا يغلبه غالب ولا يفوته هارب، ألا فليُتّقَ وليُتوكّل عليه."], "k": "«إن يعلم الله في قلوبكم خيراً يؤتكم خيراً»… ماذا يعلم الله في قلبي الآن؟"}, {"lbl": "الآيات ٧٢ – ٧٥", "q": "إِنَّ ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَـٰٓئِكَ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَٱلَّذِينَ ءَامَنُواْ وَلَمۡ يُهَاجِرُواْ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَيۡءٍ حَتَّىٰ يُهَاجِرُواْۚ وَإِنِ ٱسۡتَنصَرُوكُمۡ فِي ٱلدِّينِ فَعَلَيۡكُمُ ٱلنَّصۡرُ إِلَّا عَلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ ﴿٧٢﴾ وَٱلَّذِينَ كَفَرُواْ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٍۚ إِلَّا تَفۡعَلُوهُ تَكُن فِتۡنَةٞ فِي ٱلۡأَرۡضِ وَفَسَادٞ كَبِيرٞ ﴿٧٣﴾ وَٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَـٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ﴿٧٤﴾ وَٱلَّذِينَ ءَامَنُواْ مِنۢ بَعۡدُ وَهَاجَرُواْ وَجَٰهَدُواْ مَعَكُمۡ فَأُوْلَـٰٓئِكَ مِنكُمۡۚ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمُۢ ﴿٧٥﴾", "w": [["آمنوا", "صدّقوا الله ورسوله، وآمنوا بلقاء الله، وصدّقوا بوعده ووعيده."], ["وهاجروا", "تركوا ديارهم والتحقوا برسول الله ﷺ بالمدينة المنورة."], ["في سبيل الله", "من أجل أن يُعبد الله ولا يُعبد معه غيره، وهو الإسلام."], ["آووا", "آووا المهاجرين فضمّوهم إلى ديارهم، ونصروهم على أعدائهم."], ["وإن استنصروكم", "طلبوا منكم نصرتهم على أعدائهم."], ["ميثاق", "عهد، أي معاهدة سلم وعدم اعتداء."], ["إلا تفعلوه", "إن لم توالوا المسلمين وتقاطعوا الكافرين تكن فتنة."], ["أولو الأرحام", "الأقارب من ذوي النسب."], ["بعضهم أولى ببعض", "في التوارث، أي يرث بعضهم بعضاً."]], "m": "بمناسبة انتهاء أحداث بدر، ذكر الله حال المؤمنين وتفاوتهم في الكمال: الصنف الأول: الذين آمنوا وهاجروا وجاهدوا بأموالهم وأنفسهم في سبيل الله، والثاني: الذين آووا الرسول ﷺ والمهاجرين ونصروهم، وهما أكمل المؤمنين، أولئك بعضهم أولياء بعض في النصرة والموالاة والتوارث، ثم نُسخ التوارث بآخر آية في السياق. والصنف الثالث: الذين آمنوا ولم يهاجروا، ورضوا بالبقاء بين ظهراني الكافرين، فهم ناقصون، ما لكم من ولايتهم من شيء، فلا توارث ولا موالاة حتى يهاجروا، وإن استنصروكم في الدين فعليكم النصر، إلا على قوم بينكم وبينهم ميثاق فأوفوا بعهدكم ولا تغدروا، والله بما تعملون بصير. والذين كفروا بعضهم أولياء بعض يتناصرون ويتوارثون، إلا تفعلوه، من موالاة المؤمنين ومعاداة الكافرين، تكن فتنة في الأرض، وهي الشرك، وفساد كبير، وهو المعاصي. ثم أعاد ذكر الصنف الأول ليذكر جزاءه: أولئك هم المؤمنون حقاً، لهم مغفرة ورزق كريم في الجنة. والصنف الرابع: الذين آمنوا من بعد وهاجروا وجاهدوا معكم فأولئك منكم، دون الأولين لسبقهم، وألحقهم الله بهم. وأولو الأرحام بعضهم أولى ببعض في الإرث، وبها نُسخ التوارث بالهجرة والمعاقدة، واستقر الإرث بالمصاهرة والولاء والنسب، في كتاب الله، إن الله بكل شيء عليم.", "h": ["بيان تفاوت المؤمنين في كمالاتهم وعلو درجاتهم عند ربهم.", "أكمل المؤمنين الذين جمعوا بين الإيمان والهجرة والجهاد وسبقوا لذلك، وهم المهاجرون الأولون، والذين جمعوا بين الإيمان والإيواء والنصرة والجهاد، وهم الأنصار.", "دون ذلك من آمنوا وهاجروا وجاهدوا ولكن بعد صلح الحديبية.", "أدنى أصناف المؤمنين من آمنوا ولم يهاجروا، وهؤلاء على خطر عظيم.", "وجوب نصرة المؤمنين بموالاتهم ومحبتهم، ووجوب معاداة الكافرين وخذلانهم."], "k": "«أولئك هم المؤمنون حقاً»… بأي عمل أقترب من هذا الوصف: إيواء، أو نصرة، أو بذل؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (120, 9, 1, 12, 'سورة التوبة ١ – ١٢', '«براءة من الله ورسوله»، «فإن تابوا وأقاموا الصلاة وآتوا الزكاة فخلّوا سبيلهم»، و«فقاتلوا أئمة الكفر»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 120) = $j$[{"lbl": "الآيات ١ – ٤", "q": "بَرَآءَةٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ ﴿١﴾ فَسِيحُواْ فِي ٱلۡأَرۡضِ أَرۡبَعَةَ أَشۡهُرٖ وَٱعۡلَمُوٓاْ أَنَّكُمۡ غَيۡرُ مُعۡجِزِي ٱللَّهِ وَأَنَّ ٱللَّهَ مُخۡزِي ٱلۡكَٰفِرِينَ ﴿٢﴾ وَأَذَٰنٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوۡمَ ٱلۡحَجِّ ٱلۡأَكۡبَرِ أَنَّ ٱللَّهَ بَرِيٓءٞ مِّنَ ٱلۡمُشۡرِكِينَ وَرَسُولُهُۥۚ فَإِن تُبۡتُمۡ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّكُمۡ غَيۡرُ مُعۡجِزِي ٱللَّهِۗ وَبَشِّرِ ٱلَّذِينَ كَفَرُواْ بِعَذَابٍ أَلِيمٍ ﴿٣﴾ إِلَّا ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ ثُمَّ لَمۡ يَنقُصُوكُمۡ شَيۡـٔٗا وَلَمۡ يُظَٰهِرُواْ عَلَيۡكُمۡ أَحَدٗا فَأَتِمُّوٓاْ إِلَيۡهِمۡ عَهۡدَهُمۡ إِلَىٰ مُدَّتِهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ ﴿٤﴾", "w": [["براءة", "أي هذه براءة، بمعنى تبرّؤ وتباعد وتخلّص."], ["وأذان من الله", "إعلام منه تعالى."], ["يوم الحج الأكبر", "يوم عيد النحر."], ["لم ينقصوكم شيئاً", "من شروط المعاهدة وبنود الاتفاقية."]], "m": "هذه السورة الوحيدة التي خلت من البسملة، لأنها مفتتحة بآيات عذاب فتنافى معها ذكر الرحمة، وهي من آخر ما نزل، وقد بعث رسول الله ﷺ علياً وبعض الصحابة في حج سنة تسع يقرؤون هذه الآيات في الموسم، تُعلم المشركين أن من كان له عهد مطلق، أو دون أربعة أشهر، أو فوقها ونقضه، فعليهم أن يسيحوا في الأرض بأمان أربعة أشهر، فإن أسلموا فهو خير لهم، وإن خرجوا من الجزيرة فلهم ذلك، وإن بقوا كافرين أُخذوا حيث وُجدوا في ديار الجزيرة التي أصبحت دار إسلام. براءة من الله ورسوله إلى الذين عاهدتم من المشركين، فسيحوا في الأرض أربعة أشهر تبدأ من يوم الإعلان، يوم عيد الأضحى، واعلموا أنكم غير فائتي الله ولا هاربين من سلطانه، وأن الله مخزي الكافرين. وأذان من الله ورسوله إلى الناس يوم الحج الأكبر، حيث تفرّغ الحجاج للإقامة بمنى: أن الله بريء من المشركين ورسوله، فإن تبتم بالتوحيد والإيمان والطاعة فهو خير لكم، وإن تولّيتم فاعلموا أنكم غير معجزي الله، وبشّر الذين كفروا بعذاب أليم واقع بهم إلا أن يتوبوا. إلا الذين عاهدتم من المشركين ثم لم ينقصوكم شيئاً من شروط المعاهدة، ولم يُعاونوا عليكم أحداً لا برجال ولا بسلاح ولا بمشورة، فأتمّوا إليهم عهدهم إلى مدتهم، إن الله يحب المتقين.", "h": ["جواز عقد المعاهدات بين المسلمين والكافرين إذا كان ذلك لدفع ضرر محقّق عن المسلمين، أو جلب نفع للإسلام والمسلمين محقّقاً كذلك.", "تحريم الغدر والخيانة، ولذا كان إلغاء المعاهدات علنياً، وإمداد أصحابها بمدة ثلث سنة يفكّرون في أمرهم ويطلبون الأصلح لهم.", "وجوب الوفاء بالمعاهدات ذات الآجال إلى أجلها، إلا أن ينقضها المعاهَدون.", "فضل التقوى وأهلها، وهي اتقاء سخط الله بفعل المحبوب له تعالى وترك المكروه."], "k": "«فأتمّوا إليهم عهدهم إلى مدتهم»… الوفاء حتى مع المشرك؛ فهل أفي بوعودي ولو صعب عليّ؟"}, {"lbl": "الآيات ٥ – ٨", "q": "فَإِذَا ٱنسَلَخَ ٱلۡأَشۡهُرُ ٱلۡحُرُمُ فَٱقۡتُلُواْ ٱلۡمُشۡرِكِينَ حَيۡثُ وَجَدتُّمُوهُمۡ وَخُذُوهُمۡ وَٱحۡصُرُوهُمۡ وَٱقۡعُدُواْ لَهُمۡ كُلَّ مَرۡصَدٖۚ فَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَخَلُّواْ سَبِيلَهُمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٥﴾ وَإِنۡ أَحَدٞ مِّنَ ٱلۡمُشۡرِكِينَ ٱسۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ يَسۡمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبۡلِغۡهُ مَأۡمَنَهُۥۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡلَمُونَ ﴿٦﴾ كَيۡفَ يَكُونُ لِلۡمُشۡرِكِينَ عَهۡدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَٰهَدتُّمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ فَمَا ٱسۡتَقَٰمُواْ لَكُمۡ فَٱسۡتَقِيمُواْ لَهُمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ ﴿٧﴾ كَيۡفَ وَإِن يَظۡهَرُواْ عَلَيۡكُمۡ لَا يَرۡقُبُواْ فِيكُمۡ إِلّٗا وَلَا ذِمَّةٗۚ يُرۡضُونَكُم بِأَفۡوَٰهِهِمۡ وَتَأۡبَىٰ قُلُوبُهُمۡ وَأَكۡثَرُهُمۡ فَٰسِقُونَ ﴿٨﴾", "w": [["فإذا انسلخ الأشهر الحرم", "انقضت وخرجت الأشهر الأربعة التي أمّنتم فيها المشركين."], ["حيث وجدتموهم", "في أي مكان لقيتموهم، في الحل أو الحرم."], ["واحصروهم", "حاصروهم حتى يسلّموا أنفسهم."], ["واقعدوا لهم كل مرصد", "اقعدوا لهم في طرقاتهم وارصدوا تحركاتهم."], ["فإن تابوا", "آمنوا بالله ورسوله."], ["فخلّوا سبيلهم", "اتركوهم، فلا حصار ولا مطاردة ولا قتال."], ["استجارك", "طلب جوارك، أي حمايتك."], ["مأمنه", "المكان الذي يأمن فيه."], ["إلّاً ولا ذمة", "لا قرابة ولا عهداً، فالإلّ: القرابة، والذمة: العهد."]], "m": "ما زال السياق في إعلان الحرب العامة على المشركين تطهيراً لأرض الجزيرة، دار الإسلام وحوزته: فإذا انقضت الأشهر الأربعة التي أمّنتم فيها المشركين فاقتلوا المشركين حيث وجدتموهم في الحل والحرم، وخذوهم أسرى، واحصروهم حتى يستسلموا، واقعدوا لهم كل مرصد، فإن تابوا من الشرك وحربكم، وأقاموا الصلاة وآتوا الزكاة، فخلّوا سبيلهم، إذ أصبحوا مسلمين مثلكم، إن الله غفور رحيم. وإن أحد من المشركين استجارك فأجِره حتى يسمع كلام الله منك ويتفهّم دعوة الإسلام، ثم هو بالخيار، فإن لم يُسلم فأبلغه مكاناً يأمن فيه، ذلك بأنهم قوم لا يعلمون، ولو علموا ما رغبوا عن التوحيد. كيف يكون للمشركين عهد عند الله وعند رسوله وهم كافرون غادرون؟ إلا الذين عاهدتم عند المسجد الحرام، بعض بني بكر بن كنانة عاهدهم ﷺ عام الحديبية، فما استقاموا لكم فاستقيموا لهم، إن الله يحب المتقين. كيف وإن يظهروا عليكم ويغلبوكم لا يراعوا فيكم قرابة ولا عهداً، بل يقتلونكم قتلاً ذريعاً، يرضونكم بأفواههم بالكذب، وتأبى قلوبهم الكافرة ما يقولون، وأكثرهم فاسقون لا يلتزمون بعهد ولا دين.", "h": ["وجوب الوفاء بالعهود ما لم ينقضها المعاهَدون.", "تقرير مبدأ الحزم في القتال والضرب بشدة.", "وجوب تطهير الجزيرة من كل شرك وكفر، لأنها دار الإسلام.", "إقام الصلاة شرط في صحة الإيمان، فمن تركها فهو كافر غير مؤمن.", "احترام الجوار والإقرار به، وتأمين السفراء والممثّلين لدولة كافرة.", "قبول طلب كل من طلب من الكافرين الإذن له بدخول بلاد الإسلام ليتعلّم الدين.", "القرآن كلام الله تعالى حقاً بحروفه ومعانيه، لقوله: «حتى يسمع كلام الله»."], "k": "«فأجره حتى يسمع كلام الله»… هل أفتح لغيري باب سماع الحق، أم أغلقه بسوء معاملتي؟"}, {"lbl": "الآيات ٩ – ١٢", "q": "ٱشۡتَرَوۡاْ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلٗا فَصَدُّواْ عَن سَبِيلِهِۦٓۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ ﴿٩﴾ لَا يَرۡقُبُونَ فِي مُؤۡمِنٍ إِلّٗا وَلَا ذِمَّةٗۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُعۡتَدُونَ ﴿١٠﴾ فَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِۗ وَنُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ﴿١١﴾ وَإِن نَّكَثُوٓاْ أَيۡمَٰنَهُم مِّنۢ بَعۡدِ عَهۡدِهِمۡ وَطَعَنُواْ فِي دِينِكُمۡ فَقَٰتِلُوٓاْ أَئِمَّةَ ٱلۡكُفۡرِ إِنَّهُمۡ لَآ أَيۡمَٰنَ لَهُمۡ لَعَلَّهُمۡ يَنتَهُونَ ﴿١٢﴾", "w": [["اشتروا بآيات الله", "باعوا آيات الله وأخذوا بدلها الكفر."], ["فصدّوا عن سبيله", "أعرضوا عن سبيل الله التي هي الإسلام، كما صدّوا غيرهم عنه."], ["ساء", "قبُح."], ["لا يرقبون", "لا يراعون."], ["إلّاً", "الإلّ: الله، والقرابة، والعهد، وكلها صالحة هنا."], ["فإن تابوا", "أي من الشرك والمحاربة."], ["نكثوا", "نقضوا وغدروا."], ["وطعنوا في دينكم", "انتقدوا الإسلام في عقائده أو عباداته ومعاملاته."], ["أئمة الكفر", "رؤساء الكفر المتبوعين والمقلَّدين في الشرك والشر والفساد."]], "m": "ما زال السياق في الحديث عن المشركين: اشتروا بآيات الله ثمناً قليلاً، باعوا الإيمان بالكفر، فصدّوا أنفسهم وأتباعهم عن الإسلام، إنهم ساء ما كانوا يعملون. لا يرقبون في مؤمن يتمكّنون منه الله ولا قرابة ولا عهداً، وأولئك هم المعتدون، لا يحترمون عهوداً لظلمة نفوسهم، فعلى المسلمين قتالهم حتى يلقوا السلاح، إلا أن يتوبوا: فإن تابوا وأقاموا الصلاة وآتوا الزكاة فإخوانكم في الدين، ونفصّل الآيات المشتملة على الحجج والأحكام لقوم يعلمون، إذ أهل الجهالات لا ينتفعون بها. وإن نكثوا أيمانهم التي أكّدوا بها عهودهم، وعابوا الإسلام وطعنوا فيه، فهم أئمة الكفر، فقاتلوهم بلا هوادة، إنهم لا أيمان لهم، لعلهم ينتهون عن الكفر والغدر فيُسلموا ويصبحوا أولياء الله لا أعداءه.", "h": ["ذم سلوك الكافرين وتصرّفاتهم في الحياة، وحسبهم أن باعوا الحق بالباطل، واشتروا الضلالة بالهدى.", "من كان الاعتداء وصفاً له لا يُؤمَن على شيء، ولا يُوثق فيه في شيء، لفساد ملكته.", "أخوّة الإسلام تثبت بثلاثة أمور: التوحيد، وإقام الصلاة، وإيتاء الزكاة.", "الطعن في الدين ردّة وكفر موجب للقتل والقتال."], "k": "«فإن تابوا وأقاموا الصلاة وآتوا الزكاة فإخوانكم في الدين»… ما أوسع باب الأخوّة؛ فهل أفتحه لكل تائب؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 120;
insert into public.tdb_cards(topic, i, body) select 120, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٤", "q": "بَرَآءَةٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ ﴿١﴾ فَسِيحُواْ فِي ٱلۡأَرۡضِ أَرۡبَعَةَ أَشۡهُرٖ وَٱعۡلَمُوٓاْ أَنَّكُمۡ غَيۡرُ مُعۡجِزِي ٱللَّهِ وَأَنَّ ٱللَّهَ مُخۡزِي ٱلۡكَٰفِرِينَ ﴿٢﴾ وَأَذَٰنٞ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوۡمَ ٱلۡحَجِّ ٱلۡأَكۡبَرِ أَنَّ ٱللَّهَ بَرِيٓءٞ مِّنَ ٱلۡمُشۡرِكِينَ وَرَسُولُهُۥۚ فَإِن تُبۡتُمۡ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَوَلَّيۡتُمۡ فَٱعۡلَمُوٓاْ أَنَّكُمۡ غَيۡرُ مُعۡجِزِي ٱللَّهِۗ وَبَشِّرِ ٱلَّذِينَ كَفَرُواْ بِعَذَابٍ أَلِيمٍ ﴿٣﴾ إِلَّا ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِينَ ثُمَّ لَمۡ يَنقُصُوكُمۡ شَيۡـٔٗا وَلَمۡ يُظَٰهِرُواْ عَلَيۡكُمۡ أَحَدٗا فَأَتِمُّوٓاْ إِلَيۡهِمۡ عَهۡدَهُمۡ إِلَىٰ مُدَّتِهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ ﴿٤﴾", "w": [["براءة", "أي هذه براءة، بمعنى تبرّؤ وتباعد وتخلّص."], ["وأذان من الله", "إعلام منه تعالى."], ["يوم الحج الأكبر", "يوم عيد النحر."], ["لم ينقصوكم شيئاً", "من شروط المعاهدة وبنود الاتفاقية."]], "m": "هذه السورة الوحيدة التي خلت من البسملة، لأنها مفتتحة بآيات عذاب فتنافى معها ذكر الرحمة، وهي من آخر ما نزل، وقد بعث رسول الله ﷺ علياً وبعض الصحابة في حج سنة تسع يقرؤون هذه الآيات في الموسم، تُعلم المشركين أن من كان له عهد مطلق، أو دون أربعة أشهر، أو فوقها ونقضه، فعليهم أن يسيحوا في الأرض بأمان أربعة أشهر، فإن أسلموا فهو خير لهم، وإن خرجوا من الجزيرة فلهم ذلك، وإن بقوا كافرين أُخذوا حيث وُجدوا في ديار الجزيرة التي أصبحت دار إسلام. براءة من الله ورسوله إلى الذين عاهدتم من المشركين، فسيحوا في الأرض أربعة أشهر تبدأ من يوم الإعلان، يوم عيد الأضحى، واعلموا أنكم غير فائتي الله ولا هاربين من سلطانه، وأن الله مخزي الكافرين. وأذان من الله ورسوله إلى الناس يوم الحج الأكبر، حيث تفرّغ الحجاج للإقامة بمنى: أن الله بريء من المشركين ورسوله، فإن تبتم بالتوحيد والإيمان والطاعة فهو خير لكم، وإن تولّيتم فاعلموا أنكم غير معجزي الله، وبشّر الذين كفروا بعذاب أليم واقع بهم إلا أن يتوبوا. إلا الذين عاهدتم من المشركين ثم لم ينقصوكم شيئاً من شروط المعاهدة، ولم يُعاونوا عليكم أحداً لا برجال ولا بسلاح ولا بمشورة، فأتمّوا إليهم عهدهم إلى مدتهم، إن الله يحب المتقين.", "h": ["جواز عقد المعاهدات بين المسلمين والكافرين إذا كان ذلك لدفع ضرر محقّق عن المسلمين، أو جلب نفع للإسلام والمسلمين محقّقاً كذلك.", "تحريم الغدر والخيانة، ولذا كان إلغاء المعاهدات علنياً، وإمداد أصحابها بمدة ثلث سنة يفكّرون في أمرهم ويطلبون الأصلح لهم.", "وجوب الوفاء بالمعاهدات ذات الآجال إلى أجلها، إلا أن ينقضها المعاهَدون.", "فضل التقوى وأهلها، وهي اتقاء سخط الله بفعل المحبوب له تعالى وترك المكروه."], "k": "«فأتمّوا إليهم عهدهم إلى مدتهم»… الوفاء حتى مع المشرك؛ فهل أفي بوعودي ولو صعب عليّ؟"}, {"lbl": "الآيات ٥ – ٨", "q": "فَإِذَا ٱنسَلَخَ ٱلۡأَشۡهُرُ ٱلۡحُرُمُ فَٱقۡتُلُواْ ٱلۡمُشۡرِكِينَ حَيۡثُ وَجَدتُّمُوهُمۡ وَخُذُوهُمۡ وَٱحۡصُرُوهُمۡ وَٱقۡعُدُواْ لَهُمۡ كُلَّ مَرۡصَدٖۚ فَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَخَلُّواْ سَبِيلَهُمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿٥﴾ وَإِنۡ أَحَدٞ مِّنَ ٱلۡمُشۡرِكِينَ ٱسۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ يَسۡمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبۡلِغۡهُ مَأۡمَنَهُۥۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمٞ لَّا يَعۡلَمُونَ ﴿٦﴾ كَيۡفَ يَكُونُ لِلۡمُشۡرِكِينَ عَهۡدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَٰهَدتُّمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ فَمَا ٱسۡتَقَٰمُواْ لَكُمۡ فَٱسۡتَقِيمُواْ لَهُمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ ﴿٧﴾ كَيۡفَ وَإِن يَظۡهَرُواْ عَلَيۡكُمۡ لَا يَرۡقُبُواْ فِيكُمۡ إِلّٗا وَلَا ذِمَّةٗۚ يُرۡضُونَكُم بِأَفۡوَٰهِهِمۡ وَتَأۡبَىٰ قُلُوبُهُمۡ وَأَكۡثَرُهُمۡ فَٰسِقُونَ ﴿٨﴾", "w": [["فإذا انسلخ الأشهر الحرم", "انقضت وخرجت الأشهر الأربعة التي أمّنتم فيها المشركين."], ["حيث وجدتموهم", "في أي مكان لقيتموهم، في الحل أو الحرم."], ["واحصروهم", "حاصروهم حتى يسلّموا أنفسهم."], ["واقعدوا لهم كل مرصد", "اقعدوا لهم في طرقاتهم وارصدوا تحركاتهم."], ["فإن تابوا", "آمنوا بالله ورسوله."], ["فخلّوا سبيلهم", "اتركوهم، فلا حصار ولا مطاردة ولا قتال."], ["استجارك", "طلب جوارك، أي حمايتك."], ["مأمنه", "المكان الذي يأمن فيه."], ["إلّاً ولا ذمة", "لا قرابة ولا عهداً، فالإلّ: القرابة، والذمة: العهد."]], "m": "ما زال السياق في إعلان الحرب العامة على المشركين تطهيراً لأرض الجزيرة، دار الإسلام وحوزته: فإذا انقضت الأشهر الأربعة التي أمّنتم فيها المشركين فاقتلوا المشركين حيث وجدتموهم في الحل والحرم، وخذوهم أسرى، واحصروهم حتى يستسلموا، واقعدوا لهم كل مرصد، فإن تابوا من الشرك وحربكم، وأقاموا الصلاة وآتوا الزكاة، فخلّوا سبيلهم، إذ أصبحوا مسلمين مثلكم، إن الله غفور رحيم. وإن أحد من المشركين استجارك فأجِره حتى يسمع كلام الله منك ويتفهّم دعوة الإسلام، ثم هو بالخيار، فإن لم يُسلم فأبلغه مكاناً يأمن فيه، ذلك بأنهم قوم لا يعلمون، ولو علموا ما رغبوا عن التوحيد. كيف يكون للمشركين عهد عند الله وعند رسوله وهم كافرون غادرون؟ إلا الذين عاهدتم عند المسجد الحرام، بعض بني بكر بن كنانة عاهدهم ﷺ عام الحديبية، فما استقاموا لكم فاستقيموا لهم، إن الله يحب المتقين. كيف وإن يظهروا عليكم ويغلبوكم لا يراعوا فيكم قرابة ولا عهداً، بل يقتلونكم قتلاً ذريعاً، يرضونكم بأفواههم بالكذب، وتأبى قلوبهم الكافرة ما يقولون، وأكثرهم فاسقون لا يلتزمون بعهد ولا دين.", "h": ["وجوب الوفاء بالعهود ما لم ينقضها المعاهَدون.", "تقرير مبدأ الحزم في القتال والضرب بشدة.", "وجوب تطهير الجزيرة من كل شرك وكفر، لأنها دار الإسلام.", "إقام الصلاة شرط في صحة الإيمان، فمن تركها فهو كافر غير مؤمن.", "احترام الجوار والإقرار به، وتأمين السفراء والممثّلين لدولة كافرة.", "قبول طلب كل من طلب من الكافرين الإذن له بدخول بلاد الإسلام ليتعلّم الدين.", "القرآن كلام الله تعالى حقاً بحروفه ومعانيه، لقوله: «حتى يسمع كلام الله»."], "k": "«فأجره حتى يسمع كلام الله»… هل أفتح لغيري باب سماع الحق، أم أغلقه بسوء معاملتي؟"}, {"lbl": "الآيات ٩ – ١٢", "q": "ٱشۡتَرَوۡاْ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلٗا فَصَدُّواْ عَن سَبِيلِهِۦٓۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ ﴿٩﴾ لَا يَرۡقُبُونَ فِي مُؤۡمِنٍ إِلّٗا وَلَا ذِمَّةٗۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُعۡتَدُونَ ﴿١٠﴾ فَإِن تَابُواْ وَأَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِۗ وَنُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ﴿١١﴾ وَإِن نَّكَثُوٓاْ أَيۡمَٰنَهُم مِّنۢ بَعۡدِ عَهۡدِهِمۡ وَطَعَنُواْ فِي دِينِكُمۡ فَقَٰتِلُوٓاْ أَئِمَّةَ ٱلۡكُفۡرِ إِنَّهُمۡ لَآ أَيۡمَٰنَ لَهُمۡ لَعَلَّهُمۡ يَنتَهُونَ ﴿١٢﴾", "w": [["اشتروا بآيات الله", "باعوا آيات الله وأخذوا بدلها الكفر."], ["فصدّوا عن سبيله", "أعرضوا عن سبيل الله التي هي الإسلام، كما صدّوا غيرهم عنه."], ["ساء", "قبُح."], ["لا يرقبون", "لا يراعون."], ["إلّاً", "الإلّ: الله، والقرابة، والعهد، وكلها صالحة هنا."], ["فإن تابوا", "أي من الشرك والمحاربة."], ["نكثوا", "نقضوا وغدروا."], ["وطعنوا في دينكم", "انتقدوا الإسلام في عقائده أو عباداته ومعاملاته."], ["أئمة الكفر", "رؤساء الكفر المتبوعين والمقلَّدين في الشرك والشر والفساد."]], "m": "ما زال السياق في الحديث عن المشركين: اشتروا بآيات الله ثمناً قليلاً، باعوا الإيمان بالكفر، فصدّوا أنفسهم وأتباعهم عن الإسلام، إنهم ساء ما كانوا يعملون. لا يرقبون في مؤمن يتمكّنون منه الله ولا قرابة ولا عهداً، وأولئك هم المعتدون، لا يحترمون عهوداً لظلمة نفوسهم، فعلى المسلمين قتالهم حتى يلقوا السلاح، إلا أن يتوبوا: فإن تابوا وأقاموا الصلاة وآتوا الزكاة فإخوانكم في الدين، ونفصّل الآيات المشتملة على الحجج والأحكام لقوم يعلمون، إذ أهل الجهالات لا ينتفعون بها. وإن نكثوا أيمانهم التي أكّدوا بها عهودهم، وعابوا الإسلام وطعنوا فيه، فهم أئمة الكفر، فقاتلوهم بلا هوادة، إنهم لا أيمان لهم، لعلهم ينتهون عن الكفر والغدر فيُسلموا ويصبحوا أولياء الله لا أعداءه.", "h": ["ذم سلوك الكافرين وتصرّفاتهم في الحياة، وحسبهم أن باعوا الحق بالباطل، واشتروا الضلالة بالهدى.", "من كان الاعتداء وصفاً له لا يُؤمَن على شيء، ولا يُوثق فيه في شيء، لفساد ملكته.", "أخوّة الإسلام تثبت بثلاثة أمور: التوحيد، وإقام الصلاة، وإيتاء الزكاة.", "الطعن في الدين ردّة وكفر موجب للقتل والقتال."], "k": "«فإن تابوا وأقاموا الصلاة وآتوا الزكاة فإخوانكم في الدين»… ما أوسع باب الأخوّة؛ فهل أفتحه لكل تائب؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (121, 9, 13, 24, 'سورة التوبة ١٣ – ٢٤', '«ألا تقاتلون قوماً نكثوا أيمانهم»، «إنما يعمر مساجد الله»، و«قل إن كان آباؤكم وأبناؤكم…»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 121) = $j$[{"lbl": "الآيات ١٣ – ١٦", "q": "أَلَا تُقَٰتِلُونَ قَوۡمٗا نَّكَثُوٓاْ أَيۡمَٰنَهُمۡ وَهَمُّواْ بِإِخۡرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمۡ أَوَّلَ مَرَّةٍۚ أَتَخۡشَوۡنَهُمۡۚ فَٱللَّهُ أَحَقُّ أَن تَخۡشَوۡهُ إِن كُنتُم مُّؤۡمِنِينَ ﴿١٣﴾ قَٰتِلُوهُمۡ يُعَذِّبۡهُمُ ٱللَّهُ بِأَيۡدِيكُمۡ وَيُخۡزِهِمۡ وَيَنصُرۡكُمۡ عَلَيۡهِمۡ وَيَشۡفِ صُدُورَ قَوۡمٖ مُّؤۡمِنِينَ ﴿١٤﴾ وَيُذۡهِبۡ غَيۡظَ قُلُوبِهِمۡۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ ﴿١٥﴾ أَمۡ حَسِبۡتُمۡ أَن تُتۡرَكُواْ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَلَمۡ يَتَّخِذُواْ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلۡمُؤۡمِنِينَ وَلِيجَةٗۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿١٦﴾", "w": [["ألا", "أداة تحضيض."], ["نكثوا أيمانهم", "نقضوها وحلّوها فلم يلتزموا بها."], ["وهمّوا بإخراج الرسول", "في دار الندوة، إذ عزموا على واحدة من ثلاث: الحبس أو النفي أو القتل."], ["بدؤوكم أول مرة", "في بدر، أو في ماء الوتير حيث أعانت قريش بني بكر على خزاعة."], ["ويخزهم", "يذلّهم ويهينهم."], ["أن تُتركوا", "بدون امتحان بالتكاليف كالجهاد."], ["وليجة", "دخيلة، وهي الرجل يدخل في القوم وليس منهم، ويطلعونه على أسرارهم وبواطن أمورهم."]], "m": "بعد انسلاخ الأشهر الأربعة لم يبق إلا قتال المشركين، فقال تعالى حاضّاً مهيّجاً: ألا تقاتلون قوماً نكثوا أيمانهم، وهمّوا بإخراج الرسول من مكة، وهم بدؤوكم أول مرة في بدر، إذ نجت عيرهم وأبوا إلا القتال؟ أتخشونهم؟ فالله أحق أن تخشوه إن كنتم مؤمنين، لأن ما عنده من العذاب ليس عند المشركين. قاتلوهم يعذّبهم الله بأيديكم ويخزهم وينصركم عليهم، ويشفِ صدور قوم مؤمنين، وهم خزاعة الذين قاتلهم بنو بكر وأعانتهم قريش بعد صلح الحديبية، ويذهب غيظ قلوبهم، ويتوب الله على من يشاء، إذ سنته أن الناس إذا رأوا انتصار أعدائهم عليهم في كل معركة مالوا إليهم وقبلوا دينهم، والله عليم حكيم. أم حسبتم أن تُتركوا بلا امتحان، وأنتم خليط: المؤمن الصادق والمنافق الكاذب الذي يثبّط عن القتال بحجة أن مكة فُتحت، ولما يعلم الله الذين جاهدوا منكم ولم يتخذوا من دون الله ولا رسوله ولا المؤمنين وليجة يطلعونها على أسرار المسلمين، والله خبير بما تعملون.", "h": ["مشروعية استعمال أسلوب التهييج والإثارة للجهاد.", "وجوب خشية الله تعالى بطاعته وترك معصيته.", "لازم الإيمان الشجاعة، فمن ضعفت شجاعته ضعف إيمانه.", "من ثمرات القتال دخول الناس في دين الله تعالى.", "الجهاد عملية تصفية وتطهير لصفوف المؤمنين وقلوبهم أيضاً."], "k": "«أتخشونهم فالله أحق أن تخشوه»… من أخشى أكثر: نظرة الناس، أم نظر ربي؟"}, {"lbl": "الآيتان ١٧ – ١٨", "q": "مَا كَانَ لِلۡمُشۡرِكِينَ أَن يَعۡمُرُواْ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلۡكُفۡرِۚ أُوْلَـٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ وَفِي ٱلنَّارِ هُمۡ خَٰلِدُونَ ﴿١٧﴾ إِنَّمَا يَعۡمُرُ مَسَٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمۡ يَخۡشَ إِلَّا ٱللَّهَۖ فَعَسَىٰٓ أُوْلَـٰٓئِكَ أَن يَكُونُواْ مِنَ ٱلۡمُهۡتَدِينَ ﴿١٨﴾", "w": [["حبطت أعمالهم", "بطلت فلا يُثابون عليها ولا ينجحون فيها."], ["يعمروا مساجد الله", "بالعبادة فيها، وصيانتها وتطهيرها."], ["ولم يخشَ إلا الله", "لم يخف أحداً غير الله تعالى."], ["فعسى", "عسى من الله تعالى، كما هي هنا، تفيد التحقيق."], ["المهتدين", "إلى سبيل النجاة من الخسران، والظفر بالجنان."]], "m": "ادّعى بعض المشركين أنهم يعمرون المسجد الحرام بالسدانة والحجابة والسقاية، فأبطل الله ذلك: ما كان للمشركين أن يعمروا مساجد الله، لا يصح منهم، وكيف وهم شاهدون على أنفسهم بالكفر؟ فاليهودي إذا سُئل: ما أنت؟ قال: يهودي، والنصراني: نصراني، والوثني: مشرك، فهذه شهادتهم على أنفسهم بالكفر، أولئك حبطت أعمالهم لفقدها الإخلاص، وفي النار هم خالدون. ثم قرّر الحقيقة: إنما يعمر مساجد الله من آمن بالله واليوم الآخر، وأقام الصلاة، وآتى الزكاة، ولم يخش إلا الله، هؤلاء الجديرون بعمارة المساجد بالصلاة والذكر وتعلّم العلم الشرعي فيها، زيادة على بنائها وتطهيرها وصيانتها، فعسى أولئك أن يكونوا من المهتدين إلى الحق وسبيل النجاة.", "h": ["حرمة دخول الكافر المساجد إلا لحاجة، وبإذن من المسلمين.", "فضيلة عمارة المساجد بالعبادة فيها، وتطهيرها وصيانتها.", "فضيلة المسلم وشرفه، إذ كل من يُسأل عن دينه يجيب بجواب هو الكفر، إلا المسلم فإنه يقول: مسلم، أي لله تعالى.", "وجوب الإيمان بالله واليوم الآخر، وإقام الصلاة، وإيتاء الزكاة، والخشية من الله تعالى.", "أهل الأمن والنجاة من النار هم أصحاب الصفات الأربع المذكورة في الآية."], "k": "«إنما يعمر مساجد الله من آمن بالله»… ما نصيبي من عمارة بيوت الله: صلاة، أو ذكر، أو علم؟"}, {"lbl": "الآيات ١٩ – ٢٢", "q": "۞أَجَعَلۡتُمۡ سِقَايَةَ ٱلۡحَآجِّ وَعِمَارَةَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ كَمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَجَٰهَدَ فِي سَبِيلِ ٱللَّهِۚ لَا يَسۡتَوُۥنَ عِندَ ٱللَّهِۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿١٩﴾ ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ أَعۡظَمُ دَرَجَةً عِندَ ٱللَّهِۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ ﴿٢٠﴾ يُبَشِّرُهُمۡ رَبُّهُم بِرَحۡمَةٖ مِّنۡهُ وَرِضۡوَٰنٖ وَجَنَّـٰتٖ لَّهُمۡ فِيهَا نَعِيمٞ مُّقِيمٌ ﴿٢١﴾ خَٰلِدِينَ فِيهَآ أَبَدًاۚ إِنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ ﴿٢٢﴾", "w": [["سقاية الحاج", "مكان يوضع فيه الماء في المسجد الحرام ويُسقى منه الحجاج مجاناً."], ["وعمارة المسجد الحرام", "هنا: بناؤه وصيانته وسدانة البيت فيه."], ["لا يستوون عند الله", "إذ عمارة المسجد الحرام مع الشرك والكفر لا تساوي شيئاً."], ["والله لا يهدي القوم الظالمين", "المشركين، لا يهديهم لما فيه كمالهم وسعادتهم."], ["ورضوان", "رضا الله عز وجل عنهم."], ["نعيم مقيم", "دائم لا يزول ولا ينقطع."]], "m": "ما زال السياق في الرد على من فضّل عمارة المسجد الحرام بالسقاية والحجابة والسدانة على الإيمان والهجرة والجهاد: أجعلتم سقاية الحاج وعمارة المسجد الحرام كمن آمن بالله واليوم الآخر وجاهد في سبيل الله؟ لا يستوون عند الله بحال، والمشركون ظالمون فكيف يكون لعمارتهم وزن؟ والله لا يهدي القوم الظالمين. الذين آمنوا وهاجروا وجاهدوا في سبيل الله بأموالهم وأنفسهم أعظم درجة عند الله ممن لم يستكمل هذه الصفات، وأولئك هم الفائزون بالنجاة من النار ودخول الجنة، يبشّرهم ربهم برحمة منه، وهي الجنة، ورضوان، وهو أكبر نعيم، وجنات في الملكوت الأعلى لهم فيها نعيم مقيم لا يحول ولا يزول، خالدين فيها أبداً، إن الله عنده أجر عظيم.", "h": ["أكمل المؤمنين وأعلاهم درجة وأقربهم من الله منزلة من جمع الصفات الثلاث المذكورة في الآية (٢٠)، وهي: الإيمان، والهجرة، والجهاد في سبيل الله بالمال والنفس.", "فضل الهجرة والجهاد.", "تفاوت أهل الجنة في علو درجاتهم.", "حرمان الظالمين المتوغّلين في الظلم من هداية الله تعالى."], "k": "«يبشّرهم ربهم برحمة منه ورضوان»… أي عمل أرجو به رضوان ربي، وهو أكبر من الجنة؟"}, {"lbl": "الآيتان ٢٣ – ٢٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُوٓاْ ءَابَآءَكُمۡ وَإِخۡوَٰنَكُمۡ أَوۡلِيَآءَ إِنِ ٱسۡتَحَبُّواْ ٱلۡكُفۡرَ عَلَى ٱلۡإِيمَٰنِۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿٢٣﴾ قُلۡ إِن كَانَ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ وَإِخۡوَٰنُكُمۡ وَأَزۡوَٰجُكُمۡ وَعَشِيرَتُكُمۡ وَأَمۡوَٰلٌ ٱقۡتَرَفۡتُمُوهَا وَتِجَٰرَةٞ تَخۡشَوۡنَ كَسَادَهَا وَمَسَٰكِنُ تَرۡضَوۡنَهَآ أَحَبَّ إِلَيۡكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٖ فِي سَبِيلِهِۦ فَتَرَبَّصُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ﴿٢٤﴾", "w": [["أولياء", "جمع ولي، وهو من تتولّاه بالمحبة والنصرة ويتولّاك بمثل ذلك."], ["استحبّوا", "أحبّوا الكفر على الإيمان."], ["الظالمون", "الظلم وضع الشيء في غير موضعه، ومن أحب من لا تجوز محبته فقد ظلم."], ["اقترفتموها", "اكتسبتموها."], ["كسادها", "بوارها وعدم رواجها."], ["فتربّصوا", "انتظروا."]], "m": "هذا إنذار الله للمؤمنين ينهاهم عن اتخاذ من كفر من آبائهم وإخوانهم أولياء يوادّونهم ويناصرونهم ويطلعونهم على أسرار المسلمين: يا أيها الذين آمنوا لا تتخذوا آباءكم وإخوانكم أولياء إن آثروا الكفر على الإيمان، ومن يتولّهم منكم فأولئك هم الظالمون، إذ وضعوا المحبة موضع البغضاء والنصرة موضع الخذلان. ثم أمر رسوله أن يقول لهم، وفي العدول عن خطابهم مباشرة ما يشعر بالغضب والتهديد: قل إن كان آباؤكم وأبناؤكم وإخوانكم وأزواجكم وعشيرتكم، وأموال اكتسبتموها، وتجارة تخشون كسادها، ومساكن ترضونها، أحب إليكم من الله ورسوله وجهاد في سبيله، فتركتم الهجرة والجهاد لذلك، فتربّصوا حتى يأتي الله بأمره، وهو فتح مكة وإنزال العقوبة بكم، والله لا يهدي القوم الفاسقين.", "h": ["حرمة اتخاذ الكافرين أولياء يُوادّون، ولو كانوا من أقرب الأقرباء كالأب والابن والأخ.", "من الظلم الفظيع موالاة من عادى الله ورسوله والمؤمنين.", "فرضية محبة الله ورسوله والجهاد في سبيله، ومحبة سائر محابّ الله تعالى، وكره سائر مكارهه من العقائد والأحوال والأعمال والذوات والصفات.", "حرمان أهل الفسق المتوغّلين فيه من هداية الله تعالى إلى ما يكملهم ويسعدهم."], "k": "«أحب إليكم من الله ورسوله»… لو وُضعت محابّي الثمانية في كفّة، فأين يقع حب الله ورسوله منها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 121;
insert into public.tdb_cards(topic, i, body) select 121, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٣ – ١٦", "q": "أَلَا تُقَٰتِلُونَ قَوۡمٗا نَّكَثُوٓاْ أَيۡمَٰنَهُمۡ وَهَمُّواْ بِإِخۡرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمۡ أَوَّلَ مَرَّةٍۚ أَتَخۡشَوۡنَهُمۡۚ فَٱللَّهُ أَحَقُّ أَن تَخۡشَوۡهُ إِن كُنتُم مُّؤۡمِنِينَ ﴿١٣﴾ قَٰتِلُوهُمۡ يُعَذِّبۡهُمُ ٱللَّهُ بِأَيۡدِيكُمۡ وَيُخۡزِهِمۡ وَيَنصُرۡكُمۡ عَلَيۡهِمۡ وَيَشۡفِ صُدُورَ قَوۡمٖ مُّؤۡمِنِينَ ﴿١٤﴾ وَيُذۡهِبۡ غَيۡظَ قُلُوبِهِمۡۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ ﴿١٥﴾ أَمۡ حَسِبۡتُمۡ أَن تُتۡرَكُواْ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَلَمۡ يَتَّخِذُواْ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلۡمُؤۡمِنِينَ وَلِيجَةٗۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ ﴿١٦﴾", "w": [["ألا", "أداة تحضيض."], ["نكثوا أيمانهم", "نقضوها وحلّوها فلم يلتزموا بها."], ["وهمّوا بإخراج الرسول", "في دار الندوة، إذ عزموا على واحدة من ثلاث: الحبس أو النفي أو القتل."], ["بدؤوكم أول مرة", "في بدر، أو في ماء الوتير حيث أعانت قريش بني بكر على خزاعة."], ["ويخزهم", "يذلّهم ويهينهم."], ["أن تُتركوا", "بدون امتحان بالتكاليف كالجهاد."], ["وليجة", "دخيلة، وهي الرجل يدخل في القوم وليس منهم، ويطلعونه على أسرارهم وبواطن أمورهم."]], "m": "بعد انسلاخ الأشهر الأربعة لم يبق إلا قتال المشركين، فقال تعالى حاضّاً مهيّجاً: ألا تقاتلون قوماً نكثوا أيمانهم، وهمّوا بإخراج الرسول من مكة، وهم بدؤوكم أول مرة في بدر، إذ نجت عيرهم وأبوا إلا القتال؟ أتخشونهم؟ فالله أحق أن تخشوه إن كنتم مؤمنين، لأن ما عنده من العذاب ليس عند المشركين. قاتلوهم يعذّبهم الله بأيديكم ويخزهم وينصركم عليهم، ويشفِ صدور قوم مؤمنين، وهم خزاعة الذين قاتلهم بنو بكر وأعانتهم قريش بعد صلح الحديبية، ويذهب غيظ قلوبهم، ويتوب الله على من يشاء، إذ سنته أن الناس إذا رأوا انتصار أعدائهم عليهم في كل معركة مالوا إليهم وقبلوا دينهم، والله عليم حكيم. أم حسبتم أن تُتركوا بلا امتحان، وأنتم خليط: المؤمن الصادق والمنافق الكاذب الذي يثبّط عن القتال بحجة أن مكة فُتحت، ولما يعلم الله الذين جاهدوا منكم ولم يتخذوا من دون الله ولا رسوله ولا المؤمنين وليجة يطلعونها على أسرار المسلمين، والله خبير بما تعملون.", "h": ["مشروعية استعمال أسلوب التهييج والإثارة للجهاد.", "وجوب خشية الله تعالى بطاعته وترك معصيته.", "لازم الإيمان الشجاعة، فمن ضعفت شجاعته ضعف إيمانه.", "من ثمرات القتال دخول الناس في دين الله تعالى.", "الجهاد عملية تصفية وتطهير لصفوف المؤمنين وقلوبهم أيضاً."], "k": "«أتخشونهم فالله أحق أن تخشوه»… من أخشى أكثر: نظرة الناس، أم نظر ربي؟"}, {"lbl": "الآيتان ١٧ – ١٨", "q": "مَا كَانَ لِلۡمُشۡرِكِينَ أَن يَعۡمُرُواْ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلۡكُفۡرِۚ أُوْلَـٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ وَفِي ٱلنَّارِ هُمۡ خَٰلِدُونَ ﴿١٧﴾ إِنَّمَا يَعۡمُرُ مَسَٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمۡ يَخۡشَ إِلَّا ٱللَّهَۖ فَعَسَىٰٓ أُوْلَـٰٓئِكَ أَن يَكُونُواْ مِنَ ٱلۡمُهۡتَدِينَ ﴿١٨﴾", "w": [["حبطت أعمالهم", "بطلت فلا يُثابون عليها ولا ينجحون فيها."], ["يعمروا مساجد الله", "بالعبادة فيها، وصيانتها وتطهيرها."], ["ولم يخشَ إلا الله", "لم يخف أحداً غير الله تعالى."], ["فعسى", "عسى من الله تعالى، كما هي هنا، تفيد التحقيق."], ["المهتدين", "إلى سبيل النجاة من الخسران، والظفر بالجنان."]], "m": "ادّعى بعض المشركين أنهم يعمرون المسجد الحرام بالسدانة والحجابة والسقاية، فأبطل الله ذلك: ما كان للمشركين أن يعمروا مساجد الله، لا يصح منهم، وكيف وهم شاهدون على أنفسهم بالكفر؟ فاليهودي إذا سُئل: ما أنت؟ قال: يهودي، والنصراني: نصراني، والوثني: مشرك، فهذه شهادتهم على أنفسهم بالكفر، أولئك حبطت أعمالهم لفقدها الإخلاص، وفي النار هم خالدون. ثم قرّر الحقيقة: إنما يعمر مساجد الله من آمن بالله واليوم الآخر، وأقام الصلاة، وآتى الزكاة، ولم يخش إلا الله، هؤلاء الجديرون بعمارة المساجد بالصلاة والذكر وتعلّم العلم الشرعي فيها، زيادة على بنائها وتطهيرها وصيانتها، فعسى أولئك أن يكونوا من المهتدين إلى الحق وسبيل النجاة.", "h": ["حرمة دخول الكافر المساجد إلا لحاجة، وبإذن من المسلمين.", "فضيلة عمارة المساجد بالعبادة فيها، وتطهيرها وصيانتها.", "فضيلة المسلم وشرفه، إذ كل من يُسأل عن دينه يجيب بجواب هو الكفر، إلا المسلم فإنه يقول: مسلم، أي لله تعالى.", "وجوب الإيمان بالله واليوم الآخر، وإقام الصلاة، وإيتاء الزكاة، والخشية من الله تعالى.", "أهل الأمن والنجاة من النار هم أصحاب الصفات الأربع المذكورة في الآية."], "k": "«إنما يعمر مساجد الله من آمن بالله»… ما نصيبي من عمارة بيوت الله: صلاة، أو ذكر، أو علم؟"}, {"lbl": "الآيات ١٩ – ٢٢", "q": "۞أَجَعَلۡتُمۡ سِقَايَةَ ٱلۡحَآجِّ وَعِمَارَةَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ كَمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَجَٰهَدَ فِي سَبِيلِ ٱللَّهِۚ لَا يَسۡتَوُۥنَ عِندَ ٱللَّهِۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿١٩﴾ ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ أَعۡظَمُ دَرَجَةً عِندَ ٱللَّهِۚ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ ﴿٢٠﴾ يُبَشِّرُهُمۡ رَبُّهُم بِرَحۡمَةٖ مِّنۡهُ وَرِضۡوَٰنٖ وَجَنَّـٰتٖ لَّهُمۡ فِيهَا نَعِيمٞ مُّقِيمٌ ﴿٢١﴾ خَٰلِدِينَ فِيهَآ أَبَدًاۚ إِنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ ﴿٢٢﴾", "w": [["سقاية الحاج", "مكان يوضع فيه الماء في المسجد الحرام ويُسقى منه الحجاج مجاناً."], ["وعمارة المسجد الحرام", "هنا: بناؤه وصيانته وسدانة البيت فيه."], ["لا يستوون عند الله", "إذ عمارة المسجد الحرام مع الشرك والكفر لا تساوي شيئاً."], ["والله لا يهدي القوم الظالمين", "المشركين، لا يهديهم لما فيه كمالهم وسعادتهم."], ["ورضوان", "رضا الله عز وجل عنهم."], ["نعيم مقيم", "دائم لا يزول ولا ينقطع."]], "m": "ما زال السياق في الرد على من فضّل عمارة المسجد الحرام بالسقاية والحجابة والسدانة على الإيمان والهجرة والجهاد: أجعلتم سقاية الحاج وعمارة المسجد الحرام كمن آمن بالله واليوم الآخر وجاهد في سبيل الله؟ لا يستوون عند الله بحال، والمشركون ظالمون فكيف يكون لعمارتهم وزن؟ والله لا يهدي القوم الظالمين. الذين آمنوا وهاجروا وجاهدوا في سبيل الله بأموالهم وأنفسهم أعظم درجة عند الله ممن لم يستكمل هذه الصفات، وأولئك هم الفائزون بالنجاة من النار ودخول الجنة، يبشّرهم ربهم برحمة منه، وهي الجنة، ورضوان، وهو أكبر نعيم، وجنات في الملكوت الأعلى لهم فيها نعيم مقيم لا يحول ولا يزول، خالدين فيها أبداً، إن الله عنده أجر عظيم.", "h": ["أكمل المؤمنين وأعلاهم درجة وأقربهم من الله منزلة من جمع الصفات الثلاث المذكورة في الآية (٢٠)، وهي: الإيمان، والهجرة، والجهاد في سبيل الله بالمال والنفس.", "فضل الهجرة والجهاد.", "تفاوت أهل الجنة في علو درجاتهم.", "حرمان الظالمين المتوغّلين في الظلم من هداية الله تعالى."], "k": "«يبشّرهم ربهم برحمة منه ورضوان»… أي عمل أرجو به رضوان ربي، وهو أكبر من الجنة؟"}, {"lbl": "الآيتان ٢٣ – ٢٤", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُوٓاْ ءَابَآءَكُمۡ وَإِخۡوَٰنَكُمۡ أَوۡلِيَآءَ إِنِ ٱسۡتَحَبُّواْ ٱلۡكُفۡرَ عَلَى ٱلۡإِيمَٰنِۚ وَمَن يَتَوَلَّهُم مِّنكُمۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿٢٣﴾ قُلۡ إِن كَانَ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ وَإِخۡوَٰنُكُمۡ وَأَزۡوَٰجُكُمۡ وَعَشِيرَتُكُمۡ وَأَمۡوَٰلٌ ٱقۡتَرَفۡتُمُوهَا وَتِجَٰرَةٞ تَخۡشَوۡنَ كَسَادَهَا وَمَسَٰكِنُ تَرۡضَوۡنَهَآ أَحَبَّ إِلَيۡكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٖ فِي سَبِيلِهِۦ فَتَرَبَّصُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ﴿٢٤﴾", "w": [["أولياء", "جمع ولي، وهو من تتولّاه بالمحبة والنصرة ويتولّاك بمثل ذلك."], ["استحبّوا", "أحبّوا الكفر على الإيمان."], ["الظالمون", "الظلم وضع الشيء في غير موضعه، ومن أحب من لا تجوز محبته فقد ظلم."], ["اقترفتموها", "اكتسبتموها."], ["كسادها", "بوارها وعدم رواجها."], ["فتربّصوا", "انتظروا."]], "m": "هذا إنذار الله للمؤمنين ينهاهم عن اتخاذ من كفر من آبائهم وإخوانهم أولياء يوادّونهم ويناصرونهم ويطلعونهم على أسرار المسلمين: يا أيها الذين آمنوا لا تتخذوا آباءكم وإخوانكم أولياء إن آثروا الكفر على الإيمان، ومن يتولّهم منكم فأولئك هم الظالمون، إذ وضعوا المحبة موضع البغضاء والنصرة موضع الخذلان. ثم أمر رسوله أن يقول لهم، وفي العدول عن خطابهم مباشرة ما يشعر بالغضب والتهديد: قل إن كان آباؤكم وأبناؤكم وإخوانكم وأزواجكم وعشيرتكم، وأموال اكتسبتموها، وتجارة تخشون كسادها، ومساكن ترضونها، أحب إليكم من الله ورسوله وجهاد في سبيله، فتركتم الهجرة والجهاد لذلك، فتربّصوا حتى يأتي الله بأمره، وهو فتح مكة وإنزال العقوبة بكم، والله لا يهدي القوم الفاسقين.", "h": ["حرمة اتخاذ الكافرين أولياء يُوادّون، ولو كانوا من أقرب الأقرباء كالأب والابن والأخ.", "من الظلم الفظيع موالاة من عادى الله ورسوله والمؤمنين.", "فرضية محبة الله ورسوله والجهاد في سبيله، ومحبة سائر محابّ الله تعالى، وكره سائر مكارهه من العقائد والأحوال والأعمال والذوات والصفات.", "حرمان أهل الفسق المتوغّلين فيه من هداية الله تعالى إلى ما يكملهم ويسعدهم."], "k": "«أحب إليكم من الله ورسوله»… لو وُضعت محابّي الثمانية في كفّة، فأين يقع حب الله ورسوله منها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (122, 9, 25, 35, 'سورة التوبة ٢٥ – ٣٥', '«ويوم حنين إذ أعجبتكم كثرتكم»، قتال أهل الكتاب حتى يعطوا الجزية، و«والذين يكنزون الذهب والفضة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 122) = $j$[{"lbl": "الآيات ٢٥ – ٢٨", "q": "لَقَدۡ نَصَرَكُمُ ٱللَّهُ فِي مَوَاطِنَ كَثِيرَةٖ وَيَوۡمَ حُنَيۡنٍ إِذۡ أَعۡجَبَتۡكُمۡ كَثۡرَتُكُمۡ فَلَمۡ تُغۡنِ عَنكُمۡ شَيۡـٔٗا وَضَاقَتۡ عَلَيۡكُمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ ثُمَّ وَلَّيۡتُم مُّدۡبِرِينَ ﴿٢٥﴾ ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَنزَلَ جُنُودٗا لَّمۡ تَرَوۡهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُواْۚ وَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ ﴿٢٦﴾ ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعۡدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٢٧﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡمُشۡرِكُونَ نَجَسٞ فَلَا يَقۡرَبُواْ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ بَعۡدَ عَامِهِمۡ هَٰذَاۚ وَإِنۡ خِفۡتُمۡ عَيۡلَةٗ فَسَوۡفَ يُغۡنِيكُمُ ٱللَّهُ مِن فَضۡلِهِۦٓ إِن شَآءَۚ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٞ ﴿٢٨﴾", "w": [["ويوم حنين", "حنين: وادٍ بين مكة والطائف، قاتل فيه الرسول ﷺ هوازن."], ["إذ أعجبتكم كثرتكم", "حين قال قائل منكم: لن نُغلب اليوم من قلة."], ["فلم تُغن عنكم شيئاً", "لم تُجزِ عنكم شيئاً من الإجزاء إذ انهزمتم في أول اللقاء."], ["وضاقت عليكم الأرض", "لم تعرفوا أين تذهبون وكيف تتصرّفون، كأنكم محصورون."], ["بما رحبت", "على رحابتها وسعتها."], ["سكينته", "الطمأنينة في نفوسهم، فذهب القلق والاضطراب."], ["وأنزل جنوداً", "من الملائكة."], ["نجس", "ذوو نجس، وذلك لخبث أرواحهم بالشرك."], ["بعد عامهم هذا", "عام تسعة من الهجرة."], ["عيلة", "فقراً وفاقة وحاجة."]], "m": "لما حرّم الله موالاة الكافرين ولو كانوا أقرباء، وحرّم القعود عن الهجرة والجهاد، وكان الغالب فيمن يقعد الجبن والخوف، أخبرهم أنه ناصرهم: لقد نصركم الله في مواطن كثيرة، كبدر والنضير وقريظة والفتح، ويوم حنين حين قاتلوا هوازن، مذكّراً بهزيمة أصابتهم بخطأ بعضهم، وهو الاغترار بالكثرة، إذ قال قائل: لن نُغلب اليوم من قلة، وكانوا اثني عشر ألفاً وعدوهم أربعة آلاف، فلما توغّلوا في الوادي رماهم العدو بوابل من النبل، فضاقت عليهم الأرض بما رحبت وولّوا مدبرين، ولم يثبت إلا رسول الله ﷺ على بغلته، والعباس إلى جنبه، وأبو سفيان بن الحارث ابن عمه، ثم نادى مناديه: يا أصحاب سورة البقرة، يا أصحاب السمرة، فتراجعوا، فأنزل الله سكينته على رسوله وعلى المؤمنين، وأنزل جنوداً من الملائكة لم تروها تنفخ في القلوب روح الشجاعة والثبات، فما هي إلا ساعة وإذا بالعدو سبي بين أيديهم، وبلغ عدد الإبل اثني عشر ألف بعير، وعذّب الذين كفروا بالقتل والسبي، وذلك جزاء الكافرين، ثم يتوب الله من بعد ذلك على من يشاء. يا أيها الذين آمنوا إنما المشركون نجس الظاهر والباطن فلا يقربوا المسجد الحرام بعد عامهم هذا، ومن يومئذ لم يدخل مكة مشرك، وإن خفتم فقراً لانقطاعهم عن الموسم بتجارتهم فسوف يغنيكم الله من فضله إن شاء، استثناء لتبقى القلوب متعلّقة به راجية خائفة، إن الله عليم حكيم.", "h": ["حرمة العجب بالنفس والعمل، إذ هو من العوائق الكبيرة عن النجاح.", "بيان إفضال الله تعالى وإكرامه لعباده المؤمنين.", "بيان الحكمة من القتال في سبيل الله تعالى.", "تقرير نجاسة الكافر المعنوية.", "منع دخول المشرك الحرم المكي كائناً من كان، بخلاف باقي المساجد، فقد يُؤذن للكافر لمصلحة أن يدخل بإذن المسلمين.", "لا يمنع المؤمن من امتثال أمر ربه الخوف من الفاقة والفقر، فإن الله تعالى تعهّد بالإغناء."], "k": "«إذ أعجبتكم كثرتكم فلم تُغن عنكم شيئاً»… على أي شيء أتّكل حين أُقدم على أمر: على ما في يدي، أم على ربي؟"}, {"lbl": "الآية ٢٩", "q": "قَٰتِلُواْ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلۡحَقِّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حَتَّىٰ يُعۡطُواْ ٱلۡجِزۡيَةَ عَن يَدٖ وَهُمۡ صَٰغِرُونَ ﴿٢٩﴾", "w": [["لا يؤمنون بالله ولا باليوم الآخر", "إيماناً صحيحاً يرضاه الله تعالى لموافقة الحق والواقع."], ["ولا يحرّمون ما حرّم الله ورسوله", "كالخمر والربا وسائر المحرمات."], ["ولا يدينون دين الحق", "الإسلام، إذ هو الدين الذي لا يقبل الله ديناً سواه."], ["من الذين أوتوا الكتاب", "اليهود والنصارى."], ["الجزية", "الخراج المعلوم الذي يدفعه الذمي كل سنة."], ["عن يد وهم صاغرون", "يقدّمونه بأيديهم لا يُنيبون فيه غيرهم، وهم أذلاء منقادون لحكم الإسلام."]], "m": "لما أمر الله بقتال المشركين حتى يتوبوا، أمر بقتال أهل الكتاب من اليهود والنصارى حتى يُسلموا أو يعطوا الجزية عن يد وهم صاغرون، وجعل إعطاء الجزية غاية القتال لا الإسلام، لأن الإسلام يُعرض عليهم أولاً، فإن رفضوه طُلب منهم الدخول في ذمة المسلمين وحمايتهم تحت شعار الجزية، فإذا أعطوها حقنوا دماءهم وحفظوا أموالهم وأمنوا في حياتهم. فإن قيل: اليهود والنصارى يؤمنون بالله واليوم الآخر، فكيف نفت الآية عنهم ذلك؟ فالجواب: أن اليهود في إيمانهم بالله مشبّهة مجسّمة، والنصارى يعتقدون أن الله حلّ في المسيح وأنه ثالث ثلاثة، فإيمانهم باطل، ولو آمنوا بالله لآمنوا برسوله محمد ﷺ، ولو آمنوا باليوم الآخر لأطاعوا الله ورسوله لينجوا من عذابه، والله أعلم بخلقه من أنفسهم.", "h": ["وجوب قتال أهل الكتاب حتى يُسلموا أو يدخلوا في حكم الإسلام، وذلك من أجل إعدادهم للإسلام ليكملوا عليه ويسعدوا به.", "الإيمان غير الصحيح لا يُعتبر إيماناً منجياً ولا مسعداً.", "استباحة ما حرّم الله من المطاعم والمشارب والمناكح كفر صريح.", "مشروعية أخذ الجزية من أهل الكتاب، وهي مقدّرة في كتب الفقه، مبيّنة حسب غنى المرء وفقره وسعته وضيقه."], "k": "«ولا يحرّمون ما حرّم الله ورسوله»… هل أستهين بحرام صغير كأنه ليس حراماً؟"}, {"lbl": "الآيات ٣٠ – ٣٣", "q": "وَقَالَتِ ٱلۡيَهُودُ عُزَيۡرٌ ٱبۡنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلۡمَسِيحُ ٱبۡنُ ٱللَّهِۖ ذَٰلِكَ قَوۡلُهُم بِأَفۡوَٰهِهِمۡۖ يُضَٰهِـُٔونَ قَوۡلَ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ ﴿٣٠﴾ ٱتَّخَذُوٓاْ أَحۡبَارَهُمۡ وَرُهۡبَٰنَهُمۡ أَرۡبَابٗا مِّن دُونِ ٱللَّهِ وَٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُوٓاْ إِلَٰهٗا وَٰحِدٗاۖ لَّآ إِلَٰهَ إِلَّا هُوَۚ سُبۡحَٰنَهُۥ عَمَّا يُشۡرِكُونَ ﴿٣١﴾ يُرِيدُونَ أَن يُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ وَيَأۡبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ ﴿٣٢﴾ هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ ﴿٣٣﴾", "w": [["عُزير", "رجل صالح من بني إسرائيل."], ["المسيح", "هو عيسى ابن مريم ﵉."], ["يضاهئون", "يشابهون."], ["قول الذين كفروا", "من آبائهم وأجدادهم الماضين."], ["قاتلهم الله", "لعنهم الله لأجل كفرهم."], ["أنّى يؤفكون", "كيف يُصرفون عن الحق؟"], ["أرباباً من دون الله", "آلهة يشرّعون لهم، فيعملون بشرائعهم من حلال وحرام."], ["نور الله", "الإسلام، لأنه هادٍ إلى الإسعاد والكمال في الدارين."], ["بأفواههم", "بالكذب عليه والطعن فيه وصرف الناس عنه."], ["رسوله", "محمداً ﷺ."]], "m": "لما أمر بقتال أهل الكتاب، ذكر ما يقرّر كفرهم: وقالت اليهود عزير ابن الله، وقالت النصارى المسيح ابن الله، ونسبة الولد إليه كفر بجلاله وكماله، ذلك قولهم بأفواههم فقط، ليس له من الواقع شيء، إذ كيف يكون له ولد ولم تكن له صاحبة؟ يضاهئون قول الذين كفروا من قبل، قاتلهم الله أنّى يؤفكون؟ اتخذوا أحبارهم، علماءهم، ورهبانهم، عبّادهم، أرباباً من دون الله، إذ قبلوا قولهم وأذعنوا له حتى أحلّوا لهم الحرام فأحلّوه، وحرّموا عليهم الحلال فحرّموه، والمسيح ابن مريم اتخذه النصارى رباً، وما أُمروا على ألسنة أنبيائهم إلا ليعبدوا إلهاً واحداً لا إله إلا هو، سبحانه عما يشركون. يريدون أن يطفئوا نور الله الذي هو الإسلام بأفواههم بالكذب والافتراء والانتقاص، ويأبى الله إلا أن يتم نوره ولو كره الكافرون، وقد فعل. هو الذي أرسل رسوله محمداً بالهدى، القرآن، ودين الحق، الإسلام، ليظهره على الدين كله ولو كره المشركون، وقد فعل، فالإسلام ظاهر في الأرض سمع به أهل الشرق والغرب، وسيأتي يوم يسود فيه المسلمون أهل الدنيا قاطبة بإذن الله.", "h": ["تقرير كفر اليهود والنصارى بذكر عقائدهم الكفرية.", "طاعة العلماء ورجال الدين طاعة عمياء حتى يحلّوا ويحرّموا فيُتّبعوا شرك.", "بيان عداء اليهود والنصارى للإسلام، وتعاونهم على إفساده وإفساد أهله.", "بشرى المسلمين بأنهم سيسودون العالم في يوم من الأيام، ويصبح الإسلام هو الدين الذي يُعبد الله به في الأرض لا غيره، ويشهد لهذا آية: «ويكون الدين كله لله»، فلو لم يعلم الله أن ذلك كائن لم يجعله غاية."], "k": "«اتخذوا أحبارهم ورهبانهم أرباباً»… هل أطيع أحداً في شيء أعلم أنه يخالف أمر ربي؟"}, {"lbl": "الآيتان ٣٤ – ٣٥", "q": "۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ كَثِيرٗا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَيَأۡكُلُونَ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۗ وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٖ ﴿٣٤﴾ يَوۡمَ يُحۡمَىٰ عَلَيۡهَا فِي نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ هَٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُواْ مَا كُنتُمۡ تَكۡنِزُونَ ﴿٣٥﴾", "w": [["بالباطل", "بدون حق أباح لهم أكلها."], ["ويصدّون عن سبيل الله", "يصرفون أنفسهم وغيرهم عن الإسلام، السبيل المفضي بالعبد إلى رضوان الله."], ["يكنزون", "يجمعون المال ويدفنونه حفاظاً عليه، ولا يؤدّون حقه."], ["الذهب والفضة", "هما النقدان المعروفان."], ["في سبيل الله", "حيث رضا الله، كالجهاد وإطعام الفقراء والمساكين."], ["فبشّرهم", "أخبرهم بعذاب أليم، أي موجع."], ["يُحمى عليها", "لأنها تُحوّل إلى صفائح يُحمى عليها، ثم تُكوى بها جباههم."], ["هذا ما كنزتم", "يقال لهم عند كيّهم بها: هذا ما كنزتم لأنفسكم، توبيخاً لهم."]], "m": "بمناسبة ذكر عداء اليهود والنصارى للإسلام، وأنهم يريدون دوماً المال والرئاسة، قال: يا أيها الذين آمنوا إن كثيراً من الأحبار، علماء اليهود، والرهبان، عبّاد النصارى، ليأكلون أموال الناس بالباطل، كالرشوة، وصكوك الغفران يبيعونها، وغير ذلك من الحيل باسم الدين، ويصدّون عن سبيل الله، دليل واضح على أنهم يحاربون الإسلام. والذين يكنزون الذهب والفضة ولا ينفقونها في سبيل الله، لفظ عام يشمل الأحبار والرهبان وغيرهم من المسلمين وأهل الكتاب، وإن كان الأحبار والرهبان أولى به، فبشّرهم بعذاب أليم، تعجيلاً للخبر في صورة بشارة: يوم يُحمى على صفائحها في نار جهنم فتُكوى بها جباههم وجنوبهم وظهورهم من كل الجهات، ويقال لهم تهكّماً، وهو عذاب على النفس أشد من عذاب الجسم: هذا ما كنزتم لأنفسكم، فذوقوا ما كنتم تكنزون.", "h": ["بيان حقيقة علماء اليهود والنصارى، وهي أنهم ماديّون باعوا آخرتهم بدنياهم، يحاربون الإسلام ويصدّون عنه للمحافظة على الرئاسة والأكل على حسابه.", "حرمة أكل أموال الناس بالباطل.", "حرمة جمع المال وكنزه وعدم الإنفاق منه.", "المال الذي تُؤدّى زكاته كل حول لا يقال له كنز، ولو دُفن تحت الأرض."], "k": "«هذا ما كنزتم لأنفسكم»… ما أكنزه اليوم: مالاً يُكوى به، أم صدقة تُظلّني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 122;
insert into public.tdb_cards(topic, i, body) select 122, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٥ – ٢٨", "q": "لَقَدۡ نَصَرَكُمُ ٱللَّهُ فِي مَوَاطِنَ كَثِيرَةٖ وَيَوۡمَ حُنَيۡنٍ إِذۡ أَعۡجَبَتۡكُمۡ كَثۡرَتُكُمۡ فَلَمۡ تُغۡنِ عَنكُمۡ شَيۡـٔٗا وَضَاقَتۡ عَلَيۡكُمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ ثُمَّ وَلَّيۡتُم مُّدۡبِرِينَ ﴿٢٥﴾ ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَنزَلَ جُنُودٗا لَّمۡ تَرَوۡهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُواْۚ وَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ ﴿٢٦﴾ ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعۡدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٢٧﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡمُشۡرِكُونَ نَجَسٞ فَلَا يَقۡرَبُواْ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ بَعۡدَ عَامِهِمۡ هَٰذَاۚ وَإِنۡ خِفۡتُمۡ عَيۡلَةٗ فَسَوۡفَ يُغۡنِيكُمُ ٱللَّهُ مِن فَضۡلِهِۦٓ إِن شَآءَۚ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٞ ﴿٢٨﴾", "w": [["ويوم حنين", "حنين: وادٍ بين مكة والطائف، قاتل فيه الرسول ﷺ هوازن."], ["إذ أعجبتكم كثرتكم", "حين قال قائل منكم: لن نُغلب اليوم من قلة."], ["فلم تُغن عنكم شيئاً", "لم تُجزِ عنكم شيئاً من الإجزاء إذ انهزمتم في أول اللقاء."], ["وضاقت عليكم الأرض", "لم تعرفوا أين تذهبون وكيف تتصرّفون، كأنكم محصورون."], ["بما رحبت", "على رحابتها وسعتها."], ["سكينته", "الطمأنينة في نفوسهم، فذهب القلق والاضطراب."], ["وأنزل جنوداً", "من الملائكة."], ["نجس", "ذوو نجس، وذلك لخبث أرواحهم بالشرك."], ["بعد عامهم هذا", "عام تسعة من الهجرة."], ["عيلة", "فقراً وفاقة وحاجة."]], "m": "لما حرّم الله موالاة الكافرين ولو كانوا أقرباء، وحرّم القعود عن الهجرة والجهاد، وكان الغالب فيمن يقعد الجبن والخوف، أخبرهم أنه ناصرهم: لقد نصركم الله في مواطن كثيرة، كبدر والنضير وقريظة والفتح، ويوم حنين حين قاتلوا هوازن، مذكّراً بهزيمة أصابتهم بخطأ بعضهم، وهو الاغترار بالكثرة، إذ قال قائل: لن نُغلب اليوم من قلة، وكانوا اثني عشر ألفاً وعدوهم أربعة آلاف، فلما توغّلوا في الوادي رماهم العدو بوابل من النبل، فضاقت عليهم الأرض بما رحبت وولّوا مدبرين، ولم يثبت إلا رسول الله ﷺ على بغلته، والعباس إلى جنبه، وأبو سفيان بن الحارث ابن عمه، ثم نادى مناديه: يا أصحاب سورة البقرة، يا أصحاب السمرة، فتراجعوا، فأنزل الله سكينته على رسوله وعلى المؤمنين، وأنزل جنوداً من الملائكة لم تروها تنفخ في القلوب روح الشجاعة والثبات، فما هي إلا ساعة وإذا بالعدو سبي بين أيديهم، وبلغ عدد الإبل اثني عشر ألف بعير، وعذّب الذين كفروا بالقتل والسبي، وذلك جزاء الكافرين، ثم يتوب الله من بعد ذلك على من يشاء. يا أيها الذين آمنوا إنما المشركون نجس الظاهر والباطن فلا يقربوا المسجد الحرام بعد عامهم هذا، ومن يومئذ لم يدخل مكة مشرك، وإن خفتم فقراً لانقطاعهم عن الموسم بتجارتهم فسوف يغنيكم الله من فضله إن شاء، استثناء لتبقى القلوب متعلّقة به راجية خائفة، إن الله عليم حكيم.", "h": ["حرمة العجب بالنفس والعمل، إذ هو من العوائق الكبيرة عن النجاح.", "بيان إفضال الله تعالى وإكرامه لعباده المؤمنين.", "بيان الحكمة من القتال في سبيل الله تعالى.", "تقرير نجاسة الكافر المعنوية.", "منع دخول المشرك الحرم المكي كائناً من كان، بخلاف باقي المساجد، فقد يُؤذن للكافر لمصلحة أن يدخل بإذن المسلمين.", "لا يمنع المؤمن من امتثال أمر ربه الخوف من الفاقة والفقر، فإن الله تعالى تعهّد بالإغناء."], "k": "«إذ أعجبتكم كثرتكم فلم تُغن عنكم شيئاً»… على أي شيء أتّكل حين أُقدم على أمر: على ما في يدي، أم على ربي؟"}, {"lbl": "الآية ٢٩", "q": "قَٰتِلُواْ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلۡحَقِّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ حَتَّىٰ يُعۡطُواْ ٱلۡجِزۡيَةَ عَن يَدٖ وَهُمۡ صَٰغِرُونَ ﴿٢٩﴾", "w": [["لا يؤمنون بالله ولا باليوم الآخر", "إيماناً صحيحاً يرضاه الله تعالى لموافقة الحق والواقع."], ["ولا يحرّمون ما حرّم الله ورسوله", "كالخمر والربا وسائر المحرمات."], ["ولا يدينون دين الحق", "الإسلام، إذ هو الدين الذي لا يقبل الله ديناً سواه."], ["من الذين أوتوا الكتاب", "اليهود والنصارى."], ["الجزية", "الخراج المعلوم الذي يدفعه الذمي كل سنة."], ["عن يد وهم صاغرون", "يقدّمونه بأيديهم لا يُنيبون فيه غيرهم، وهم أذلاء منقادون لحكم الإسلام."]], "m": "لما أمر الله بقتال المشركين حتى يتوبوا، أمر بقتال أهل الكتاب من اليهود والنصارى حتى يُسلموا أو يعطوا الجزية عن يد وهم صاغرون، وجعل إعطاء الجزية غاية القتال لا الإسلام، لأن الإسلام يُعرض عليهم أولاً، فإن رفضوه طُلب منهم الدخول في ذمة المسلمين وحمايتهم تحت شعار الجزية، فإذا أعطوها حقنوا دماءهم وحفظوا أموالهم وأمنوا في حياتهم. فإن قيل: اليهود والنصارى يؤمنون بالله واليوم الآخر، فكيف نفت الآية عنهم ذلك؟ فالجواب: أن اليهود في إيمانهم بالله مشبّهة مجسّمة، والنصارى يعتقدون أن الله حلّ في المسيح وأنه ثالث ثلاثة، فإيمانهم باطل، ولو آمنوا بالله لآمنوا برسوله محمد ﷺ، ولو آمنوا باليوم الآخر لأطاعوا الله ورسوله لينجوا من عذابه، والله أعلم بخلقه من أنفسهم.", "h": ["وجوب قتال أهل الكتاب حتى يُسلموا أو يدخلوا في حكم الإسلام، وذلك من أجل إعدادهم للإسلام ليكملوا عليه ويسعدوا به.", "الإيمان غير الصحيح لا يُعتبر إيماناً منجياً ولا مسعداً.", "استباحة ما حرّم الله من المطاعم والمشارب والمناكح كفر صريح.", "مشروعية أخذ الجزية من أهل الكتاب، وهي مقدّرة في كتب الفقه، مبيّنة حسب غنى المرء وفقره وسعته وضيقه."], "k": "«ولا يحرّمون ما حرّم الله ورسوله»… هل أستهين بحرام صغير كأنه ليس حراماً؟"}, {"lbl": "الآيات ٣٠ – ٣٣", "q": "وَقَالَتِ ٱلۡيَهُودُ عُزَيۡرٌ ٱبۡنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلۡمَسِيحُ ٱبۡنُ ٱللَّهِۖ ذَٰلِكَ قَوۡلُهُم بِأَفۡوَٰهِهِمۡۖ يُضَٰهِـُٔونَ قَوۡلَ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ ﴿٣٠﴾ ٱتَّخَذُوٓاْ أَحۡبَارَهُمۡ وَرُهۡبَٰنَهُمۡ أَرۡبَابٗا مِّن دُونِ ٱللَّهِ وَٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُوٓاْ إِلَٰهٗا وَٰحِدٗاۖ لَّآ إِلَٰهَ إِلَّا هُوَۚ سُبۡحَٰنَهُۥ عَمَّا يُشۡرِكُونَ ﴿٣١﴾ يُرِيدُونَ أَن يُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ وَيَأۡبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ ﴿٣٢﴾ هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ ﴿٣٣﴾", "w": [["عُزير", "رجل صالح من بني إسرائيل."], ["المسيح", "هو عيسى ابن مريم ﵉."], ["يضاهئون", "يشابهون."], ["قول الذين كفروا", "من آبائهم وأجدادهم الماضين."], ["قاتلهم الله", "لعنهم الله لأجل كفرهم."], ["أنّى يؤفكون", "كيف يُصرفون عن الحق؟"], ["أرباباً من دون الله", "آلهة يشرّعون لهم، فيعملون بشرائعهم من حلال وحرام."], ["نور الله", "الإسلام، لأنه هادٍ إلى الإسعاد والكمال في الدارين."], ["بأفواههم", "بالكذب عليه والطعن فيه وصرف الناس عنه."], ["رسوله", "محمداً ﷺ."]], "m": "لما أمر بقتال أهل الكتاب، ذكر ما يقرّر كفرهم: وقالت اليهود عزير ابن الله، وقالت النصارى المسيح ابن الله، ونسبة الولد إليه كفر بجلاله وكماله، ذلك قولهم بأفواههم فقط، ليس له من الواقع شيء، إذ كيف يكون له ولد ولم تكن له صاحبة؟ يضاهئون قول الذين كفروا من قبل، قاتلهم الله أنّى يؤفكون؟ اتخذوا أحبارهم، علماءهم، ورهبانهم، عبّادهم، أرباباً من دون الله، إذ قبلوا قولهم وأذعنوا له حتى أحلّوا لهم الحرام فأحلّوه، وحرّموا عليهم الحلال فحرّموه، والمسيح ابن مريم اتخذه النصارى رباً، وما أُمروا على ألسنة أنبيائهم إلا ليعبدوا إلهاً واحداً لا إله إلا هو، سبحانه عما يشركون. يريدون أن يطفئوا نور الله الذي هو الإسلام بأفواههم بالكذب والافتراء والانتقاص، ويأبى الله إلا أن يتم نوره ولو كره الكافرون، وقد فعل. هو الذي أرسل رسوله محمداً بالهدى، القرآن، ودين الحق، الإسلام، ليظهره على الدين كله ولو كره المشركون، وقد فعل، فالإسلام ظاهر في الأرض سمع به أهل الشرق والغرب، وسيأتي يوم يسود فيه المسلمون أهل الدنيا قاطبة بإذن الله.", "h": ["تقرير كفر اليهود والنصارى بذكر عقائدهم الكفرية.", "طاعة العلماء ورجال الدين طاعة عمياء حتى يحلّوا ويحرّموا فيُتّبعوا شرك.", "بيان عداء اليهود والنصارى للإسلام، وتعاونهم على إفساده وإفساد أهله.", "بشرى المسلمين بأنهم سيسودون العالم في يوم من الأيام، ويصبح الإسلام هو الدين الذي يُعبد الله به في الأرض لا غيره، ويشهد لهذا آية: «ويكون الدين كله لله»، فلو لم يعلم الله أن ذلك كائن لم يجعله غاية."], "k": "«اتخذوا أحبارهم ورهبانهم أرباباً»… هل أطيع أحداً في شيء أعلم أنه يخالف أمر ربي؟"}, {"lbl": "الآيتان ٣٤ – ٣٥", "q": "۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ كَثِيرٗا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَيَأۡكُلُونَ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۗ وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٖ ﴿٣٤﴾ يَوۡمَ يُحۡمَىٰ عَلَيۡهَا فِي نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ هَٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُواْ مَا كُنتُمۡ تَكۡنِزُونَ ﴿٣٥﴾", "w": [["بالباطل", "بدون حق أباح لهم أكلها."], ["ويصدّون عن سبيل الله", "يصرفون أنفسهم وغيرهم عن الإسلام، السبيل المفضي بالعبد إلى رضوان الله."], ["يكنزون", "يجمعون المال ويدفنونه حفاظاً عليه، ولا يؤدّون حقه."], ["الذهب والفضة", "هما النقدان المعروفان."], ["في سبيل الله", "حيث رضا الله، كالجهاد وإطعام الفقراء والمساكين."], ["فبشّرهم", "أخبرهم بعذاب أليم، أي موجع."], ["يُحمى عليها", "لأنها تُحوّل إلى صفائح يُحمى عليها، ثم تُكوى بها جباههم."], ["هذا ما كنزتم", "يقال لهم عند كيّهم بها: هذا ما كنزتم لأنفسكم، توبيخاً لهم."]], "m": "بمناسبة ذكر عداء اليهود والنصارى للإسلام، وأنهم يريدون دوماً المال والرئاسة، قال: يا أيها الذين آمنوا إن كثيراً من الأحبار، علماء اليهود، والرهبان، عبّاد النصارى، ليأكلون أموال الناس بالباطل، كالرشوة، وصكوك الغفران يبيعونها، وغير ذلك من الحيل باسم الدين، ويصدّون عن سبيل الله، دليل واضح على أنهم يحاربون الإسلام. والذين يكنزون الذهب والفضة ولا ينفقونها في سبيل الله، لفظ عام يشمل الأحبار والرهبان وغيرهم من المسلمين وأهل الكتاب، وإن كان الأحبار والرهبان أولى به، فبشّرهم بعذاب أليم، تعجيلاً للخبر في صورة بشارة: يوم يُحمى على صفائحها في نار جهنم فتُكوى بها جباههم وجنوبهم وظهورهم من كل الجهات، ويقال لهم تهكّماً، وهو عذاب على النفس أشد من عذاب الجسم: هذا ما كنزتم لأنفسكم، فذوقوا ما كنتم تكنزون.", "h": ["بيان حقيقة علماء اليهود والنصارى، وهي أنهم ماديّون باعوا آخرتهم بدنياهم، يحاربون الإسلام ويصدّون عنه للمحافظة على الرئاسة والأكل على حسابه.", "حرمة أكل أموال الناس بالباطل.", "حرمة جمع المال وكنزه وعدم الإنفاق منه.", "المال الذي تُؤدّى زكاته كل حول لا يقال له كنز، ولو دُفن تحت الأرض."], "k": "«هذا ما كنزتم لأنفسكم»… ما أكنزه اليوم: مالاً يُكوى به، أم صدقة تُظلّني؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (123, 9, 36, 43, 'سورة التوبة ٣٦ – ٤٣', '«إن عدة الشهور عند الله اثنا عشر شهراً»، «إلا تنصروه فقد نصره الله»، و«انفروا خفافاً وثقالاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 123) = $j$[{"lbl": "الآيتان ٣٦ – ٣٧", "q": "إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ شَهۡرٗا فِي كِتَٰبِ ٱللَّهِ يَوۡمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ مِنۡهَآ أَرۡبَعَةٌ حُرُمٞۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُۚ فَلَا تَظۡلِمُواْ فِيهِنَّ أَنفُسَكُمۡۚ وَقَٰتِلُواْ ٱلۡمُشۡرِكِينَ كَآفَّةٗ كَمَا يُقَٰتِلُونَكُمۡ كَآفَّةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ ﴿٣٦﴾ إِنَّمَا ٱلنَّسِيٓءُ زِيَادَةٞ فِي ٱلۡكُفۡرِۖ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُواْ يُحِلُّونَهُۥ عَامٗا وَيُحَرِّمُونَهُۥ عَامٗا لِّيُوَاطِـُٔواْ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّواْ مَا حَرَّمَ ٱللَّهُۚ زُيِّنَ لَهُمۡ سُوٓءُ أَعۡمَٰلِهِمۡۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ ﴿٣٧﴾", "w": [["الشهور", "جمع شهر، والشهر تسعة وعشرون يوماً أو ثلاثون يوماً."], ["في كتاب الله", "كتاب المقادير: اللوح المحفوظ."], ["أربعة حُرُم", "هي رجب، وذو القعدة، وذو الحجة، والمحرم، الواحد منها حرام، والجمع حُرُم."], ["الدين القيّم", "الشرع المستقيم الذي لا اعوجاج فيه."], ["فلا تظلموا فيهن أنفسكم", "لا ترتكبوا في الأشهر الحرم المعاصي، فإنها أشد قبحاً فيها."], ["كافّة", "جميعاً، وفي كل الشهور حلالها وحرامها."], ["مع المتقين", "بالتأييد والنصر، والمتقون هم الذين لا يعصون الله تعالى."], ["إنما النسيء", "تأخير حرمة شهر المحرم إلى صفر."], ["يحلّونه عاماً ويحرّمونه عاماً", "أي النسيء، عاماً يحلّونه وعاماً يحرّمونه."], ["ليواطئوا عدة ما حرّم الله", "ليوافقوا عدد الشهور المحرّمة، وهي أربعة."], ["زُيّن لهم سوء أعمالهم", "زيّن لهم الشيطان هذا التأخير للشهر الحرام، وهو عمل سيئ لأنه افتيات على الشارع واحتيال على تحليل الحرام."]], "m": "عاد السياق إلى المشركين: إن عدة الشهور عند الله اثنا عشر شهراً لا تزيد ولا تنقص، هكذا في اللوح المحفوظ يوم خلق السماوات والأرض، منها أربعة حرم: رجب وذو القعدة وذو الحجة والمحرم، حرّم الله القتال فيها لتكون هدنة يتمكّن العرب معها من السفر للتجارة والحج والعمرة، ولما أعز الله الإسلام نسخ حرمة القتال فيها، ذلك الدين القيّم، فلا تظلموا فيهن أنفسكم بارتكاب الذنوب، فإنها توجب غضب الله وسخطه. وقاتلوا المشركين بعد انتهاء المدة كافّة لا يتأخر منكم أحد، كما يقاتلونكم مجتمعين، واعلموا أن الله مع المتقين بنصره وتأييده. إنما النسيء، تأخير حرمة المحرم إلى صفر كما تفعل الجاهلية ليستبيحوا القتال في الشهر الحرام، زيادة في الكفر، لأنه محاربة لشرع الله، يُضل به الذين كفروا فيزدادون ضلالاً، يحلّونه عاماً ويحرّمونه عاماً ليوافقوا عدد الأشهر الحرم، ظناً أنهم ما عصوا، مستترين بهذه الفتيا الإبليسية، زُيّن لهم سوء أعمالهم، والله لا يهدي القوم الكافرين، عقوبة لهم على كفرهم.", "h": ["بيان أن الأشهر الحرم أربعة، وقد بيّنها الرسول ﷺ، وهي: رجب، وذو القعدة، وذو الحجة، والمحرم.", "حرمة الأشهر الحرم، ومضاعفة السيئات فيها، أي قبح الذنوب فيها.", "صفة المعيّة لله تعالى، وهي معيّة خاصة بالنصر والتأييد لأهل تقواه.", "حرمة الاحتيال على الشرع بالفتاوى الباطلة لإحلال الحرام، وأن هذا الاحتيال ما هو إلا زيادة في الإثم.", "تزيين الباطل وتحسين المنكر من الشيطان.", "حرمان أهل الكفر والفسق من هداية الله تعالى وتوفيقه لما هو حق وخير، حالاً ومآلاً."], "k": "«فلا تظلموا فيهن أنفسكم»… في الأوقات الفاضلة، هل أزيد طاعتي، أم يمرّ الشهر الحرام كغيره؟"}, {"lbl": "الآيات ٣٨ – ٤٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَا لَكُمۡ إِذَا قِيلَ لَكُمُ ٱنفِرُواْ فِي سَبِيلِ ٱللَّهِ ٱثَّاقَلۡتُمۡ إِلَى ٱلۡأَرۡضِۚ أَرَضِيتُم بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا مِنَ ٱلۡأٓخِرَةِۚ فَمَا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا قَلِيلٌ ﴿٣٨﴾ إِلَّا تَنفِرُواْ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا وَيَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّوهُ شَيۡـٔٗاۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿٣٩﴾ إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودٖ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ ﴿٤٠﴾", "w": [["ما لكم", "أي شيء ثبت لكم من الأعذار؟"], ["انفروا", "اخرجوا مستعجلين مندفعين."], ["اثّاقلتم", "تباطأتم كأنكم تحملون أثقالاً."], ["إلا تنصروه", "أي الرسول محمداً ﷺ."], ["ثاني اثنين", "هو وأبو بكر رضي الله عنه."], ["لصاحبه", "هو أبو بكر الصديق رضي الله عنه."], ["سكينته", "طمأنينته."], ["كلمة الذين كفروا", "هي الدعوة إلى الشرك."], ["السفلى", "مغلوبة هابطة لا يُسمع لها صوت."], ["وكلمة الله هي العليا", "دعوة التوحيد (لا إله إلا الله محمد رسول الله) هي العليا الغالبة الظاهرة."]], "m": "نزلت في غزوة تبوك، فقد بلغ النبي ﷺ أن هرقل ملك الروم جمع جموعه لحربه، فأعلن التعبئة العامة، وكان الزمن صيفاً حاراً، وبالبلاد جدب ومجاعة، في شوال سنة تسع، وسُمّيت غزوة العسرة، فاستحثّ الرب المؤمنين: يا أيها الذين آمنوا ما لكم إذا قيل لكم انفروا في سبيل الله لأجل رضاه، اثّاقلتم إلى الأرض راضين بالبقاء في دوركم؟ أرضيتم بالحياة الدنيا من الآخرة؟ فما متاع الحياة الدنيا في الآخرة إلا قليل تافه، فكيف تؤثرون القليل الفاني على الكثير الباقي؟ إلا تنفروا وتتركوه يخرج إلى قتال الروم وحده يعذّبكم عذاباً أليماً ويستبدل قوماً غيركم ولا تضرّوه شيئاً، وعيد اهتزّت له القلوب. إلا تنصروه فقد نصره الله في ظرف أصعب، إذ أخرجه الذين كفروا ثاني اثنين إذ هما في الغار، إذ يقول لصاحبه، وقد قال: لو نظر أحدهم تحت قدميه لرآنا يا رسول الله: لا تحزن إن الله معنا، فأنزل الله سكينته عليه فاطمأن، وأيّده بجنود لم تروها، وجعل كلمة الذين كفروا السفلى مغلوبة، وكلمة الله هي العليا الغالبة الظاهرة، والله عزيز حكيم.", "h": ["وجوب الخروج إلى الجهاد إذا دعا الإمام بالدعوة العامة، وهو ما يُعرف بالتعبئة العامة أو النفير العام.", "يجب أن يكون النفير في سبيل الله، لا في سبيل غيره تعالى.", "بيان حقارة الدنيا وضآلتها أمام الآخرة.", "وجوب نصرة رسول الله ﷺ في دينه، وفي أمته، وفي سنته.", "شرف أبي بكر الصديق وبيان فضله.", "الإسلام يعلو ولا يُعلى عليه."], "k": "«لا تحزن إن الله معنا»… في أضيق ساعاتي، هل أتذكّر هذه المعيّة؟"}, {"lbl": "الآيات ٤١ – ٤٣", "q": "ٱنفِرُواْ خِفَافٗا وَثِقَالٗا وَجَٰهِدُواْ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ فِي سَبِيلِ ٱللَّهِۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٤١﴾ لَوۡ كَانَ عَرَضٗا قَرِيبٗا وَسَفَرٗا قَاصِدٗا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتۡ عَلَيۡهِمُ ٱلشُّقَّةُۚ وَسَيَحۡلِفُونَ بِٱللَّهِ لَوِ ٱسۡتَطَعۡنَا لَخَرَجۡنَا مَعَكُمۡ يُهۡلِكُونَ أَنفُسَهُمۡ وَٱللَّهُ يَعۡلَمُ إِنَّهُمۡ لَكَٰذِبُونَ ﴿٤٢﴾ عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمۡ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُواْ وَتَعۡلَمَ ٱلۡكَٰذِبِينَ ﴿٤٣﴾", "w": [["خفافاً وثقالاً", "الخفاف: جمع خفيف، وهو الشاب القوي البدن ذو الجِدة من زاد ومركوب، والثقال: جمع ثقيل، وهو الشيخ الكبير والمريض والفقير الذي لا جِدة عنده."], ["ذلكم", "أي الجهاد بالمال والنفس خير من التثاقل إلى الأرض وترك الجهاد."], ["عرضاً قريباً", "غنيمة في مكان قريب غير بعيد."], ["وسفراً قاصداً", "معتدلاً لا مشقة فيه."], ["عفا الله عنك", "لم يؤاخذك."]], "m": "ما زال السياق في الحث على الخروج إلى قتال الروم بالشام: انفروا خفافاً وثقالاً، على أي حال كان، من قوة أو ضعف، الشاب القوي كالكبير العاجز، والغني كالفقير، وجاهدوا بأموالكم وأنفسكم في سبيل الله حتى يدخل الكافرون في الإسلام أو يعطوا الجزية، ذلكم خير لكم من الخلود إلى الأرض إن كنتم تعلمون. لو كان ما دعوت إليه المتخلّفين من المنافقين وضعفة الإيمان غنيمة حاضرة أو سفراً سهلاً معتدلاً لاتبعوك، ولكن دعوتهم إلى تبوك في زمن الحر والحاجة فبعدت عليهم الشقة، فانتحلوا الأعذار، وسيحلفون بالله: لو استطعنا لخرجنا معكم، يهلكون أنفسهم بجلب سخط الله، والله يعلم إنهم لكاذبون. ثم عاتب نبيه ﷺ إذ أذن لمن استأذنه في التخلّف، وكان الأرشد ألا يأذن لأحد حتى يتميّز الصادق من الكاذب: عفا الله عنك، وقدّمه على العتاب تعجيلاً للمسرّة له، لم أذنت لهم حتى يتبيّن لك الذين صدقوا وتعلم الكاذبين؟", "h": ["إذا أعلن الإمام التعبئة العامة يحرم التخلّف عن الجهاد، ولا يقعد أحد إلا بإذن، لأجل علة قامت به فاستأذن فأُذن له.", "الجهاد كما يكون بالنفس يكون بالمال، وهو خير من تركه حالاً ومآلاً.", "الأيمان الكاذبة لإبطال حق أو إحقاق باطل توجب سخط الله تعالى وعذابه.", "مشروعية العتاب للمحب.", "جواز مخالفة الأولى على النبي ﷺ لعدم علمه ما لم يعلّمه الله تعالى."], "k": "«لو كان عرضاً قريباً وسفراً قاصداً لاتبعوك»… هل طاعتي مشروطة بأن تكون سهلة قريبة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 123;
insert into public.tdb_cards(topic, i, body) select 123, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٣٦ – ٣٧", "q": "إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ شَهۡرٗا فِي كِتَٰبِ ٱللَّهِ يَوۡمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ مِنۡهَآ أَرۡبَعَةٌ حُرُمٞۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُۚ فَلَا تَظۡلِمُواْ فِيهِنَّ أَنفُسَكُمۡۚ وَقَٰتِلُواْ ٱلۡمُشۡرِكِينَ كَآفَّةٗ كَمَا يُقَٰتِلُونَكُمۡ كَآفَّةٗۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ ﴿٣٦﴾ إِنَّمَا ٱلنَّسِيٓءُ زِيَادَةٞ فِي ٱلۡكُفۡرِۖ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُواْ يُحِلُّونَهُۥ عَامٗا وَيُحَرِّمُونَهُۥ عَامٗا لِّيُوَاطِـُٔواْ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّواْ مَا حَرَّمَ ٱللَّهُۚ زُيِّنَ لَهُمۡ سُوٓءُ أَعۡمَٰلِهِمۡۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ ﴿٣٧﴾", "w": [["الشهور", "جمع شهر، والشهر تسعة وعشرون يوماً أو ثلاثون يوماً."], ["في كتاب الله", "كتاب المقادير: اللوح المحفوظ."], ["أربعة حُرُم", "هي رجب، وذو القعدة، وذو الحجة، والمحرم، الواحد منها حرام، والجمع حُرُم."], ["الدين القيّم", "الشرع المستقيم الذي لا اعوجاج فيه."], ["فلا تظلموا فيهن أنفسكم", "لا ترتكبوا في الأشهر الحرم المعاصي، فإنها أشد قبحاً فيها."], ["كافّة", "جميعاً، وفي كل الشهور حلالها وحرامها."], ["مع المتقين", "بالتأييد والنصر، والمتقون هم الذين لا يعصون الله تعالى."], ["إنما النسيء", "تأخير حرمة شهر المحرم إلى صفر."], ["يحلّونه عاماً ويحرّمونه عاماً", "أي النسيء، عاماً يحلّونه وعاماً يحرّمونه."], ["ليواطئوا عدة ما حرّم الله", "ليوافقوا عدد الشهور المحرّمة، وهي أربعة."], ["زُيّن لهم سوء أعمالهم", "زيّن لهم الشيطان هذا التأخير للشهر الحرام، وهو عمل سيئ لأنه افتيات على الشارع واحتيال على تحليل الحرام."]], "m": "عاد السياق إلى المشركين: إن عدة الشهور عند الله اثنا عشر شهراً لا تزيد ولا تنقص، هكذا في اللوح المحفوظ يوم خلق السماوات والأرض، منها أربعة حرم: رجب وذو القعدة وذو الحجة والمحرم، حرّم الله القتال فيها لتكون هدنة يتمكّن العرب معها من السفر للتجارة والحج والعمرة، ولما أعز الله الإسلام نسخ حرمة القتال فيها، ذلك الدين القيّم، فلا تظلموا فيهن أنفسكم بارتكاب الذنوب، فإنها توجب غضب الله وسخطه. وقاتلوا المشركين بعد انتهاء المدة كافّة لا يتأخر منكم أحد، كما يقاتلونكم مجتمعين، واعلموا أن الله مع المتقين بنصره وتأييده. إنما النسيء، تأخير حرمة المحرم إلى صفر كما تفعل الجاهلية ليستبيحوا القتال في الشهر الحرام، زيادة في الكفر، لأنه محاربة لشرع الله، يُضل به الذين كفروا فيزدادون ضلالاً، يحلّونه عاماً ويحرّمونه عاماً ليوافقوا عدد الأشهر الحرم، ظناً أنهم ما عصوا، مستترين بهذه الفتيا الإبليسية، زُيّن لهم سوء أعمالهم، والله لا يهدي القوم الكافرين، عقوبة لهم على كفرهم.", "h": ["بيان أن الأشهر الحرم أربعة، وقد بيّنها الرسول ﷺ، وهي: رجب، وذو القعدة، وذو الحجة، والمحرم.", "حرمة الأشهر الحرم، ومضاعفة السيئات فيها، أي قبح الذنوب فيها.", "صفة المعيّة لله تعالى، وهي معيّة خاصة بالنصر والتأييد لأهل تقواه.", "حرمة الاحتيال على الشرع بالفتاوى الباطلة لإحلال الحرام، وأن هذا الاحتيال ما هو إلا زيادة في الإثم.", "تزيين الباطل وتحسين المنكر من الشيطان.", "حرمان أهل الكفر والفسق من هداية الله تعالى وتوفيقه لما هو حق وخير، حالاً ومآلاً."], "k": "«فلا تظلموا فيهن أنفسكم»… في الأوقات الفاضلة، هل أزيد طاعتي، أم يمرّ الشهر الحرام كغيره؟"}, {"lbl": "الآيات ٣٨ – ٤٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَا لَكُمۡ إِذَا قِيلَ لَكُمُ ٱنفِرُواْ فِي سَبِيلِ ٱللَّهِ ٱثَّاقَلۡتُمۡ إِلَى ٱلۡأَرۡضِۚ أَرَضِيتُم بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا مِنَ ٱلۡأٓخِرَةِۚ فَمَا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا قَلِيلٌ ﴿٣٨﴾ إِلَّا تَنفِرُواْ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا وَيَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّوهُ شَيۡـٔٗاۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿٣٩﴾ إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودٖ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ ﴿٤٠﴾", "w": [["ما لكم", "أي شيء ثبت لكم من الأعذار؟"], ["انفروا", "اخرجوا مستعجلين مندفعين."], ["اثّاقلتم", "تباطأتم كأنكم تحملون أثقالاً."], ["إلا تنصروه", "أي الرسول محمداً ﷺ."], ["ثاني اثنين", "هو وأبو بكر رضي الله عنه."], ["لصاحبه", "هو أبو بكر الصديق رضي الله عنه."], ["سكينته", "طمأنينته."], ["كلمة الذين كفروا", "هي الدعوة إلى الشرك."], ["السفلى", "مغلوبة هابطة لا يُسمع لها صوت."], ["وكلمة الله هي العليا", "دعوة التوحيد (لا إله إلا الله محمد رسول الله) هي العليا الغالبة الظاهرة."]], "m": "نزلت في غزوة تبوك، فقد بلغ النبي ﷺ أن هرقل ملك الروم جمع جموعه لحربه، فأعلن التعبئة العامة، وكان الزمن صيفاً حاراً، وبالبلاد جدب ومجاعة، في شوال سنة تسع، وسُمّيت غزوة العسرة، فاستحثّ الرب المؤمنين: يا أيها الذين آمنوا ما لكم إذا قيل لكم انفروا في سبيل الله لأجل رضاه، اثّاقلتم إلى الأرض راضين بالبقاء في دوركم؟ أرضيتم بالحياة الدنيا من الآخرة؟ فما متاع الحياة الدنيا في الآخرة إلا قليل تافه، فكيف تؤثرون القليل الفاني على الكثير الباقي؟ إلا تنفروا وتتركوه يخرج إلى قتال الروم وحده يعذّبكم عذاباً أليماً ويستبدل قوماً غيركم ولا تضرّوه شيئاً، وعيد اهتزّت له القلوب. إلا تنصروه فقد نصره الله في ظرف أصعب، إذ أخرجه الذين كفروا ثاني اثنين إذ هما في الغار، إذ يقول لصاحبه، وقد قال: لو نظر أحدهم تحت قدميه لرآنا يا رسول الله: لا تحزن إن الله معنا، فأنزل الله سكينته عليه فاطمأن، وأيّده بجنود لم تروها، وجعل كلمة الذين كفروا السفلى مغلوبة، وكلمة الله هي العليا الغالبة الظاهرة، والله عزيز حكيم.", "h": ["وجوب الخروج إلى الجهاد إذا دعا الإمام بالدعوة العامة، وهو ما يُعرف بالتعبئة العامة أو النفير العام.", "يجب أن يكون النفير في سبيل الله، لا في سبيل غيره تعالى.", "بيان حقارة الدنيا وضآلتها أمام الآخرة.", "وجوب نصرة رسول الله ﷺ في دينه، وفي أمته، وفي سنته.", "شرف أبي بكر الصديق وبيان فضله.", "الإسلام يعلو ولا يُعلى عليه."], "k": "«لا تحزن إن الله معنا»… في أضيق ساعاتي، هل أتذكّر هذه المعيّة؟"}, {"lbl": "الآيات ٤١ – ٤٣", "q": "ٱنفِرُواْ خِفَافٗا وَثِقَالٗا وَجَٰهِدُواْ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ فِي سَبِيلِ ٱللَّهِۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٤١﴾ لَوۡ كَانَ عَرَضٗا قَرِيبٗا وَسَفَرٗا قَاصِدٗا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتۡ عَلَيۡهِمُ ٱلشُّقَّةُۚ وَسَيَحۡلِفُونَ بِٱللَّهِ لَوِ ٱسۡتَطَعۡنَا لَخَرَجۡنَا مَعَكُمۡ يُهۡلِكُونَ أَنفُسَهُمۡ وَٱللَّهُ يَعۡلَمُ إِنَّهُمۡ لَكَٰذِبُونَ ﴿٤٢﴾ عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمۡ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُواْ وَتَعۡلَمَ ٱلۡكَٰذِبِينَ ﴿٤٣﴾", "w": [["خفافاً وثقالاً", "الخفاف: جمع خفيف، وهو الشاب القوي البدن ذو الجِدة من زاد ومركوب، والثقال: جمع ثقيل، وهو الشيخ الكبير والمريض والفقير الذي لا جِدة عنده."], ["ذلكم", "أي الجهاد بالمال والنفس خير من التثاقل إلى الأرض وترك الجهاد."], ["عرضاً قريباً", "غنيمة في مكان قريب غير بعيد."], ["وسفراً قاصداً", "معتدلاً لا مشقة فيه."], ["عفا الله عنك", "لم يؤاخذك."]], "m": "ما زال السياق في الحث على الخروج إلى قتال الروم بالشام: انفروا خفافاً وثقالاً، على أي حال كان، من قوة أو ضعف، الشاب القوي كالكبير العاجز، والغني كالفقير، وجاهدوا بأموالكم وأنفسكم في سبيل الله حتى يدخل الكافرون في الإسلام أو يعطوا الجزية، ذلكم خير لكم من الخلود إلى الأرض إن كنتم تعلمون. لو كان ما دعوت إليه المتخلّفين من المنافقين وضعفة الإيمان غنيمة حاضرة أو سفراً سهلاً معتدلاً لاتبعوك، ولكن دعوتهم إلى تبوك في زمن الحر والحاجة فبعدت عليهم الشقة، فانتحلوا الأعذار، وسيحلفون بالله: لو استطعنا لخرجنا معكم، يهلكون أنفسهم بجلب سخط الله، والله يعلم إنهم لكاذبون. ثم عاتب نبيه ﷺ إذ أذن لمن استأذنه في التخلّف، وكان الأرشد ألا يأذن لأحد حتى يتميّز الصادق من الكاذب: عفا الله عنك، وقدّمه على العتاب تعجيلاً للمسرّة له، لم أذنت لهم حتى يتبيّن لك الذين صدقوا وتعلم الكاذبين؟", "h": ["إذا أعلن الإمام التعبئة العامة يحرم التخلّف عن الجهاد، ولا يقعد أحد إلا بإذن، لأجل علة قامت به فاستأذن فأُذن له.", "الجهاد كما يكون بالنفس يكون بالمال، وهو خير من تركه حالاً ومآلاً.", "الأيمان الكاذبة لإبطال حق أو إحقاق باطل توجب سخط الله تعالى وعذابه.", "مشروعية العتاب للمحب.", "جواز مخالفة الأولى على النبي ﷺ لعدم علمه ما لم يعلّمه الله تعالى."], "k": "«لو كان عرضاً قريباً وسفراً قاصداً لاتبعوك»… هل طاعتي مشروطة بأن تكون سهلة قريبة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (124, 9, 44, 60, 'سورة التوبة ٤٤ – ٦٠', 'المنافقون في غزوة تبوك: «ولا تفتني»، «قل هل تربّصون بنا إلا إحدى الحسنيين»، و«إنما الصدقات للفقراء»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 124) = $j$[{"lbl": "الآيات ٤٤ – ٤٦", "q": "لَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ ﴿٤٤﴾ إِنَّمَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱرۡتَابَتۡ قُلُوبُهُمۡ فَهُمۡ فِي رَيۡبِهِمۡ يَتَرَدَّدُونَ ﴿٤٥﴾ ۞وَلَوۡ أَرَادُواْ ٱلۡخُرُوجَ لَأَعَدُّواْ لَهُۥ عُدَّةٗ وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمۡ فَثَبَّطَهُمۡ وَقِيلَ ٱقۡعُدُواْ مَعَ ٱلۡقَٰعِدِينَ ﴿٤٦﴾", "w": [["لا يستأذنك", "لا يطلبون منك إذناً بالتخلّف عن الجهاد."], ["وارتابت قلوبهم", "شكّت في صحة ما تدعو إليه من الدين الحق."], ["في ريبهم", "في شكّهم."], ["يتردّدون", "حيارى لا يثبتون على شيء."], ["لأعدّوا له عدة", "لهيّؤوا له ما يلزم من سلاح وزاد ومركوب."], ["فثبّطهم", "ألقى في نفوسهم الرغبة في التخلّف وحبّبه إليهم، فكسلوا ولم يخرجوا."]], "m": "بعد أن عاتب الله رسوله في إذنه للمتخلّفين أخبره: لا يستأذنك المؤمنون الصادقون أن يتخلّفوا عن الجهاد بأموالهم وأنفسهم، والله عليم بالمتقين، إنما يستأذنك الذين لا يؤمنون بالله واليوم الآخر، وارتابت قلوبهم في الإيمان بالله ورسوله ووعده ووعيده، فهم في ريبهم يتردّدون حيارى، وهي حالة المزعزع العقيدة كسائر المنافقين. وهم كاذبون في اعتذاراتهم، إذ لو أرادوا الخروج لأعدّوا له عدته من سلاح وزاد وراحلة، ولكنهم كانوا عازمين على عدم الخروج بحال، ولو لم تأذن لهم لتخلّفوا متحدّين أمرك، ولكن كره الله انبعاثهم لما فيه من الضرر والخطر، فثبّطهم بما ألقى في قلوبهم من الفشل وفي أجسامهم من الكسل، وقيل: اقعدوا مع القاعدين.", "h": ["فضيلة الإيمان والتقوى، إذ صاحبهما لا يمكنه أن يتخلّف عن الجهاد بالنفس والمال.", "خطر الشك في العقيدة، وأنه سبب الحيرة والتردّد، وصاحبه لا يقدر على أن يجاهد.", "سوابق الشر تحول بين صاحبها وبين فعل الخير."], "k": "«ولو أرادوا الخروج لأعدّوا له عدة»… الطاعة التي أنويها، هل أعددت لها أسبابها، أم أكتفي بالتمنّي؟"}, {"lbl": "الآيتان ٤٧ – ٤٨", "q": "لَوۡ خَرَجُواْ فِيكُم مَّا زَادُوكُمۡ إِلَّا خَبَالٗا وَلَأَوۡضَعُواْ خِلَٰلَكُمۡ يَبۡغُونَكُمُ ٱلۡفِتۡنَةَ وَفِيكُمۡ سَمَّـٰعُونَ لَهُمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلظَّـٰلِمِينَ ﴿٤٧﴾ لَقَدِ ٱبۡتَغَوُاْ ٱلۡفِتۡنَةَ مِن قَبۡلُ وَقَلَّبُواْ لَكَ ٱلۡأُمُورَ حَتَّىٰ جَآءَ ٱلۡحَقُّ وَظَهَرَ أَمۡرُ ٱللَّهِ وَهُمۡ كَٰرِهُونَ ﴿٤٨﴾", "w": [["لو خرجوا فيكم", "مندسّين بين رجالكم."], ["خبالاً", "الفساد في الرأي والتدبير."], ["ولأوضعوا خلالكم", "لأسرعوا بينكم بالنميمة والتحريش والإثارة لإيقاعكم في الفتنة."], ["وفيكم سمّاعون لهم", "بينكم من يكثر السماع لهم والتأثّر بأقوالهم المثيرة الفاسدة."], ["من قبل", "عند مجيئك المدينة مهاجراً."], ["وقلّبوا لك الأمور", "بالكيد والمكر، والاتصال باليهود والمشركين والتعاون معهم."], ["وظهر أمر الله", "بأن فُتحت مكة ودخل الناس في دين الله أفواجاً."], ["وهم كارهون", "لمجيء الحق وظهور أمر الله بانتصار دينه."]], "m": "ما زال السياق في فضح نوايا المنافقين: لو خرجوا فيكم إلى تبوك ما زادوكم إلا خبالاً، ضرراً وفساداً وبلبلة لأفكار المؤمنين بما ينفثونه من التخذيل، ولأوضعوا خلالكم، أسرعوا بين صفوفكم بكلمات التثبيط، يبغونكم الفتنة بتفريق جمعكم وإثارة العداوة بينكم، كما يحسنه المنافقون في كل زمان ومكان، وفيكم ضعاف إيمان يسمعون منكم وينقلون لهم أسراركم، ومن يسمع لهم ويطيعهم، والله عليم بالظالمين، فلذا صرفهم عن الخروج معكم. لقد ابتغوا الفتنة من قبل، من يوم هاجرت إلى المدينة، وفي أحد رجع ابن أُبيّ بثلث الجيش، وقلّبوا لك الأمور بقصد القضاء على دعوتك، فظاهروا المشركين واليهود، حتى جاء الحق بفتح مكة، وظهر أمر الله بدخول أكثر العرب في دينه، وهم كارهون آسفون، فلا تأسفوا على عدم خروجهم، فإن الله رحمة بكم صرفهم عنكم.", "h": ["وجود منافقين في صفوف المؤمنين خطر عليهم وضرر كبير لهم، فلذا ينبغي ألّا يُشركوا في أمر، وألّا يُعوّل عليهم في مهمة.", "وجوب الأخذ بالحيطة في الأمور ذات البال والأثر على حياة الإسلام والمسلمين.", "المنافق يسوؤه عزة الإسلام والمسلمين ويحزن لذلك.", "تدبير الله تعالى لأوليائه خير تدبير، فلذا وجب الرضا بقضاء الله وقدره والتسليم به."], "k": "«وفيكم سمّاعون لهم»… هل أنقل كلام الفتنة، أم أقطعه عندي؟"}, {"lbl": "الآيات ٤٩ – ٥٢", "q": "وَمِنۡهُم مَّن يَقُولُ ٱئۡذَن لِّي وَلَا تَفۡتِنِّيٓۚ أَلَا فِي ٱلۡفِتۡنَةِ سَقَطُواْۗ وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ ﴿٤٩﴾ إِن تُصِبۡكَ حَسَنَةٞ تَسُؤۡهُمۡۖ وَإِن تُصِبۡكَ مُصِيبَةٞ يَقُولُواْ قَدۡ أَخَذۡنَآ أَمۡرَنَا مِن قَبۡلُ وَيَتَوَلَّواْ وَّهُمۡ فَرِحُونَ ﴿٥٠﴾ قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوۡلَىٰنَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿٥١﴾ قُلۡ هَلۡ تَرَبَّصُونَ بِنَآ إِلَّآ إِحۡدَى ٱلۡحُسۡنَيَيۡنِۖ وَنَحۡنُ نَتَرَبَّصُ بِكُمۡ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٖ مِّنۡ عِندِهِۦٓ أَوۡ بِأَيۡدِينَاۖ فَتَرَبَّصُوٓاْ إِنَّا مَعَكُم مُّتَرَبِّصُونَ ﴿٥٢﴾", "w": [["ومنهم", "من المنافقين، وهو الجد بن قيس."], ["ائذن لي", "في التخلّف عن الجهاد."], ["ولا تفتنّي", "لا توقعني في الفتنة، بدعوى أنه إذا رأى نساء الروم لا يملك نفسه."], ["حسنة تسؤهم", "الحسنة: كل ما يحسن من نصر وغنيمة وعافية، وتسؤهم: يكربون لها ويحزنون."], ["قد أخذنا أمرنا من قبل", "احتطنا للأمر، ولذا لم نخرج معهم."], ["إحدى الحسنيين", "الأولى: الظفر بالعدو والانتصار عليه، والثانية: الشهادة المورثة للجنة."], ["فتربّصوا", "انتظروا، فإنا معكم من المنتظرين."]], "m": "ما زال السياق في المنافقين المتخلّفين عن تبوك: ومنهم من يقول: ائذن لي في التخلّف ولا تفتنّي، فقد روي أن النبي ﷺ قال له: «هل لك في بلاد بني الأصفر؟» فقال: إني مغرم بالنساء، وأخشى إن رأيت نساء بني الأصفر، الروم، لا أصبر عنهن فأُفتن، والقائل الجد بن قيس أحد زعماء المنافقين، فقال تعالى: ألا في الفتنة سقطوا، وأي فتنة أعظم من الشرك والنفاق؟ وإن جهنم لمحيطة بالكافرين. إن تصبك حسنة من نصر أو غنيمة تسؤهم، وإن تصبك مصيبة من هزيمة أو قتل يقولوا: قد أخذنا أمرنا من قبل فاحتطنا ولم نخرج، ويتولّوا إلى بيوتهم وهم فرحون. قل لن يصيبنا إلا ما كتب الله لنا، وما يكتبه ربنا لنا لن يكون إلا خيراً، هو مولانا، وعلى الله فليتوكّل المؤمنون. قل هل تربّصون بنا إلا إحدى الحسنيين: النصر والظهور على أهل الشرك، أو الاستشهاد ثم النعيم المقيم؟ ونحن نتربّص بكم أن يصيبكم الله بعذاب من عنده أو بأيدينا، فتربّصوا إنا معكم متربّصون.", "h": ["فضيحة الجد بن قيس، وتسجيل اللعنة عليه، وتبشيره بجهنم.", "بيان فرح المنافقين والكافرين بما يسوء المسلمين، واستيائهم لما يفرح المسلمين، وهي علامة النفاق البارزة في كل منافق.", "وجوب التوكل على الله، وعدم الاهتمام بأقوال المنافقين.", "بيان أن المؤمنين بين خيارين في جهادهم: النصر أو الشهادة.", "مشروعية القول الذي يغيظ العدو ويحزنه."], "k": "«قل لن يصيبنا إلا ما كتب الله لنا»… هل أستقبل ما يصيبني موقناً أن ما كتبه مولاي لي خير؟"}, {"lbl": "الآيات ٥٣ – ٥٥", "q": "قُلۡ أَنفِقُواْ طَوۡعًا أَوۡ كَرۡهٗا لَّن يُتَقَبَّلَ مِنكُمۡ إِنَّكُمۡ كُنتُمۡ قَوۡمٗا فَٰسِقِينَ ﴿٥٣﴾ وَمَا مَنَعَهُمۡ أَن تُقۡبَلَ مِنۡهُمۡ نَفَقَٰتُهُمۡ إِلَّآ أَنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأۡتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمۡ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمۡ كَٰرِهُونَ ﴿٥٤﴾ فَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ ﴿٥٥﴾", "w": [["طوعاً أو كرهاً", "وأنتم طائعون أو مكرهون على الإنفاق."], ["إنكم كنتم قوماً فاسقين", "الجملة علّة لعدم قبول نفقاتهم."], ["كسالى", "متثاقلون، لعدم إيمانهم في الباطن بفائدة الصلاة."], ["فلا تعجبك أموالهم", "لا تستحسنوا أيها المسلمون ما عند المنافقين من مال وولد."], ["وتزهق أنفسهم", "تفيض وتخرج من أجسامهم."]], "m": "ما زال السياق في تعليم الرسول ﷺ كيف يردّ على المنافقين: قل أنفقوا طائعين أو مكرهين لن يُتقبّل منكم ما تنفقونه في الخروج إلى تبوك أو غيره، إنكم كنتم قوماً فاسقين بكفركم. وما منعهم أن تُقبل منهم نفقاتهم إلا ثلاثة: أنهم كفروا بالله وبرسوله، ولا يأتون الصلاة إلا وهم كسالى، ولا ينفقون إلا وهم كارهون. فلا تعجبك أموالهم ولا أولادهم مهما كثرت وحسنت، إنما يريد الله ليعذّبهم بها في الحياة الدنيا: فالمال ينفقونه في الجهاد مكرهين، إذ لا يريدون نصر الإسلام ولا ظهوره، والأولاد يشاهدونهم يدخلون في الإسلام ويعملون به، ولا يستطيعون ردّهم، وأي ألم أكبر من أن يكفر ولد الرجل بدينه ويدين بآخر، وتزهق أنفسهم وهم كافرون فينتقلون من عذاب إلى عذاب أشد، وبهذا سلّى الله رسوله والمؤمنين.", "h": ["تقرير مبدأ أن الرياء مبطل للعمل، كالشرك محبط للعمل.", "إطلاق الفسق على الكفر، فكل كافر فاسق على الإطلاق.", "حرمة التكاسل في الصلاة، وأن ذلك من صفات المنافقين.", "وجوب رضا النفس بما ينفق العبد في سبيل الله، زكاة أو غيرها.", "كراهية استحسان المسلم لما عند أهل الفسق والنفاق من مال ومتاع."], "k": "«ولا يأتون الصلاة إلا وهم كسالى»… كيف أقوم إلى صلاتي: بشوق، أم بتثاقل؟"}, {"lbl": "الآيات ٥٦ – ٥٩", "q": "وَيَحۡلِفُونَ بِٱللَّهِ إِنَّهُمۡ لَمِنكُمۡ وَمَا هُم مِّنكُمۡ وَلَٰكِنَّهُمۡ قَوۡمٞ يَفۡرَقُونَ ﴿٥٦﴾ لَوۡ يَجِدُونَ مَلۡجَـًٔا أَوۡ مَغَٰرَٰتٍ أَوۡ مُدَّخَلٗا لَّوَلَّوۡاْ إِلَيۡهِ وَهُمۡ يَجۡمَحُونَ ﴿٥٧﴾ وَمِنۡهُم مَّن يَلۡمِزُكَ فِي ٱلصَّدَقَٰتِ فَإِنۡ أُعۡطُواْ مِنۡهَا رَضُواْ وَإِن لَّمۡ يُعۡطَوۡاْ مِنۡهَآ إِذَا هُمۡ يَسۡخَطُونَ ﴿٥٨﴾ وَلَوۡ أَنَّهُمۡ رَضُواْ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُواْ حَسۡبُنَا ٱللَّهُ سَيُؤۡتِينَا ٱللَّهُ مِن فَضۡلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ ﴿٥٩﴾", "w": [["وما هم منكم", "في باطن الأمر، لأنهم كافرون، وجوههم وقلوبهم مع الكافرين."], ["يفرقون", "يخافون خوفاً شديداً منكم."], ["ملجأ", "مكاناً حصيناً يلجؤون إليه."], ["أو مغارات", "جمع مغارة، وهي الغار في الجبل."], ["أو مُدّخلاً", "سرباً في الأرض يستتر فيه الخائف الهارب."], ["يلمزك", "يعيبك ويطعن فيك."], ["حسبنا الله", "كافينا الله كل ما يهمّنا."], ["إلى الله راغبون", "إلى الله وحده راغبون، طامعون راجون."]], "m": "ما زال السياق في هتك أستار المنافقين ليتوب منهم من أكرمه الله: ويحلفون بالله إنهم لمنكم، من أهل ملّتكم، وما هم منكم في واقع الأمر، ولكنهم قوم يفرقون منكم خوفاً شديداً، فيحلفون لتأمنوهم على أرواحهم وأموالهم، لو يجدون حصناً أو غيراناً في الجبال أو سرباً في الأرض لولّوا إليه وهم يجمحون مسرعين. ومنهم من يلمزك في قسمة الصدقات ويتّهمك بعدم العدل، فإن أُعطوا منها رضوا، وإن لم يُعطوا إذا هم يسخطون. ثم أرشدهم إلى أحسن ما يكونون عليه: ولو أنهم رضوا ما آتاهم الله ورسوله من الصدقات، وقالوا: حسبنا الله، سيؤتينا الله من فضله ورسوله بما يقسمه بيننا، إنا إلى الله وحده راغبون، لكان خيراً لهم.", "h": ["الأيمان الكاذبة شعار المنافقين، وفي الحديث: «آية المنافق ثلاث: إذا حدّث كذب، وإذا وعد أخلف، وإذا اؤتمن خان».", "الجبن والخور والضعف والخوف من لوازم الكفر والنفاق.", "عيب الصالحين والطعن فيهم ظاهرة دالة على فساد قلوب ونيات من يفعل ذلك.", "مظاهر الرحمة الإلهية تتجلّى في إرشاد المنافقين إلى أحسن ما يكونون عليه ليكملوا ويسعدوا.", "لا كافي إلا الله، ووجوب انحصار الرغبة فيه تعالى وحده دون سواه."], "k": "«وقالوا حسبنا الله سيؤتينا الله من فضله»… حين أُحرم من عطاء، هل أسخط، أم أقولها راضياً؟"}, {"lbl": "الآية ٦٠", "q": "۞إِنَّمَا ٱلصَّدَقَٰتُ لِلۡفُقَرَآءِ وَٱلۡمَسَٰكِينِ وَٱلۡعَٰمِلِينَ عَلَيۡهَا وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ وَفِي ٱلرِّقَابِ وَٱلۡغَٰرِمِينَ وَفِي سَبِيلِ ٱللَّهِ وَٱبۡنِ ٱلسَّبِيلِۖ فَرِيضَةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٦٠﴾", "w": [["الصدقات", "جمع صدقة، وهي هنا الزكاة المفروضة في الأموال."], ["للفقراء", "جمع فقير، وهو من ليس له ما يكفيه من القوت ولا يسأل الناس."], ["والمساكين", "جمع مسكين، وهو فقير ليس له ما يكفيه، ويسأل الناس ويذلّ نفسه لهم."], ["والعاملين عليها", "على جمعها وجبايتها، وهم الموظفون لها."], ["والمؤلّفة قلوبهم", "أناس يُرجى إسلامهم أو بقاؤهم عليه إن كانوا قد أسلموا، وهم ذوو شأن وخطر ينفع الله بهم إن أسلموا وحسن إسلامهم."], ["وفي الرقاب", "في فك الرقاب وتحريرها من الرق، فيُعطى المكاتَبون ما يسدّدون به أقساط كتابتهم."], ["والغارمين", "المدينين الذين استدانوا لأنفسهم وعيالهم، وليس لديهم ما يسدّدون به ديونهم."], ["وابن السبيل", "المسافر المنقطع عن بلاده، ولو كان غنياً ببلاده."], ["فريضة من الله", "فرضها الله تعالى فريضة على عباده المؤمنين."]], "m": "بمناسبة لمز المنافقين الرسول ﷺ في قسمة الصدقات، بيّن الله أهلها المختصّين بها: إنما الصدقات محصورة في ثمانية أصناف: الفقراء الذين لا يجدون ما يسدّ حاجتهم الضرورية، والمساكين الذين لا يجدون ذلك فيسألون الناس ويُظهرون المسكنة، والعاملين عليها من سعاة وجباة وأمناء وكتّاب وموزّعين، يُعطون أجرة على عملهم، والمؤلّفة قلوبهم ممن يُرجى نفعهم للإسلام لمناصبهم وشوكتهم في أقوامهم، فيُعطى من لم يسلم ترغيباً، ومن ضعف إسلامه تثبيتاً، وفي الرقاب بمساعدة المكاتَبين على تسديد أقساطهم، أما شراء عبد بالزكاة وتحريره فلا يجوز لأنه يعود بالنفع على دافعها، إذ ولاء المعتوق له، والغارمين، وفي سبيل الله بتجهيز الغزاة والإنفاق عليهم تسليحاً وإركاباً وطعاماً ولباساً، وابن السبيل، فريضة من الله لازمة على عباده، والله عليم بخلقه حكيم في شرعه، فلا يجوز أن يُعطى منها من ليس مذكوراً في الآية، وليس شرطاً أن تُعطى كل الأصناف، فقد يعطي المرء زكاته كلها في صنف واحد فتجزئه، وإن كان الأولى أن يقسمها بين من وُجد منهم.", "h": ["تقرير فرضية الزكاة.", "بيان مصارف الزكاة.", "وجوب التسليم لله تعالى في قسمته، بعدم محاولة الخروج عنها.", "إثبات صفات الله تعالى، وهي هنا: العلم والحكمة، ومتى كان الله عليماً بخلقه وحاجاتهم، حكيماً في تصرّفه وشرعه، وجب التسليم لأمره والخضوع له بالطاعة والانقياد."], "k": "«فريضة من الله»… هل أؤدّي زكاتي كاملة إلى أهلها، وأتحرّى من يستحقها؟"}]$j$::jsonb then 0 else 1 end;
