insert into public.tdb_cards(topic, i, body) select 124, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٤ – ٤٦", "q": "لَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ ﴿٤٤﴾ إِنَّمَا يَسۡتَـٔۡذِنُكَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱرۡتَابَتۡ قُلُوبُهُمۡ فَهُمۡ فِي رَيۡبِهِمۡ يَتَرَدَّدُونَ ﴿٤٥﴾ ۞وَلَوۡ أَرَادُواْ ٱلۡخُرُوجَ لَأَعَدُّواْ لَهُۥ عُدَّةٗ وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمۡ فَثَبَّطَهُمۡ وَقِيلَ ٱقۡعُدُواْ مَعَ ٱلۡقَٰعِدِينَ ﴿٤٦﴾", "w": [["لا يستأذنك", "لا يطلبون منك إذناً بالتخلّف عن الجهاد."], ["وارتابت قلوبهم", "شكّت في صحة ما تدعو إليه من الدين الحق."], ["في ريبهم", "في شكّهم."], ["يتردّدون", "حيارى لا يثبتون على شيء."], ["لأعدّوا له عدة", "لهيّؤوا له ما يلزم من سلاح وزاد ومركوب."], ["فثبّطهم", "ألقى في نفوسهم الرغبة في التخلّف وحبّبه إليهم، فكسلوا ولم يخرجوا."]], "m": "بعد أن عاتب الله رسوله في إذنه للمتخلّفين أخبره: لا يستأذنك المؤمنون الصادقون أن يتخلّفوا عن الجهاد بأموالهم وأنفسهم، والله عليم بالمتقين، إنما يستأذنك الذين لا يؤمنون بالله واليوم الآخر، وارتابت قلوبهم في الإيمان بالله ورسوله ووعده ووعيده، فهم في ريبهم يتردّدون حيارى، وهي حالة المزعزع العقيدة كسائر المنافقين. وهم كاذبون في اعتذاراتهم، إذ لو أرادوا الخروج لأعدّوا له عدته من سلاح وزاد وراحلة، ولكنهم كانوا عازمين على عدم الخروج بحال، ولو لم تأذن لهم لتخلّفوا متحدّين أمرك، ولكن كره الله انبعاثهم لما فيه من الضرر والخطر، فثبّطهم بما ألقى في قلوبهم من الفشل وفي أجسامهم من الكسل، وقيل: اقعدوا مع القاعدين.", "h": ["فضيلة الإيمان والتقوى، إذ صاحبهما لا يمكنه أن يتخلّف عن الجهاد بالنفس والمال.", "خطر الشك في العقيدة، وأنه سبب الحيرة والتردّد، وصاحبه لا يقدر على أن يجاهد.", "سوابق الشر تحول بين صاحبها وبين فعل الخير."], "k": "«ولو أرادوا الخروج لأعدّوا له عدة»… الطاعة التي أنويها، هل أعددت لها أسبابها، أم أكتفي بالتمنّي؟"}, {"lbl": "الآيتان ٤٧ – ٤٨", "q": "لَوۡ خَرَجُواْ فِيكُم مَّا زَادُوكُمۡ إِلَّا خَبَالٗا وَلَأَوۡضَعُواْ خِلَٰلَكُمۡ يَبۡغُونَكُمُ ٱلۡفِتۡنَةَ وَفِيكُمۡ سَمَّـٰعُونَ لَهُمۡۗ وَٱللَّهُ عَلِيمُۢ بِٱلظَّـٰلِمِينَ ﴿٤٧﴾ لَقَدِ ٱبۡتَغَوُاْ ٱلۡفِتۡنَةَ مِن قَبۡلُ وَقَلَّبُواْ لَكَ ٱلۡأُمُورَ حَتَّىٰ جَآءَ ٱلۡحَقُّ وَظَهَرَ أَمۡرُ ٱللَّهِ وَهُمۡ كَٰرِهُونَ ﴿٤٨﴾", "w": [["لو خرجوا فيكم", "مندسّين بين رجالكم."], ["خبالاً", "الفساد في الرأي والتدبير."], ["ولأوضعوا خلالكم", "لأسرعوا بينكم بالنميمة والتحريش والإثارة لإيقاعكم في الفتنة."], ["وفيكم سمّاعون لهم", "بينكم من يكثر السماع لهم والتأثّر بأقوالهم المثيرة الفاسدة."], ["من قبل", "عند مجيئك المدينة مهاجراً."], ["وقلّبوا لك الأمور", "بالكيد والمكر، والاتصال باليهود والمشركين والتعاون معهم."], ["وظهر أمر الله", "بأن فُتحت مكة ودخل الناس في دين الله أفواجاً."], ["وهم كارهون", "لمجيء الحق وظهور أمر الله بانتصار دينه."]], "m": "ما زال السياق في فضح نوايا المنافقين: لو خرجوا فيكم إلى تبوك ما زادوكم إلا خبالاً، ضرراً وفساداً وبلبلة لأفكار المؤمنين بما ينفثونه من التخذيل، ولأوضعوا خلالكم، أسرعوا بين صفوفكم بكلمات التثبيط، يبغونكم الفتنة بتفريق جمعكم وإثارة العداوة بينكم، كما يحسنه المنافقون في كل زمان ومكان، وفيكم ضعاف إيمان يسمعون منكم وينقلون لهم أسراركم، ومن يسمع لهم ويطيعهم، والله عليم بالظالمين، فلذا صرفهم عن الخروج معكم. لقد ابتغوا الفتنة من قبل، من يوم هاجرت إلى المدينة، وفي أحد رجع ابن أُبيّ بثلث الجيش، وقلّبوا لك الأمور بقصد القضاء على دعوتك، فظاهروا المشركين واليهود، حتى جاء الحق بفتح مكة، وظهر أمر الله بدخول أكثر العرب في دينه، وهم كارهون آسفون، فلا تأسفوا على عدم خروجهم، فإن الله رحمة بكم صرفهم عنكم.", "h": ["وجود منافقين في صفوف المؤمنين خطر عليهم وضرر كبير لهم، فلذا ينبغي ألّا يُشركوا في أمر، وألّا يُعوّل عليهم في مهمة.", "وجوب الأخذ بالحيطة في الأمور ذات البال والأثر على حياة الإسلام والمسلمين.", "المنافق يسوؤه عزة الإسلام والمسلمين ويحزن لذلك.", "تدبير الله تعالى لأوليائه خير تدبير، فلذا وجب الرضا بقضاء الله وقدره والتسليم به."], "k": "«وفيكم سمّاعون لهم»… هل أنقل كلام الفتنة، أم أقطعه عندي؟"}, {"lbl": "الآيات ٤٩ – ٥٢", "q": "وَمِنۡهُم مَّن يَقُولُ ٱئۡذَن لِّي وَلَا تَفۡتِنِّيٓۚ أَلَا فِي ٱلۡفِتۡنَةِ سَقَطُواْۗ وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ ﴿٤٩﴾ إِن تُصِبۡكَ حَسَنَةٞ تَسُؤۡهُمۡۖ وَإِن تُصِبۡكَ مُصِيبَةٞ يَقُولُواْ قَدۡ أَخَذۡنَآ أَمۡرَنَا مِن قَبۡلُ وَيَتَوَلَّواْ وَّهُمۡ فَرِحُونَ ﴿٥٠﴾ قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوۡلَىٰنَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿٥١﴾ قُلۡ هَلۡ تَرَبَّصُونَ بِنَآ إِلَّآ إِحۡدَى ٱلۡحُسۡنَيَيۡنِۖ وَنَحۡنُ نَتَرَبَّصُ بِكُمۡ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٖ مِّنۡ عِندِهِۦٓ أَوۡ بِأَيۡدِينَاۖ فَتَرَبَّصُوٓاْ إِنَّا مَعَكُم مُّتَرَبِّصُونَ ﴿٥٢﴾", "w": [["ومنهم", "من المنافقين، وهو الجد بن قيس."], ["ائذن لي", "في التخلّف عن الجهاد."], ["ولا تفتنّي", "لا توقعني في الفتنة، بدعوى أنه إذا رأى نساء الروم لا يملك نفسه."], ["حسنة تسؤهم", "الحسنة: كل ما يحسن من نصر وغنيمة وعافية، وتسؤهم: يكربون لها ويحزنون."], ["قد أخذنا أمرنا من قبل", "احتطنا للأمر، ولذا لم نخرج معهم."], ["إحدى الحسنيين", "الأولى: الظفر بالعدو والانتصار عليه، والثانية: الشهادة المورثة للجنة."], ["فتربّصوا", "انتظروا، فإنا معكم من المنتظرين."]], "m": "ما زال السياق في المنافقين المتخلّفين عن تبوك: ومنهم من يقول: ائذن لي في التخلّف ولا تفتنّي، فقد روي أن النبي ﷺ قال له: «هل لك في بلاد بني الأصفر؟» فقال: إني مغرم بالنساء، وأخشى إن رأيت نساء بني الأصفر، الروم، لا أصبر عنهن فأُفتن، والقائل الجد بن قيس أحد زعماء المنافقين، فقال تعالى: ألا في الفتنة سقطوا، وأي فتنة أعظم من الشرك والنفاق؟ وإن جهنم لمحيطة بالكافرين. إن تصبك حسنة من نصر أو غنيمة تسؤهم، وإن تصبك مصيبة من هزيمة أو قتل يقولوا: قد أخذنا أمرنا من قبل فاحتطنا ولم نخرج، ويتولّوا إلى بيوتهم وهم فرحون. قل لن يصيبنا إلا ما كتب الله لنا، وما يكتبه ربنا لنا لن يكون إلا خيراً، هو مولانا، وعلى الله فليتوكّل المؤمنون. قل هل تربّصون بنا إلا إحدى الحسنيين: النصر والظهور على أهل الشرك، أو الاستشهاد ثم النعيم المقيم؟ ونحن نتربّص بكم أن يصيبكم الله بعذاب من عنده أو بأيدينا، فتربّصوا إنا معكم متربّصون.", "h": ["فضيحة الجد بن قيس، وتسجيل اللعنة عليه، وتبشيره بجهنم.", "بيان فرح المنافقين والكافرين بما يسوء المسلمين، واستيائهم لما يفرح المسلمين، وهي علامة النفاق البارزة في كل منافق.", "وجوب التوكل على الله، وعدم الاهتمام بأقوال المنافقين.", "بيان أن المؤمنين بين خيارين في جهادهم: النصر أو الشهادة.", "مشروعية القول الذي يغيظ العدو ويحزنه."], "k": "«قل لن يصيبنا إلا ما كتب الله لنا»… هل أستقبل ما يصيبني موقناً أن ما كتبه مولاي لي خير؟"}, {"lbl": "الآيات ٥٣ – ٥٥", "q": "قُلۡ أَنفِقُواْ طَوۡعًا أَوۡ كَرۡهٗا لَّن يُتَقَبَّلَ مِنكُمۡ إِنَّكُمۡ كُنتُمۡ قَوۡمٗا فَٰسِقِينَ ﴿٥٣﴾ وَمَا مَنَعَهُمۡ أَن تُقۡبَلَ مِنۡهُمۡ نَفَقَٰتُهُمۡ إِلَّآ أَنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأۡتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمۡ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمۡ كَٰرِهُونَ ﴿٥٤﴾ فَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ ﴿٥٥﴾", "w": [["طوعاً أو كرهاً", "وأنتم طائعون أو مكرهون على الإنفاق."], ["إنكم كنتم قوماً فاسقين", "الجملة علّة لعدم قبول نفقاتهم."], ["كسالى", "متثاقلون، لعدم إيمانهم في الباطن بفائدة الصلاة."], ["فلا تعجبك أموالهم", "لا تستحسنوا أيها المسلمون ما عند المنافقين من مال وولد."], ["وتزهق أنفسهم", "تفيض وتخرج من أجسامهم."]], "m": "ما زال السياق في تعليم الرسول ﷺ كيف يردّ على المنافقين: قل أنفقوا طائعين أو مكرهين لن يُتقبّل منكم ما تنفقونه في الخروج إلى تبوك أو غيره، إنكم كنتم قوماً فاسقين بكفركم. وما منعهم أن تُقبل منهم نفقاتهم إلا ثلاثة: أنهم كفروا بالله وبرسوله، ولا يأتون الصلاة إلا وهم كسالى، ولا ينفقون إلا وهم كارهون. فلا تعجبك أموالهم ولا أولادهم مهما كثرت وحسنت، إنما يريد الله ليعذّبهم بها في الحياة الدنيا: فالمال ينفقونه في الجهاد مكرهين، إذ لا يريدون نصر الإسلام ولا ظهوره، والأولاد يشاهدونهم يدخلون في الإسلام ويعملون به، ولا يستطيعون ردّهم، وأي ألم أكبر من أن يكفر ولد الرجل بدينه ويدين بآخر، وتزهق أنفسهم وهم كافرون فينتقلون من عذاب إلى عذاب أشد، وبهذا سلّى الله رسوله والمؤمنين.", "h": ["تقرير مبدأ أن الرياء مبطل للعمل، كالشرك محبط للعمل.", "إطلاق الفسق على الكفر، فكل كافر فاسق على الإطلاق.", "حرمة التكاسل في الصلاة، وأن ذلك من صفات المنافقين.", "وجوب رضا النفس بما ينفق العبد في سبيل الله، زكاة أو غيرها.", "كراهية استحسان المسلم لما عند أهل الفسق والنفاق من مال ومتاع."], "k": "«ولا يأتون الصلاة إلا وهم كسالى»… كيف أقوم إلى صلاتي: بشوق، أم بتثاقل؟"}, {"lbl": "الآيات ٥٦ – ٥٩", "q": "وَيَحۡلِفُونَ بِٱللَّهِ إِنَّهُمۡ لَمِنكُمۡ وَمَا هُم مِّنكُمۡ وَلَٰكِنَّهُمۡ قَوۡمٞ يَفۡرَقُونَ ﴿٥٦﴾ لَوۡ يَجِدُونَ مَلۡجَـًٔا أَوۡ مَغَٰرَٰتٍ أَوۡ مُدَّخَلٗا لَّوَلَّوۡاْ إِلَيۡهِ وَهُمۡ يَجۡمَحُونَ ﴿٥٧﴾ وَمِنۡهُم مَّن يَلۡمِزُكَ فِي ٱلصَّدَقَٰتِ فَإِنۡ أُعۡطُواْ مِنۡهَا رَضُواْ وَإِن لَّمۡ يُعۡطَوۡاْ مِنۡهَآ إِذَا هُمۡ يَسۡخَطُونَ ﴿٥٨﴾ وَلَوۡ أَنَّهُمۡ رَضُواْ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُواْ حَسۡبُنَا ٱللَّهُ سَيُؤۡتِينَا ٱللَّهُ مِن فَضۡلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ ﴿٥٩﴾", "w": [["وما هم منكم", "في باطن الأمر، لأنهم كافرون، وجوههم وقلوبهم مع الكافرين."], ["يفرقون", "يخافون خوفاً شديداً منكم."], ["ملجأ", "مكاناً حصيناً يلجؤون إليه."], ["أو مغارات", "جمع مغارة، وهي الغار في الجبل."], ["أو مُدّخلاً", "سرباً في الأرض يستتر فيه الخائف الهارب."], ["يلمزك", "يعيبك ويطعن فيك."], ["حسبنا الله", "كافينا الله كل ما يهمّنا."], ["إلى الله راغبون", "إلى الله وحده راغبون، طامعون راجون."]], "m": "ما زال السياق في هتك أستار المنافقين ليتوب منهم من أكرمه الله: ويحلفون بالله إنهم لمنكم، من أهل ملّتكم، وما هم منكم في واقع الأمر، ولكنهم قوم يفرقون منكم خوفاً شديداً، فيحلفون لتأمنوهم على أرواحهم وأموالهم، لو يجدون حصناً أو غيراناً في الجبال أو سرباً في الأرض لولّوا إليه وهم يجمحون مسرعين. ومنهم من يلمزك في قسمة الصدقات ويتّهمك بعدم العدل، فإن أُعطوا منها رضوا، وإن لم يُعطوا إذا هم يسخطون. ثم أرشدهم إلى أحسن ما يكونون عليه: ولو أنهم رضوا ما آتاهم الله ورسوله من الصدقات، وقالوا: حسبنا الله، سيؤتينا الله من فضله ورسوله بما يقسمه بيننا، إنا إلى الله وحده راغبون، لكان خيراً لهم.", "h": ["الأيمان الكاذبة شعار المنافقين، وفي الحديث: «آية المنافق ثلاث: إذا حدّث كذب، وإذا وعد أخلف، وإذا اؤتمن خان».", "الجبن والخور والضعف والخوف من لوازم الكفر والنفاق.", "عيب الصالحين والطعن فيهم ظاهرة دالة على فساد قلوب ونيات من يفعل ذلك.", "مظاهر الرحمة الإلهية تتجلّى في إرشاد المنافقين إلى أحسن ما يكونون عليه ليكملوا ويسعدوا.", "لا كافي إلا الله، ووجوب انحصار الرغبة فيه تعالى وحده دون سواه."], "k": "«وقالوا حسبنا الله سيؤتينا الله من فضله»… حين أُحرم من عطاء، هل أسخط، أم أقولها راضياً؟"}, {"lbl": "الآية ٦٠", "q": "۞إِنَّمَا ٱلصَّدَقَٰتُ لِلۡفُقَرَآءِ وَٱلۡمَسَٰكِينِ وَٱلۡعَٰمِلِينَ عَلَيۡهَا وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ وَفِي ٱلرِّقَابِ وَٱلۡغَٰرِمِينَ وَفِي سَبِيلِ ٱللَّهِ وَٱبۡنِ ٱلسَّبِيلِۖ فَرِيضَةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٦٠﴾", "w": [["الصدقات", "جمع صدقة، وهي هنا الزكاة المفروضة في الأموال."], ["للفقراء", "جمع فقير، وهو من ليس له ما يكفيه من القوت ولا يسأل الناس."], ["والمساكين", "جمع مسكين، وهو فقير ليس له ما يكفيه، ويسأل الناس ويذلّ نفسه لهم."], ["والعاملين عليها", "على جمعها وجبايتها، وهم الموظفون لها."], ["والمؤلّفة قلوبهم", "أناس يُرجى إسلامهم أو بقاؤهم عليه إن كانوا قد أسلموا، وهم ذوو شأن وخطر ينفع الله بهم إن أسلموا وحسن إسلامهم."], ["وفي الرقاب", "في فك الرقاب وتحريرها من الرق، فيُعطى المكاتَبون ما يسدّدون به أقساط كتابتهم."], ["والغارمين", "المدينين الذين استدانوا لأنفسهم وعيالهم، وليس لديهم ما يسدّدون به ديونهم."], ["وابن السبيل", "المسافر المنقطع عن بلاده، ولو كان غنياً ببلاده."], ["فريضة من الله", "فرضها الله تعالى فريضة على عباده المؤمنين."]], "m": "بمناسبة لمز المنافقين الرسول ﷺ في قسمة الصدقات، بيّن الله أهلها المختصّين بها: إنما الصدقات محصورة في ثمانية أصناف: الفقراء الذين لا يجدون ما يسدّ حاجتهم الضرورية، والمساكين الذين لا يجدون ذلك فيسألون الناس ويُظهرون المسكنة، والعاملين عليها من سعاة وجباة وأمناء وكتّاب وموزّعين، يُعطون أجرة على عملهم، والمؤلّفة قلوبهم ممن يُرجى نفعهم للإسلام لمناصبهم وشوكتهم في أقوامهم، فيُعطى من لم يسلم ترغيباً، ومن ضعف إسلامه تثبيتاً، وفي الرقاب بمساعدة المكاتَبين على تسديد أقساطهم، أما شراء عبد بالزكاة وتحريره فلا يجوز لأنه يعود بالنفع على دافعها، إذ ولاء المعتوق له، والغارمين، وفي سبيل الله بتجهيز الغزاة والإنفاق عليهم تسليحاً وإركاباً وطعاماً ولباساً، وابن السبيل، فريضة من الله لازمة على عباده، والله عليم بخلقه حكيم في شرعه، فلا يجوز أن يُعطى منها من ليس مذكوراً في الآية، وليس شرطاً أن تُعطى كل الأصناف، فقد يعطي المرء زكاته كلها في صنف واحد فتجزئه، وإن كان الأولى أن يقسمها بين من وُجد منهم.", "h": ["تقرير فرضية الزكاة.", "بيان مصارف الزكاة.", "وجوب التسليم لله تعالى في قسمته، بعدم محاولة الخروج عنها.", "إثبات صفات الله تعالى، وهي هنا: العلم والحكمة، ومتى كان الله عليماً بخلقه وحاجاتهم، حكيماً في تصرّفه وشرعه، وجب التسليم لأمره والخضوع له بالطاعة والانقياد."], "k": "«فريضة من الله»… هل أؤدّي زكاتي كاملة إلى أهلها، وأتحرّى من يستحقها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (125, 9, 61, 72, 'سورة التوبة ٦١ – ٧٢', '«قل أذن خير لكم»، «أبالله وآياته ورسوله كنتم تستهزئون»، و«والمؤمنون والمؤمنات بعضهم أولياء بعض»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 125) = $j$[{"lbl": "الآيات ٦١ – ٦٣", "q": "وَمِنۡهُمُ ٱلَّذِينَ يُؤۡذُونَ ٱلنَّبِيَّ وَيَقُولُونَ هُوَ أُذُنٞۚ قُلۡ أُذُنُ خَيۡرٖ لَّكُمۡ يُؤۡمِنُ بِٱللَّهِ وَيُؤۡمِنُ لِلۡمُؤۡمِنِينَ وَرَحۡمَةٞ لِّلَّذِينَ ءَامَنُواْ مِنكُمۡۚ وَٱلَّذِينَ يُؤۡذُونَ رَسُولَ ٱللَّهِ لَهُمۡ عَذَابٌ أَلِيمٞ ﴿٦١﴾ يَحۡلِفُونَ بِٱللَّهِ لَكُمۡ لِيُرۡضُوكُمۡ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرۡضُوهُ إِن كَانُواْ مُؤۡمِنِينَ ﴿٦٢﴾ أَلَمۡ يَعۡلَمُوٓاْ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدٗا فِيهَاۚ ذَٰلِكَ ٱلۡخِزۡيُ ٱلۡعَظِيمُ ﴿٦٣﴾", "w": [["يؤذون النبي", "الرسول محمداً ﷺ، والأذى: المكروه يصيب الإنسان كثيراً أو يسيراً."], ["هو أذن", "يسمع من كل من يقول له ويحدّثه، وهذا من الأذى."], ["قل أذن خير لكم", "هو يسمع من كل من يقول له لا يتكبّر، ولكن لا يقرّ إلا الحق، ولا يقبل إلا الخير والمعروف، فهو أذن خير لكم لا أذن شر مثلكم أيها المنافقون."], ["ويؤمن للمؤمنين", "يصدّق المؤمنين الصادقين من المهاجرين والأنصار، أما غيرهم فإنه وإن سمع منهم لا يصدّقهم لأنهم كذبة فجرة."], ["والله ورسوله أحق أن يُرضوه", "الله أحق أن يُرضوه، ورسوله أحق أن يُرضوه."], ["من يحادد الله ورسوله", "يعاديهما، ويقف دائماً في حد وهما في حد، فلا ولاء ولا موالاة."]], "m": "ما زال السياق في هتك أستار المنافقين: ومنهم الذين يؤذون النبي بالطعن فيه وعيبه، ويقولون: هو أذن يسمع كل ما يقال له، وحاشاه أن يقرّ باطلاً أو شراً، فهو لا يسمع إلا الخير، ولكنهم لخبث نفوسهم حملهم هذا الجميل على الطعن فيه، قل أذن خير لكم، يؤمن بالله، ويؤمن للمؤمنين فيصدّقهم فيما يقولون، ورحمة للذين آمنوا منكم فكملوا بما جاء به وسعدوا، والذين يؤذون رسول الله بأي نوع من الأذى لهم عذاب أليم. يحلفون بالله لكم أنهم ما طعنوا في الرسول ليرضوكم فلا تبطشوا بهم، والله ورسوله أحق أن يرضوه بالتوبة والإيمان والمتابعة إن كانوا مؤمنين كما يزعمون. ألم يعلموا أنه من يحادد الله ورسوله بالعداوة والمحاربة فأن له نار جهنم خالداً فيها، ذلك الخزي العظيم.", "h": ["حرمة أذية رسول الله ﷺ بأي وجه من الوجوه.", "كون النبي ﷺ رحمة للمؤمنين دعوة للإيمان والإسلام.", "توعّد الله تعالى من يؤذي رسوله بالعذاب الأليم دليل على كفر من يؤذي رسول الله ﷺ.", "بيان كذب المنافقين وجبنهم، حيث يحلفون للمؤمنين أنهم ما طعنوا في الرسول وقد طعنوا بالفعل، وإنما يدفعون بحلفهم الكاذب غضب المؤمنين.", "وجوب طلب رضا الله تعالى بفعل محابّه وترك مساخطه.", "توعّد من يحادد الله ورسوله بالعذاب الأليم."], "k": "«والله ورسوله أحق أن يُرضوه»… كم مرة قدّمت رضا الناس على رضا ربي؟"}, {"lbl": "الآيات ٦٤ – ٦٦", "q": "يَحۡذَرُ ٱلۡمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيۡهِمۡ سُورَةٞ تُنَبِّئُهُم بِمَا فِي قُلُوبِهِمۡۚ قُلِ ٱسۡتَهۡزِءُوٓاْ إِنَّ ٱللَّهَ مُخۡرِجٞ مَّا تَحۡذَرُونَ ﴿٦٤﴾ وَلَئِن سَأَلۡتَهُمۡ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلۡعَبُۚ قُلۡ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمۡ تَسۡتَهۡزِءُونَ ﴿٦٥﴾ لَا تَعۡتَذِرُواْ قَدۡ كَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡۚ إِن نَّعۡفُ عَن طَآئِفَةٖ مِّنكُمۡ نُعَذِّبۡ طَآئِفَةَۢ بِأَنَّهُمۡ كَانُواْ مُجۡرِمِينَ ﴿٦٦﴾", "w": [["يحذر المنافقون", "يخافون ويحترسون."], ["تُنزّل عليهم سورة", "في شأنهم، فتفضحهم بإظهار عيوبهم."], ["تنبّئهم بما في قلوبهم", "تخبرهم بما يضمرونه في نفوسهم."], ["قل استهزئوا", "الأمر هنا للتهديد."], ["مُخرج ما تحذرون", "مخرجه من نفوسكم ومظهره للناس أجمعين."], ["تستهزئون", "تسخرون وتحتقرون."]], "m": "يحذر المنافقون أن تُنزّل على رسول الله سورة تنبّئهم بما في قلوبهم فتفضحهم، ولذا سُمّيت هذه السورة الفاضحة، قل استهزئوا إن الله مُخرج ما تحذرون مما يقولونه في خلواتهم من الطعن في الإسلام وأهله. ولئن سألتهم عما قالوا ليقولنّ: إنما كنا نخوض ونلعب، وذلك أن نفراً منهم قالوا في غزوة تبوك: ما رأينا مثل قرّائنا هؤلاء أرغب بطوناً ولا أكذب ألسناً ولا أجبن عند اللقاء، وقالوا يشيرون إلى النبي ﷺ: يظن هذا أن يفتح قصور الشام وحصونها، فأطلعه الله عليهم، فاعتذروا: إنما كنا نخوض في الحديث ونلعب تقصيراً للوقت، قل: أبالله وآياته ورسوله كنتم تستهزئون؟ لا تعتذروا، قد كفرتم بعد إيمانكم، لأن الاستهزاء بالله والرسول والكتاب كفر مخرج من الملة. إن نعف عن طائفة منكم لأنهم يتوبون، كمخشي بن حمير، نعذّب طائفة لا يتوبون، بأنهم كانوا مجرمين بالكفر والاستهزاء.", "h": ["الكشف عن مدى ما كان يعيش عليه المنافقون من الحذر والخوف.", "كفر من استهزأ بالله أو آياته أو رسوله.", "لا يُقبل اعتذار من كفر بأي وجه، وإنما التوبة أو السيف فيُقتل كفراً.", "مصداق ما أخبر به تعالى من أنه سيعذّب طائفة، فقد هلك عشرة بداء الدُّبيلة، خراج يخرج من الظهر وينفذ ألمه إلى الصدر فيهلك صاحبه حتماً."], "k": "«إنما كنا نخوض ونلعب»… هل أمزح بشيء من الدين، وأحسبه هيّناً وهو عند الله عظيم؟"}, {"lbl": "الآيات ٦٧ – ٧٠", "q": "ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ بَعۡضُهُم مِّنۢ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمُنكَرِ وَيَنۡهَوۡنَ عَنِ ٱلۡمَعۡرُوفِ وَيَقۡبِضُونَ أَيۡدِيَهُمۡۚ نَسُواْ ٱللَّهَ فَنَسِيَهُمۡۚ إِنَّ ٱلۡمُنَٰفِقِينَ هُمُ ٱلۡفَٰسِقُونَ ﴿٦٧﴾ وَعَدَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۚ هِيَ حَسۡبُهُمۡۚ وَلَعَنَهُمُ ٱللَّهُۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ ﴿٦٨﴾ كَٱلَّذِينَ مِن قَبۡلِكُمۡ كَانُوٓاْ أَشَدَّ مِنكُمۡ قُوَّةٗ وَأَكۡثَرَ أَمۡوَٰلٗا وَأَوۡلَٰدٗا فَٱسۡتَمۡتَعُواْ بِخَلَٰقِهِمۡ فَٱسۡتَمۡتَعۡتُم بِخَلَٰقِكُمۡ كَمَا ٱسۡتَمۡتَعَ ٱلَّذِينَ مِن قَبۡلِكُم بِخَلَٰقِهِمۡ وَخُضۡتُمۡ كَٱلَّذِي خَاضُوٓاْۚ أُوْلَـٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ﴿٦٩﴾ أَلَمۡ يَأۡتِهِمۡ نَبَأُ ٱلَّذِينَ مِن قَبۡلِهِمۡ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَقَوۡمِ إِبۡرَٰهِيمَ وَأَصۡحَٰبِ مَدۡيَنَ وَٱلۡمُؤۡتَفِكَٰتِۚ أَتَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِۖ فَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿٧٠﴾", "w": [["المنافقون", "الذين يُظهرون للمؤمنين الإيمان بألسنتهم، ويسترون الكفر في قلوبهم."], ["بالمنكر", "ما أنكره الشرع لضرره أو قبحه، وهو الكفر بالله ورسوله والمعاصي."], ["عن المعروف", "ما عرفه الشرع نافعاً فأمر به من الإيمان والعمل الصالح."], ["يقبضون أيديهم", "يمسكونها عن الإنفاق في سبيل الله."], ["نسوا الله فنسيهم", "تركوا الله فلم يؤمنوا به وبرسوله، فتركهم وحرمهم من توفيقه وهدايته."], ["عذاب مقيم", "دائم لا يزول ولا يبيد."], ["وخضتم", "أي في الكذب والباطل."], ["والمؤتفكات", "المنقلبات حيث صار عاليها سافلها، وهي ثلاث مدن."], ["بالبيّنات", "الآيات الدالة على صدقهم في رسالاتهم إليهم."]], "m": "المنافقون والمنافقات بعضهم من بعض كأبعاض الشيء الواحد، أمرهم واحد في المعتقد والقول والعمل، يأمرون بالمنكر، وهو الكفر والعصيان، وينهون عن المعروف، وهو الإيمان والطاعة، دليل على انتكاسهم وفساد قلوبهم، ويقبضون أيديهم عن الإنفاق في سبيل الله، نسوا الله فنسيهم، إن المنافقين هم الفاسقون. وعد الله المنافقين والمنافقات والكفار نار جهنم خالدين فيها هي حسبهم، ولعنهم الله ولهم عذاب مقيم، أشد وعيد لأهل النفاق. أنتم كالذين من قبلكم كانوا أشد منكم قوة وأكثر أموالاً وأولاداً، فاستمتعوا بخلاقهم، نصيبهم المكتوب لهم في الدنيا، فاستمتعتم بخلاقكم كما استمتعوا، وخضتم في الباطل والتكذيب كالذي خاضوا، أولئك حبطت أعمالهم في الدنيا والآخرة وأولئك هم الخاسرون، وأنتم على منهجهم فمصيركم كمصيرهم. ألم يأتهم نبأ الذين من قبلهم: قوم نوح أُهلكوا بالطوفان، وعاد بالريح العاتية، وثمود بالصاعقة، وقوم إبراهيم بسلب النعم، وأصحاب مدين بالرجفة وعذاب الظلّة، والمؤتفكات بالمطر والقلب؟ أتتهم رسلهم بالبيّنات، فما كان الله ليظلمهم ولكن كانوا أنفسهم يظلمون.", "h": ["المنافقون لما كان مرضهم واحداً، وهو الكفر الباطني، كان سلوكهم متشابهاً.", "الأمر بالمنكر والنهي عن المعروف علامة النفاق، وظاهرة الكفر، وانتكاس الفطرة.", "الاغترار بالمال والولد من عوامل عدم قبول الحق والإذعان له والتسليم به.", "تشابه حال البشر، واتباع بعضهم لبعض في الباطل والفساد والشر.", "حبوط الأعمال بالباطل وهلاك أهلها أمر مقضيّ به لا يتخلّف.", "وجوب الاعتبار بأحوال السابقين، والاتعاظ بما لاقاه أهل الكفر منهم من عذاب."], "k": "«نسوا الله فنسيهم»… هل في يومي وقت أنسى فيه ربي كأنه ليس معي؟"}, {"lbl": "الآيتان ٧١ – ٧٢", "q": "وَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَـٰٓئِكَ سَيَرۡحَمُهُمُ ٱللَّهُۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ﴿٧١﴾ وَعَدَ ٱللَّهُ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّـٰتِ عَدۡنٖۚ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِ أَكۡبَرُۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٧٢﴾", "w": [["والمؤمنون", "الصادقون في إيمانهم بالله ورسوله ووعد الله ووعيده."], ["أولياء بعض", "يتولّى بعضهم بعضاً في النصرة والحماية والمحبة والتأييد."], ["ويقيمون الصلاة", "يؤدّونها في خشوع، وافية الشروط والأركان والسنن والآداب."], ["ويؤتون الزكاة", "يُخرجون زكاة أموالهم الصامتة كالدراهم والدنانير والمعشّرات، والناطقة كالأنعام: الإبل والبقر والغنم."], ["في جنات عدن", "إقامة دائمة لا يخرجون منها ولا يتحوّلون عنها."], ["ورضوان من الله أكبر", "رضوان الله الذي يحلّه عليهم أكبر من كل نعيم في الجنة."]], "m": "بمناسبة ذكر المنافقين ومصيرهم، ذكر المؤمنين وسلوكهم الحسن ومصيرهم السعيد: والمؤمنون والمؤمنات بعضهم أولياء بعض محبة ونصرة وتعاوناً، يأمرون بالمعروف من الإيمان وصالح الأعمال، وينهون عن المنكر من الشرك وسائر الجرائم، على عكس المنافقين، ويقيمون الصلاة، والمنافقون يأتونها كسالى، ويؤتون الزكاة، والمنافقون يقبضون أيديهم، ويطيعون الله ورسوله، والمنافقون يعصونهما، أولئك سيرحمهم الله، والمنافقون سيعذّبهم، إن الله عزيز حكيم يضع كل شيء في موضعه. وعد الله المؤمنين والمؤمنات جنات تجري من تحتها الأنهار خالدين فيها، ومساكن طيبة في غاية النظافة وطيب الرائحة في جنات عدن، ورضوان من الله يحلّه عليهم أكبر من الجنات والقصور وسائر النعيم، ذلك هو الفوز العظيم: السلامة من المرهوب والظفر بالمرغوب.", "h": ["بيان صفات المؤمنين والمؤمنات التي هي مظاهر إيمانهم وأدلّته.", "أهمية صفات أهل الإيمان، وهي: الولاء لبعضهم بعضاً، والأمر بالمعروف والنهي عن المنكر، وإقامة الصلاة، وإيتاء الزكاة، وطاعة الله ورسوله.", "بيان جزاء أهل الإيمان في الدار الآخرة، وهو النعيم المقيم في دار السلام.", "أفضلية رضا الله تعالى على سائر النعيم.", "بيان معنى الفوز، وهو النجاة من النار ودخول الجنة."], "k": "«بعضهم أولياء بعض»… من المؤمنين الذين أحتاج أن أكون لهم وليّاً بمحبتي ونصرتي اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 125;
insert into public.tdb_cards(topic, i, body) select 125, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦١ – ٦٣", "q": "وَمِنۡهُمُ ٱلَّذِينَ يُؤۡذُونَ ٱلنَّبِيَّ وَيَقُولُونَ هُوَ أُذُنٞۚ قُلۡ أُذُنُ خَيۡرٖ لَّكُمۡ يُؤۡمِنُ بِٱللَّهِ وَيُؤۡمِنُ لِلۡمُؤۡمِنِينَ وَرَحۡمَةٞ لِّلَّذِينَ ءَامَنُواْ مِنكُمۡۚ وَٱلَّذِينَ يُؤۡذُونَ رَسُولَ ٱللَّهِ لَهُمۡ عَذَابٌ أَلِيمٞ ﴿٦١﴾ يَحۡلِفُونَ بِٱللَّهِ لَكُمۡ لِيُرۡضُوكُمۡ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرۡضُوهُ إِن كَانُواْ مُؤۡمِنِينَ ﴿٦٢﴾ أَلَمۡ يَعۡلَمُوٓاْ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدٗا فِيهَاۚ ذَٰلِكَ ٱلۡخِزۡيُ ٱلۡعَظِيمُ ﴿٦٣﴾", "w": [["يؤذون النبي", "الرسول محمداً ﷺ، والأذى: المكروه يصيب الإنسان كثيراً أو يسيراً."], ["هو أذن", "يسمع من كل من يقول له ويحدّثه، وهذا من الأذى."], ["قل أذن خير لكم", "هو يسمع من كل من يقول له لا يتكبّر، ولكن لا يقرّ إلا الحق، ولا يقبل إلا الخير والمعروف، فهو أذن خير لكم لا أذن شر مثلكم أيها المنافقون."], ["ويؤمن للمؤمنين", "يصدّق المؤمنين الصادقين من المهاجرين والأنصار، أما غيرهم فإنه وإن سمع منهم لا يصدّقهم لأنهم كذبة فجرة."], ["والله ورسوله أحق أن يُرضوه", "الله أحق أن يُرضوه، ورسوله أحق أن يُرضوه."], ["من يحادد الله ورسوله", "يعاديهما، ويقف دائماً في حد وهما في حد، فلا ولاء ولا موالاة."]], "m": "ما زال السياق في هتك أستار المنافقين: ومنهم الذين يؤذون النبي بالطعن فيه وعيبه، ويقولون: هو أذن يسمع كل ما يقال له، وحاشاه أن يقرّ باطلاً أو شراً، فهو لا يسمع إلا الخير، ولكنهم لخبث نفوسهم حملهم هذا الجميل على الطعن فيه، قل أذن خير لكم، يؤمن بالله، ويؤمن للمؤمنين فيصدّقهم فيما يقولون، ورحمة للذين آمنوا منكم فكملوا بما جاء به وسعدوا، والذين يؤذون رسول الله بأي نوع من الأذى لهم عذاب أليم. يحلفون بالله لكم أنهم ما طعنوا في الرسول ليرضوكم فلا تبطشوا بهم، والله ورسوله أحق أن يرضوه بالتوبة والإيمان والمتابعة إن كانوا مؤمنين كما يزعمون. ألم يعلموا أنه من يحادد الله ورسوله بالعداوة والمحاربة فأن له نار جهنم خالداً فيها، ذلك الخزي العظيم.", "h": ["حرمة أذية رسول الله ﷺ بأي وجه من الوجوه.", "كون النبي ﷺ رحمة للمؤمنين دعوة للإيمان والإسلام.", "توعّد الله تعالى من يؤذي رسوله بالعذاب الأليم دليل على كفر من يؤذي رسول الله ﷺ.", "بيان كذب المنافقين وجبنهم، حيث يحلفون للمؤمنين أنهم ما طعنوا في الرسول وقد طعنوا بالفعل، وإنما يدفعون بحلفهم الكاذب غضب المؤمنين.", "وجوب طلب رضا الله تعالى بفعل محابّه وترك مساخطه.", "توعّد من يحادد الله ورسوله بالعذاب الأليم."], "k": "«والله ورسوله أحق أن يُرضوه»… كم مرة قدّمت رضا الناس على رضا ربي؟"}, {"lbl": "الآيات ٦٤ – ٦٦", "q": "يَحۡذَرُ ٱلۡمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيۡهِمۡ سُورَةٞ تُنَبِّئُهُم بِمَا فِي قُلُوبِهِمۡۚ قُلِ ٱسۡتَهۡزِءُوٓاْ إِنَّ ٱللَّهَ مُخۡرِجٞ مَّا تَحۡذَرُونَ ﴿٦٤﴾ وَلَئِن سَأَلۡتَهُمۡ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلۡعَبُۚ قُلۡ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمۡ تَسۡتَهۡزِءُونَ ﴿٦٥﴾ لَا تَعۡتَذِرُواْ قَدۡ كَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡۚ إِن نَّعۡفُ عَن طَآئِفَةٖ مِّنكُمۡ نُعَذِّبۡ طَآئِفَةَۢ بِأَنَّهُمۡ كَانُواْ مُجۡرِمِينَ ﴿٦٦﴾", "w": [["يحذر المنافقون", "يخافون ويحترسون."], ["تُنزّل عليهم سورة", "في شأنهم، فتفضحهم بإظهار عيوبهم."], ["تنبّئهم بما في قلوبهم", "تخبرهم بما يضمرونه في نفوسهم."], ["قل استهزئوا", "الأمر هنا للتهديد."], ["مُخرج ما تحذرون", "مخرجه من نفوسكم ومظهره للناس أجمعين."], ["تستهزئون", "تسخرون وتحتقرون."]], "m": "يحذر المنافقون أن تُنزّل على رسول الله سورة تنبّئهم بما في قلوبهم فتفضحهم، ولذا سُمّيت هذه السورة الفاضحة، قل استهزئوا إن الله مُخرج ما تحذرون مما يقولونه في خلواتهم من الطعن في الإسلام وأهله. ولئن سألتهم عما قالوا ليقولنّ: إنما كنا نخوض ونلعب، وذلك أن نفراً منهم قالوا في غزوة تبوك: ما رأينا مثل قرّائنا هؤلاء أرغب بطوناً ولا أكذب ألسناً ولا أجبن عند اللقاء، وقالوا يشيرون إلى النبي ﷺ: يظن هذا أن يفتح قصور الشام وحصونها، فأطلعه الله عليهم، فاعتذروا: إنما كنا نخوض في الحديث ونلعب تقصيراً للوقت، قل: أبالله وآياته ورسوله كنتم تستهزئون؟ لا تعتذروا، قد كفرتم بعد إيمانكم، لأن الاستهزاء بالله والرسول والكتاب كفر مخرج من الملة. إن نعف عن طائفة منكم لأنهم يتوبون، كمخشي بن حمير، نعذّب طائفة لا يتوبون، بأنهم كانوا مجرمين بالكفر والاستهزاء.", "h": ["الكشف عن مدى ما كان يعيش عليه المنافقون من الحذر والخوف.", "كفر من استهزأ بالله أو آياته أو رسوله.", "لا يُقبل اعتذار من كفر بأي وجه، وإنما التوبة أو السيف فيُقتل كفراً.", "مصداق ما أخبر به تعالى من أنه سيعذّب طائفة، فقد هلك عشرة بداء الدُّبيلة، خراج يخرج من الظهر وينفذ ألمه إلى الصدر فيهلك صاحبه حتماً."], "k": "«إنما كنا نخوض ونلعب»… هل أمزح بشيء من الدين، وأحسبه هيّناً وهو عند الله عظيم؟"}, {"lbl": "الآيات ٦٧ – ٧٠", "q": "ٱلۡمُنَٰفِقُونَ وَٱلۡمُنَٰفِقَٰتُ بَعۡضُهُم مِّنۢ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمُنكَرِ وَيَنۡهَوۡنَ عَنِ ٱلۡمَعۡرُوفِ وَيَقۡبِضُونَ أَيۡدِيَهُمۡۚ نَسُواْ ٱللَّهَ فَنَسِيَهُمۡۚ إِنَّ ٱلۡمُنَٰفِقِينَ هُمُ ٱلۡفَٰسِقُونَ ﴿٦٧﴾ وَعَدَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۚ هِيَ حَسۡبُهُمۡۚ وَلَعَنَهُمُ ٱللَّهُۖ وَلَهُمۡ عَذَابٞ مُّقِيمٞ ﴿٦٨﴾ كَٱلَّذِينَ مِن قَبۡلِكُمۡ كَانُوٓاْ أَشَدَّ مِنكُمۡ قُوَّةٗ وَأَكۡثَرَ أَمۡوَٰلٗا وَأَوۡلَٰدٗا فَٱسۡتَمۡتَعُواْ بِخَلَٰقِهِمۡ فَٱسۡتَمۡتَعۡتُم بِخَلَٰقِكُمۡ كَمَا ٱسۡتَمۡتَعَ ٱلَّذِينَ مِن قَبۡلِكُم بِخَلَٰقِهِمۡ وَخُضۡتُمۡ كَٱلَّذِي خَاضُوٓاْۚ أُوْلَـٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ﴿٦٩﴾ أَلَمۡ يَأۡتِهِمۡ نَبَأُ ٱلَّذِينَ مِن قَبۡلِهِمۡ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَقَوۡمِ إِبۡرَٰهِيمَ وَأَصۡحَٰبِ مَدۡيَنَ وَٱلۡمُؤۡتَفِكَٰتِۚ أَتَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِۖ فَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿٧٠﴾", "w": [["المنافقون", "الذين يُظهرون للمؤمنين الإيمان بألسنتهم، ويسترون الكفر في قلوبهم."], ["بالمنكر", "ما أنكره الشرع لضرره أو قبحه، وهو الكفر بالله ورسوله والمعاصي."], ["عن المعروف", "ما عرفه الشرع نافعاً فأمر به من الإيمان والعمل الصالح."], ["يقبضون أيديهم", "يمسكونها عن الإنفاق في سبيل الله."], ["نسوا الله فنسيهم", "تركوا الله فلم يؤمنوا به وبرسوله، فتركهم وحرمهم من توفيقه وهدايته."], ["عذاب مقيم", "دائم لا يزول ولا يبيد."], ["وخضتم", "أي في الكذب والباطل."], ["والمؤتفكات", "المنقلبات حيث صار عاليها سافلها، وهي ثلاث مدن."], ["بالبيّنات", "الآيات الدالة على صدقهم في رسالاتهم إليهم."]], "m": "المنافقون والمنافقات بعضهم من بعض كأبعاض الشيء الواحد، أمرهم واحد في المعتقد والقول والعمل، يأمرون بالمنكر، وهو الكفر والعصيان، وينهون عن المعروف، وهو الإيمان والطاعة، دليل على انتكاسهم وفساد قلوبهم، ويقبضون أيديهم عن الإنفاق في سبيل الله، نسوا الله فنسيهم، إن المنافقين هم الفاسقون. وعد الله المنافقين والمنافقات والكفار نار جهنم خالدين فيها هي حسبهم، ولعنهم الله ولهم عذاب مقيم، أشد وعيد لأهل النفاق. أنتم كالذين من قبلكم كانوا أشد منكم قوة وأكثر أموالاً وأولاداً، فاستمتعوا بخلاقهم، نصيبهم المكتوب لهم في الدنيا، فاستمتعتم بخلاقكم كما استمتعوا، وخضتم في الباطل والتكذيب كالذي خاضوا، أولئك حبطت أعمالهم في الدنيا والآخرة وأولئك هم الخاسرون، وأنتم على منهجهم فمصيركم كمصيرهم. ألم يأتهم نبأ الذين من قبلهم: قوم نوح أُهلكوا بالطوفان، وعاد بالريح العاتية، وثمود بالصاعقة، وقوم إبراهيم بسلب النعم، وأصحاب مدين بالرجفة وعذاب الظلّة، والمؤتفكات بالمطر والقلب؟ أتتهم رسلهم بالبيّنات، فما كان الله ليظلمهم ولكن كانوا أنفسهم يظلمون.", "h": ["المنافقون لما كان مرضهم واحداً، وهو الكفر الباطني، كان سلوكهم متشابهاً.", "الأمر بالمنكر والنهي عن المعروف علامة النفاق، وظاهرة الكفر، وانتكاس الفطرة.", "الاغترار بالمال والولد من عوامل عدم قبول الحق والإذعان له والتسليم به.", "تشابه حال البشر، واتباع بعضهم لبعض في الباطل والفساد والشر.", "حبوط الأعمال بالباطل وهلاك أهلها أمر مقضيّ به لا يتخلّف.", "وجوب الاعتبار بأحوال السابقين، والاتعاظ بما لاقاه أهل الكفر منهم من عذاب."], "k": "«نسوا الله فنسيهم»… هل في يومي وقت أنسى فيه ربي كأنه ليس معي؟"}, {"lbl": "الآيتان ٧١ – ٧٢", "q": "وَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَـٰٓئِكَ سَيَرۡحَمُهُمُ ٱللَّهُۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ﴿٧١﴾ وَعَدَ ٱللَّهُ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّـٰتِ عَدۡنٖۚ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِ أَكۡبَرُۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٧٢﴾", "w": [["والمؤمنون", "الصادقون في إيمانهم بالله ورسوله ووعد الله ووعيده."], ["أولياء بعض", "يتولّى بعضهم بعضاً في النصرة والحماية والمحبة والتأييد."], ["ويقيمون الصلاة", "يؤدّونها في خشوع، وافية الشروط والأركان والسنن والآداب."], ["ويؤتون الزكاة", "يُخرجون زكاة أموالهم الصامتة كالدراهم والدنانير والمعشّرات، والناطقة كالأنعام: الإبل والبقر والغنم."], ["في جنات عدن", "إقامة دائمة لا يخرجون منها ولا يتحوّلون عنها."], ["ورضوان من الله أكبر", "رضوان الله الذي يحلّه عليهم أكبر من كل نعيم في الجنة."]], "m": "بمناسبة ذكر المنافقين ومصيرهم، ذكر المؤمنين وسلوكهم الحسن ومصيرهم السعيد: والمؤمنون والمؤمنات بعضهم أولياء بعض محبة ونصرة وتعاوناً، يأمرون بالمعروف من الإيمان وصالح الأعمال، وينهون عن المنكر من الشرك وسائر الجرائم، على عكس المنافقين، ويقيمون الصلاة، والمنافقون يأتونها كسالى، ويؤتون الزكاة، والمنافقون يقبضون أيديهم، ويطيعون الله ورسوله، والمنافقون يعصونهما، أولئك سيرحمهم الله، والمنافقون سيعذّبهم، إن الله عزيز حكيم يضع كل شيء في موضعه. وعد الله المؤمنين والمؤمنات جنات تجري من تحتها الأنهار خالدين فيها، ومساكن طيبة في غاية النظافة وطيب الرائحة في جنات عدن، ورضوان من الله يحلّه عليهم أكبر من الجنات والقصور وسائر النعيم، ذلك هو الفوز العظيم: السلامة من المرهوب والظفر بالمرغوب.", "h": ["بيان صفات المؤمنين والمؤمنات التي هي مظاهر إيمانهم وأدلّته.", "أهمية صفات أهل الإيمان، وهي: الولاء لبعضهم بعضاً، والأمر بالمعروف والنهي عن المنكر، وإقامة الصلاة، وإيتاء الزكاة، وطاعة الله ورسوله.", "بيان جزاء أهل الإيمان في الدار الآخرة، وهو النعيم المقيم في دار السلام.", "أفضلية رضا الله تعالى على سائر النعيم.", "بيان معنى الفوز، وهو النجاة من النار ودخول الجنة."], "k": "«بعضهم أولياء بعض»… من المؤمنين الذين أحتاج أن أكون لهم وليّاً بمحبتي ونصرتي اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (126, 9, 73, 83, 'سورة التوبة ٧٣ – ٨٣', '«جاهد الكفار والمنافقين»، «ومنهم من عاهد الله لئن آتانا من فضله»، و«فرح المخلّفون بمقعدهم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 126) = $j$[{"lbl": "الآيتان ٧٣ – ٧٤", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿٧٣﴾ يَحۡلِفُونَ بِٱللَّهِ مَا قَالُواْ وَلَقَدۡ قَالُواْ كَلِمَةَ ٱلۡكُفۡرِ وَكَفَرُواْ بَعۡدَ إِسۡلَٰمِهِمۡ وَهَمُّواْ بِمَا لَمۡ يَنَالُواْۚ وَمَا نَقَمُوٓاْ إِلَّآ أَنۡ أَغۡنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضۡلِهِۦۚ فَإِن يَتُوبُواْ يَكُ خَيۡرٗا لَّهُمۡۖ وَإِن يَتَوَلَّوۡاْ يُعَذِّبۡهُمُ ٱللَّهُ عَذَابًا أَلِيمٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَمَا لَهُمۡ فِي ٱلۡأَرۡضِ مِن وَلِيّٖ وَلَا نَصِيرٖ ﴿٧٤﴾", "w": [["جاهد الكفار", "ابذل غاية جهدك في قتال الكفار والمنافقين."], ["واغلظ عليهم", "في القول والفعل، أي شدّد عليهم ولا تلن لهم."], ["كلمة الكفر", "كلمة يكفر بها من قالها، وهي قول الجلاس بن سويد: إن كان ما جاء به محمد حقاً لنحن شر من الحمير."], ["وهمّوا بما لم ينالوا", "همّوا بقتل النبي ﷺ في مؤامرة دنيئة وهم عائدون من تبوك."], ["وما نقموا إلا أن أغناهم", "ما أنكروا أو كرهوا من الإسلام ورسوله إلا أن أغناهم الله بعد فقر، أفعلى مثل هذا يهمّون بقتل رسول الله؟"]], "m": "يا أيها النبي جاهد الكفار بالسلاح، والمنافقين باللسان، واغلظ عليهم فلا هوادة مع من كفر بالله ورسوله أو أظهر الإيمان وأسرّ الكفر، ومأواهم في الآخرة جهنم وبئس المصير. وعلّة ذلك: يحلفون بالله ما قالوا، ولقد قالوا كلمة الكفر، إذ قال الجلاس بن سويد: لئن كان ما جاء به محمد حقاً لنحن شر من الحمير، فسمعه أحد المؤمنين فبلّغ رسول الله ﷺ، فجاء يعتذر ويحلف، فأكذبه الله، وكفروا بعد إسلامهم، وهمّوا بما لم ينالوا، إذ تآمر منافقون على قتل النبي ﷺ عند عودته من تبوك في عقبة في الطريق، عزموا أن يزاحموه بنوقهم حتى يسقط فيهلك، ففضحهم الله ونجّاه، إذ بعث عمار بن ياسر يضرب وجوه الرواحل فتفرّقوا، وما نقموا إلا أن أغناهم الله ورسوله من فضله بعد فقر، وهل الغنى مما يُنقم منه؟ ولكنه الكفر والنفاق يفسد الذوق والفطرة والعقل. ومع هذا يفتح الرب الرحيم باب التوبة: فإن يتوبوا يكُ خيراً لهم حالاً ومآلاً، وإن يتولّوا يعذّبهم الله عذاباً أليماً في الدنيا بالقتل والخزي، وفي الآخرة بالنار، وما لهم في الأرض من ولي ولا نصير.", "h": ["بيان آية السيف، وهي: «يا أيها النبي جاهد الكفار والمنافقين».", "تقرير مبدأ الردة، وهي أن يقول المسلم كلمة الكفر فيكفر بها، وذلك كالطعن في الإسلام، أو سب الله أو رسوله ﷺ، أو التكذيب بما أمر الله تعالى بالإيمان به، والتصديق بما أمر الله بتكذيبه."], "k": "«فإن يتوبوا يكُ خيراً لهم»… إن فُتح هذا الباب لمن همّ بقتل النبي ﷺ، أفيُغلق في وجهي؟"}, {"lbl": "الآيات ٧٥ – ٧٨", "q": "۞وَمِنۡهُم مَّنۡ عَٰهَدَ ٱللَّهَ لَئِنۡ ءَاتَىٰنَا مِن فَضۡلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّـٰلِحِينَ ﴿٧٥﴾ فَلَمَّآ ءَاتَىٰهُم مِّن فَضۡلِهِۦ بَخِلُواْ بِهِۦ وَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ ﴿٧٦﴾ فَأَعۡقَبَهُمۡ نِفَاقٗا فِي قُلُوبِهِمۡ إِلَىٰ يَوۡمِ يَلۡقَوۡنَهُۥ بِمَآ أَخۡلَفُواْ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُواْ يَكۡذِبُونَ ﴿٧٧﴾ أَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ سِرَّهُمۡ وَنَجۡوَىٰهُمۡ وَأَنَّ ٱللَّهَ عَلَّـٰمُ ٱلۡغُيُوبِ ﴿٧٨﴾", "w": [["ومنهم", "أي من المنافقين."], ["لئن آتانا من فضله", "مالاً كثيراً."], ["بخلوا به", "منعوه فلم يؤدّوا حقه من زكاة وغيرها."], ["فأعقبهم نفاقاً", "أورثهم البخل نفاقاً ملازماً لقلوبهم لا يفارقها إلى يوم يلقونه."], ["بما أخلفوا الله", "بسبب إخلافهم ما وعدوا الله تعالى به."], ["سرّهم ونجواهم", "ما يسرّونه في نفوسهم ويخفونه، وما يتناجون به فيما بينهم."], ["علّام الغيوب", "يعلم كل غيب في الأرض أو في السماء."]], "m": "ما زال السياق في المنافقين، وهذا صنف آخر منهم: عاهدوا الله لئن أغناهم من فضله ليتصدّقنّ ولينفقنّ في طريق البر والخير وليكوننّ من الصالحين، فلما أعطاهم الله ما سألوا وكثر مالهم بخلوا به، وتولّوا عما تعهّدوا به من تقوى وصلاح وهم معرضون، فأورثهم هذا البخل وخلف الوعد والكذب نفاقاً في قلوبهم لا يفارقهم إلى يوم يلقونه، بما أخلفوا الله ما وعدوه وبما كانوا يكذبون. ألم يعلموا أن الله يعلم سرّهم ونجواهم وأن الله علّام الغيوب؟ توبيخ لهم، كأنهم لا يعلمون ذلك، وإلا كيف يعدونه ويحلفون له ثم يخلفون؟ فموقفهم مخزٍ، وويل لهم حيث لازمهم النفاق حتى الموت، فأُغلق باب التوبة في وجوههم.", "h": ["وجوب الوفاء بالعهود، وخاصة عهود الله تعالى.", "ذم البخل وأهله.", "تقرير مبدأ أن السيئة يتولّد عنها سيئة.", "جواز تقريع وتأنيب أهل الباطل.", "وجوب مراقبة الله تعالى، إذ لو راقب هؤلاء المنافقون الله تعالى لما خرجوا عن طاعته."], "k": "«لئن آتانا من فضله لنصّدّقنّ»… ما الذي وعدت به ربي إن فرّج عني، فهل وفّيت؟"}, {"lbl": "الآيتان ٧٩ – ٨٠", "q": "ٱلَّذِينَ يَلۡمِزُونَ ٱلۡمُطَّوِّعِينَ مِنَ ٱلۡمُؤۡمِنِينَ فِي ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهۡدَهُمۡ فَيَسۡخَرُونَ مِنۡهُمۡ سَخِرَ ٱللَّهُ مِنۡهُمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ ﴿٧٩﴾ ٱسۡتَغۡفِرۡ لَهُمۡ أَوۡ لَا تَسۡتَغۡفِرۡ لَهُمۡ إِن تَسۡتَغۡفِرۡ لَهُمۡ سَبۡعِينَ مَرَّةٗ فَلَن يَغۡفِرَ ٱللَّهُ لَهُمۡۚ ذَٰلِكَ بِأَنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَرَسُولِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ﴿٨٠﴾", "w": [["يلمزون", "يعيبون ويطعنون."], ["المطّوّعين", "المتصدّقين بأموالهم زيادة على الفريضة."], ["إلا جهدهم", "إلا طاقتهم وما يقدرون عليه فيأتون به."], ["فيسخرون منهم", "يستهزئون بهم احتقاراً لهم."], ["استغفر لهم", "اطلب لهم المغفرة أو لا تطلب."], ["لا يهدي القوم الفاسقين", "إلى ما فيه خيرهم وسعادتهم، وذلك لتوغّلهم في العصيان."]], "m": "ما زال السياق في التنديد بالمنافقين: الذين يلمزون المطّوّعين من المؤمنين في الصدقات، والذين لا يجدون إلا جهدهم، فيسخرون منهم، سخر الله منهم جزاء سخريتهم، ولهم عذاب أليم. وكيفية لمزهم أن النبي ﷺ دعا إلى الصدقة، فإذا جاء الرجل بمال كثير قالوا: مراءٍ، وإذا جاء بالقليل قالوا: الله غني عن صاعك هذا، ففضحهم الله. وأخبر نبيه أن استغفاره لهم وعدمه سواء: استغفر لهم أو لا تستغفر لهم، إن تستغفر لهم سبعين مرة فلن يغفر الله لهم، ذلك بأنهم كفروا بالله ورسوله، والكافر مخلّد في النار، والله لا يهدي القوم الفاسقين، لأن الفسق أصبح وصفاً لازماً لهم فلا يتوبون.", "h": ["حرمة لمز المؤمن والطعن فيه.", "حرمة السخرية بالمؤمن.", "غيرة الله على أوليائه، حيث سخر ممن سخر من المطّوّعين.", "من مات على الكفر لا ينفعه الاستغفار له، بل ولا يجوز الاستغفار له.", "التوغّل في الفسق أو الكفر أو الظلم يحرم صاحبه الهداية."], "k": "«والذين لا يجدون إلا جهدهم»… هل أستقلّ صدقة يسيرة فأتركها، والله يقبل الجهد القليل؟"}, {"lbl": "الآيات ٨١ – ٨٣", "q": "فَرِحَ ٱلۡمُخَلَّفُونَ بِمَقۡعَدِهِمۡ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓاْ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ وَقَالُواْ لَا تَنفِرُواْ فِي ٱلۡحَرِّۗ قُلۡ نَارُ جَهَنَّمَ أَشَدُّ حَرّٗاۚ لَّوۡ كَانُواْ يَفۡقَهُونَ ﴿٨١﴾ فَلۡيَضۡحَكُواْ قَلِيلٗا وَلۡيَبۡكُواْ كَثِيرٗا جَزَآءَۢ بِمَا كَانُواْ يَكۡسِبُونَ ﴿٨٢﴾ فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٖ مِّنۡهُمۡ فَٱسۡتَـٔۡذَنُوكَ لِلۡخُرُوجِ فَقُل لَّن تَخۡرُجُواْ مَعِيَ أَبَدٗا وَلَن تُقَٰتِلُواْ مَعِيَ عَدُوًّاۖ إِنَّكُمۡ رَضِيتُم بِٱلۡقُعُودِ أَوَّلَ مَرَّةٖ فَٱقۡعُدُواْ مَعَ ٱلۡخَٰلِفِينَ ﴿٨٣﴾", "w": [["المخلّفون", "الذين تخلّفوا عن غزوة تبوك من المنافقين."], ["بمقعدهم", "بقعودهم خلاف رسول الله ﷺ."], ["وقالوا لا تنفروا في الحر", "قال المنافقون لبعضهم بعضاً: لا تخرجوا للغزو في الحر."], ["لو كانوا يفقهون", "لو كانوا يفقهون أسرار الأمور وعواقبها ونتائجها لما قالوا: لا تنفروا في الحر."], ["فليضحكوا قليلاً", "في الدنيا، وليبكوا كثيراً في الدار الآخرة."], ["فإن رجعك الله إلى طائفة منهم", "أي من المنافقين."], ["فاقعدوا مع الخالفين", "المتخلّفين عن تبوك من النساء والأطفال وأصحاب الأعذار."]], "m": "ما زال السياق في المنافقين المتخلّفين عن تبوك: فرح المخلّفون بمقعدهم خلاف رسول الله بالمدينة، وكرهوا أن يجاهدوا بأموالهم وأنفسهم في سبيل الله، وكرههم هذا ثمرة نفاقهم وكفرهم، وقالوا لبعضهم: لا تنفروا في الحر، إذ كانت تبوك في شدة الحر، فأمر الله رسوله أن يرد: قل نار جهنم أشد حراً لو كانوا يفقهون. فليضحكوا قليلاً في الدنيا بما يجدون من المسرّات، وليبكوا كثيراً يوم القيامة لما يجدون من الحرمان والعذاب، جزاءً بما كانوا يكسبون. فإن رجعك الله سالماً من تبوك إلى طائفة من المنافقين فاستأذنوك للخروج معك لغزو، فقل لن تخرجوا معي أبداً ولن تقاتلوا معي عدواً، إنكم رضيتم بالقعود أول مرة فاقعدوا مع الخالفين من النساء والأطفال، فإن هذا يزيد في همّهم ويعظّم حسرتهم.", "h": ["من علامات النفاق الفرح بترك طاعة الله ورسوله.", "من علامات النفاق كراهية طاعة الله ورسوله.", "كراهية الضحك والإكثار منه.", "تعمّد ترك الطاعة قد يسبّب الحرمان منها."], "k": "«قل نار جهنم أشد حراً»… حين تثقل عليّ الطاعة لحرّ أو برد أو تعب، هل أتذكّر حرّ جهنم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 126;
insert into public.tdb_cards(topic, i, body) select 126, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٧٣ – ٧٤", "q": "يَـٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿٧٣﴾ يَحۡلِفُونَ بِٱللَّهِ مَا قَالُواْ وَلَقَدۡ قَالُواْ كَلِمَةَ ٱلۡكُفۡرِ وَكَفَرُواْ بَعۡدَ إِسۡلَٰمِهِمۡ وَهَمُّواْ بِمَا لَمۡ يَنَالُواْۚ وَمَا نَقَمُوٓاْ إِلَّآ أَنۡ أَغۡنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضۡلِهِۦۚ فَإِن يَتُوبُواْ يَكُ خَيۡرٗا لَّهُمۡۖ وَإِن يَتَوَلَّوۡاْ يُعَذِّبۡهُمُ ٱللَّهُ عَذَابًا أَلِيمٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَمَا لَهُمۡ فِي ٱلۡأَرۡضِ مِن وَلِيّٖ وَلَا نَصِيرٖ ﴿٧٤﴾", "w": [["جاهد الكفار", "ابذل غاية جهدك في قتال الكفار والمنافقين."], ["واغلظ عليهم", "في القول والفعل، أي شدّد عليهم ولا تلن لهم."], ["كلمة الكفر", "كلمة يكفر بها من قالها، وهي قول الجلاس بن سويد: إن كان ما جاء به محمد حقاً لنحن شر من الحمير."], ["وهمّوا بما لم ينالوا", "همّوا بقتل النبي ﷺ في مؤامرة دنيئة وهم عائدون من تبوك."], ["وما نقموا إلا أن أغناهم", "ما أنكروا أو كرهوا من الإسلام ورسوله إلا أن أغناهم الله بعد فقر، أفعلى مثل هذا يهمّون بقتل رسول الله؟"]], "m": "يا أيها النبي جاهد الكفار بالسلاح، والمنافقين باللسان، واغلظ عليهم فلا هوادة مع من كفر بالله ورسوله أو أظهر الإيمان وأسرّ الكفر، ومأواهم في الآخرة جهنم وبئس المصير. وعلّة ذلك: يحلفون بالله ما قالوا، ولقد قالوا كلمة الكفر، إذ قال الجلاس بن سويد: لئن كان ما جاء به محمد حقاً لنحن شر من الحمير، فسمعه أحد المؤمنين فبلّغ رسول الله ﷺ، فجاء يعتذر ويحلف، فأكذبه الله، وكفروا بعد إسلامهم، وهمّوا بما لم ينالوا، إذ تآمر منافقون على قتل النبي ﷺ عند عودته من تبوك في عقبة في الطريق، عزموا أن يزاحموه بنوقهم حتى يسقط فيهلك، ففضحهم الله ونجّاه، إذ بعث عمار بن ياسر يضرب وجوه الرواحل فتفرّقوا، وما نقموا إلا أن أغناهم الله ورسوله من فضله بعد فقر، وهل الغنى مما يُنقم منه؟ ولكنه الكفر والنفاق يفسد الذوق والفطرة والعقل. ومع هذا يفتح الرب الرحيم باب التوبة: فإن يتوبوا يكُ خيراً لهم حالاً ومآلاً، وإن يتولّوا يعذّبهم الله عذاباً أليماً في الدنيا بالقتل والخزي، وفي الآخرة بالنار، وما لهم في الأرض من ولي ولا نصير.", "h": ["بيان آية السيف، وهي: «يا أيها النبي جاهد الكفار والمنافقين».", "تقرير مبدأ الردة، وهي أن يقول المسلم كلمة الكفر فيكفر بها، وذلك كالطعن في الإسلام، أو سب الله أو رسوله ﷺ، أو التكذيب بما أمر الله تعالى بالإيمان به، والتصديق بما أمر الله بتكذيبه."], "k": "«فإن يتوبوا يكُ خيراً لهم»… إن فُتح هذا الباب لمن همّ بقتل النبي ﷺ، أفيُغلق في وجهي؟"}, {"lbl": "الآيات ٧٥ – ٧٨", "q": "۞وَمِنۡهُم مَّنۡ عَٰهَدَ ٱللَّهَ لَئِنۡ ءَاتَىٰنَا مِن فَضۡلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّـٰلِحِينَ ﴿٧٥﴾ فَلَمَّآ ءَاتَىٰهُم مِّن فَضۡلِهِۦ بَخِلُواْ بِهِۦ وَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ ﴿٧٦﴾ فَأَعۡقَبَهُمۡ نِفَاقٗا فِي قُلُوبِهِمۡ إِلَىٰ يَوۡمِ يَلۡقَوۡنَهُۥ بِمَآ أَخۡلَفُواْ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُواْ يَكۡذِبُونَ ﴿٧٧﴾ أَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ سِرَّهُمۡ وَنَجۡوَىٰهُمۡ وَأَنَّ ٱللَّهَ عَلَّـٰمُ ٱلۡغُيُوبِ ﴿٧٨﴾", "w": [["ومنهم", "أي من المنافقين."], ["لئن آتانا من فضله", "مالاً كثيراً."], ["بخلوا به", "منعوه فلم يؤدّوا حقه من زكاة وغيرها."], ["فأعقبهم نفاقاً", "أورثهم البخل نفاقاً ملازماً لقلوبهم لا يفارقها إلى يوم يلقونه."], ["بما أخلفوا الله", "بسبب إخلافهم ما وعدوا الله تعالى به."], ["سرّهم ونجواهم", "ما يسرّونه في نفوسهم ويخفونه، وما يتناجون به فيما بينهم."], ["علّام الغيوب", "يعلم كل غيب في الأرض أو في السماء."]], "m": "ما زال السياق في المنافقين، وهذا صنف آخر منهم: عاهدوا الله لئن أغناهم من فضله ليتصدّقنّ ولينفقنّ في طريق البر والخير وليكوننّ من الصالحين، فلما أعطاهم الله ما سألوا وكثر مالهم بخلوا به، وتولّوا عما تعهّدوا به من تقوى وصلاح وهم معرضون، فأورثهم هذا البخل وخلف الوعد والكذب نفاقاً في قلوبهم لا يفارقهم إلى يوم يلقونه، بما أخلفوا الله ما وعدوه وبما كانوا يكذبون. ألم يعلموا أن الله يعلم سرّهم ونجواهم وأن الله علّام الغيوب؟ توبيخ لهم، كأنهم لا يعلمون ذلك، وإلا كيف يعدونه ويحلفون له ثم يخلفون؟ فموقفهم مخزٍ، وويل لهم حيث لازمهم النفاق حتى الموت، فأُغلق باب التوبة في وجوههم.", "h": ["وجوب الوفاء بالعهود، وخاصة عهود الله تعالى.", "ذم البخل وأهله.", "تقرير مبدأ أن السيئة يتولّد عنها سيئة.", "جواز تقريع وتأنيب أهل الباطل.", "وجوب مراقبة الله تعالى، إذ لو راقب هؤلاء المنافقون الله تعالى لما خرجوا عن طاعته."], "k": "«لئن آتانا من فضله لنصّدّقنّ»… ما الذي وعدت به ربي إن فرّج عني، فهل وفّيت؟"}, {"lbl": "الآيتان ٧٩ – ٨٠", "q": "ٱلَّذِينَ يَلۡمِزُونَ ٱلۡمُطَّوِّعِينَ مِنَ ٱلۡمُؤۡمِنِينَ فِي ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهۡدَهُمۡ فَيَسۡخَرُونَ مِنۡهُمۡ سَخِرَ ٱللَّهُ مِنۡهُمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ ﴿٧٩﴾ ٱسۡتَغۡفِرۡ لَهُمۡ أَوۡ لَا تَسۡتَغۡفِرۡ لَهُمۡ إِن تَسۡتَغۡفِرۡ لَهُمۡ سَبۡعِينَ مَرَّةٗ فَلَن يَغۡفِرَ ٱللَّهُ لَهُمۡۚ ذَٰلِكَ بِأَنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَرَسُولِهِۦۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ ﴿٨٠﴾", "w": [["يلمزون", "يعيبون ويطعنون."], ["المطّوّعين", "المتصدّقين بأموالهم زيادة على الفريضة."], ["إلا جهدهم", "إلا طاقتهم وما يقدرون عليه فيأتون به."], ["فيسخرون منهم", "يستهزئون بهم احتقاراً لهم."], ["استغفر لهم", "اطلب لهم المغفرة أو لا تطلب."], ["لا يهدي القوم الفاسقين", "إلى ما فيه خيرهم وسعادتهم، وذلك لتوغّلهم في العصيان."]], "m": "ما زال السياق في التنديد بالمنافقين: الذين يلمزون المطّوّعين من المؤمنين في الصدقات، والذين لا يجدون إلا جهدهم، فيسخرون منهم، سخر الله منهم جزاء سخريتهم، ولهم عذاب أليم. وكيفية لمزهم أن النبي ﷺ دعا إلى الصدقة، فإذا جاء الرجل بمال كثير قالوا: مراءٍ، وإذا جاء بالقليل قالوا: الله غني عن صاعك هذا، ففضحهم الله. وأخبر نبيه أن استغفاره لهم وعدمه سواء: استغفر لهم أو لا تستغفر لهم، إن تستغفر لهم سبعين مرة فلن يغفر الله لهم، ذلك بأنهم كفروا بالله ورسوله، والكافر مخلّد في النار، والله لا يهدي القوم الفاسقين، لأن الفسق أصبح وصفاً لازماً لهم فلا يتوبون.", "h": ["حرمة لمز المؤمن والطعن فيه.", "حرمة السخرية بالمؤمن.", "غيرة الله على أوليائه، حيث سخر ممن سخر من المطّوّعين.", "من مات على الكفر لا ينفعه الاستغفار له، بل ولا يجوز الاستغفار له.", "التوغّل في الفسق أو الكفر أو الظلم يحرم صاحبه الهداية."], "k": "«والذين لا يجدون إلا جهدهم»… هل أستقلّ صدقة يسيرة فأتركها، والله يقبل الجهد القليل؟"}, {"lbl": "الآيات ٨١ – ٨٣", "q": "فَرِحَ ٱلۡمُخَلَّفُونَ بِمَقۡعَدِهِمۡ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓاْ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ وَقَالُواْ لَا تَنفِرُواْ فِي ٱلۡحَرِّۗ قُلۡ نَارُ جَهَنَّمَ أَشَدُّ حَرّٗاۚ لَّوۡ كَانُواْ يَفۡقَهُونَ ﴿٨١﴾ فَلۡيَضۡحَكُواْ قَلِيلٗا وَلۡيَبۡكُواْ كَثِيرٗا جَزَآءَۢ بِمَا كَانُواْ يَكۡسِبُونَ ﴿٨٢﴾ فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٖ مِّنۡهُمۡ فَٱسۡتَـٔۡذَنُوكَ لِلۡخُرُوجِ فَقُل لَّن تَخۡرُجُواْ مَعِيَ أَبَدٗا وَلَن تُقَٰتِلُواْ مَعِيَ عَدُوًّاۖ إِنَّكُمۡ رَضِيتُم بِٱلۡقُعُودِ أَوَّلَ مَرَّةٖ فَٱقۡعُدُواْ مَعَ ٱلۡخَٰلِفِينَ ﴿٨٣﴾", "w": [["المخلّفون", "الذين تخلّفوا عن غزوة تبوك من المنافقين."], ["بمقعدهم", "بقعودهم خلاف رسول الله ﷺ."], ["وقالوا لا تنفروا في الحر", "قال المنافقون لبعضهم بعضاً: لا تخرجوا للغزو في الحر."], ["لو كانوا يفقهون", "لو كانوا يفقهون أسرار الأمور وعواقبها ونتائجها لما قالوا: لا تنفروا في الحر."], ["فليضحكوا قليلاً", "في الدنيا، وليبكوا كثيراً في الدار الآخرة."], ["فإن رجعك الله إلى طائفة منهم", "أي من المنافقين."], ["فاقعدوا مع الخالفين", "المتخلّفين عن تبوك من النساء والأطفال وأصحاب الأعذار."]], "m": "ما زال السياق في المنافقين المتخلّفين عن تبوك: فرح المخلّفون بمقعدهم خلاف رسول الله بالمدينة، وكرهوا أن يجاهدوا بأموالهم وأنفسهم في سبيل الله، وكرههم هذا ثمرة نفاقهم وكفرهم، وقالوا لبعضهم: لا تنفروا في الحر، إذ كانت تبوك في شدة الحر، فأمر الله رسوله أن يرد: قل نار جهنم أشد حراً لو كانوا يفقهون. فليضحكوا قليلاً في الدنيا بما يجدون من المسرّات، وليبكوا كثيراً يوم القيامة لما يجدون من الحرمان والعذاب، جزاءً بما كانوا يكسبون. فإن رجعك الله سالماً من تبوك إلى طائفة من المنافقين فاستأذنوك للخروج معك لغزو، فقل لن تخرجوا معي أبداً ولن تقاتلوا معي عدواً، إنكم رضيتم بالقعود أول مرة فاقعدوا مع الخالفين من النساء والأطفال، فإن هذا يزيد في همّهم ويعظّم حسرتهم.", "h": ["من علامات النفاق الفرح بترك طاعة الله ورسوله.", "من علامات النفاق كراهية طاعة الله ورسوله.", "كراهية الضحك والإكثار منه.", "تعمّد ترك الطاعة قد يسبّب الحرمان منها."], "k": "«قل نار جهنم أشد حراً»… حين تثقل عليّ الطاعة لحرّ أو برد أو تعب، هل أتذكّر حرّ جهنم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (127, 9, 84, 92, 'سورة التوبة ٨٤ – ٩٢', '«ولا تصلّ على أحد منهم مات أبداً»، «رضوا بأن يكونوا مع الخوالف»، و«ليس على الضعفاء… حرج»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 127) = $j$[{"lbl": "الآيتان ٨٤ – ٨٥", "q": "وَلَا تُصَلِّ عَلَىٰٓ أَحَدٖ مِّنۡهُم مَّاتَ أَبَدٗا وَلَا تَقُمۡ عَلَىٰ قَبۡرِهِۦٓۖ إِنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُواْ وَهُمۡ فَٰسِقُونَ ﴿٨٤﴾ وَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَأَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِي ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ ﴿٨٥﴾", "w": [["ولا تصلّ على أحد", "أي صلاة الجنازة."], ["ولا تقم على قبره", "لا تتولّ دفنه والدعاء له كما تفعل مع المؤمنين."], ["وماتوا وهم فاسقون", "خارجون عن طاعة الله ورسوله."], ["وتزهق أنفسهم", "تخرج أرواحهم بالموت وهم كافرون."]], "m": "نزلت في شأن عبد الله بن أُبيّ بن سلول كبير المنافقين، لما مات جاء ولده، وكان اسمه الحباب فسمّاه رسول الله ﷺ عبد الله، وقال: الحباب اسم شيطان، فقال: يا رسول الله إن أبي قد مات فأعطني قميصك أكفّنه فيه، وصلّ عليه واستغفر له، فأعطاه القميص، فلما أراد أن يصلي عليه جذبه عمر وقال: أليس قد نهاك الله أن تصلي على المنافقين؟ فقال: «بل خيّرني فقال: استغفر لهم أو لا تستغفر لهم»، فصلى عليه، فأنزل الله: ولا تصلّ على أحد منهم مات أبداً، ولا تقم على قبره فتتولّى دفنه والدعاء له بالتثبيت عند المسألة، إنهم كفروا بالله ورسوله وماتوا وهم فاسقون. ولا تعجبك أموالهم وأولادهم فتصلي عليهم، إنما أعطاهم الله ذلك لا كرامة لهم، بل ليعذّبهم بها في الدنيا بالغموم والهموم، وتزهق أنفسهم وهم كافرون، فينتقلون إلى عذاب أبدي.", "h": ["حرمة الصلاة على الكافر مطلقاً.", "حرمة غسل الكافر والقيام على دفنه والدعاء له.", "كراهة الصلاة على أهل الفسق دون الكفر.", "حرمة الإعجاب بأحوال الكافرين المادية."], "k": "«ولا تعجبك أموالهم وأولادهم»… هل يبهرني ما عند أهل الدنيا، وأنسى أنه قد يكون عذاباً لهم؟"}, {"lbl": "الآيات ٨٦ – ٩٠", "q": "وَإِذَآ أُنزِلَتۡ سُورَةٌ أَنۡ ءَامِنُواْ بِٱللَّهِ وَجَٰهِدُواْ مَعَ رَسُولِهِ ٱسۡتَـٔۡذَنَكَ أُوْلُواْ ٱلطَّوۡلِ مِنۡهُمۡ وَقَالُواْ ذَرۡنَا نَكُن مَّعَ ٱلۡقَٰعِدِينَ ﴿٨٦﴾ رَضُواْ بِأَن يَكُونُواْ مَعَ ٱلۡخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَفۡقَهُونَ ﴿٨٧﴾ لَٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ جَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ وَأُوْلَـٰٓئِكَ لَهُمُ ٱلۡخَيۡرَٰتُۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿٨٨﴾ أَعَدَّ ٱللَّهُ لَهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٨٩﴾ وَجَآءَ ٱلۡمُعَذِّرُونَ مِنَ ٱلۡأَعۡرَابِ لِيُؤۡذَنَ لَهُمۡ وَقَعَدَ ٱلَّذِينَ كَذَبُواْ ٱللَّهَ وَرَسُولَهُۥۚ سَيُصِيبُ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٞ ﴿٩٠﴾", "w": [["سورة", "قطعة من القرآن، آية أو آيات."], ["استأذنك", "طلبوا إذنك لهم بالتخلّف."], ["أولو الطَّول منهم", "أولو الثروة والغنى."], ["ذرنا نكن مع القاعدين", "اتركنا مع المتخلّفين من العجزة والمرضى والأطفال."], ["مع الخوالف", "مع النساء، جمع خالفة: المرأة تخلف الرجل في البيت إذا غاب."], ["وطُبع على قلوبهم", "توالت ذنوبهم على قلوبهم فأصبحت طابعاً عليها فحجبتها عن الفهم."], ["لهم الخيرات", "في الدنيا بالنصر والغنيمة، وفي الآخرة بالجنة والكرامة."], ["وأولئك هم المفلحون", "الفائزون بالسلامة من المخوف والظفر بالمحبوب."], ["المعذّرون", "المعتذرون."], ["وقعد الذين كذبوا الله ورسوله", "ولم يأتوا إلى طلب الإذن بالقعود عن الجهاد منافقو الأعراب."]], "m": "ما زال السياق في كشف عورات المنافقين: وإذا أُنزلت سورة تأمر أن آمنوا بالله وجاهدوا مع رسوله استأذنك أولو الثروة منهم وقالوا: ذرنا نكن مع القاعدين، لجبنهم وهزيمتهم النفسية، رضوا بأن يكونوا مع النساء في البيوت، وصمة عار، وطُبع على قلوبهم بآثار ذنوبهم فهم لا يفقهون. لكن الرسول والذين آمنوا معه جاهدوا بأموالهم وأنفسهم، وأولئك لهم الخيرات في الدنيا بالانتصارات والغنائم، وفي الآخرة بالجنة ونعيمها ورضوان الله، وأولئك هم المفلحون، أعد الله لهم جنات تجري من تحتها الأنهار خالدين فيها، ذلك الفوز العظيم. وجاء المعذّرون من الأعراب سكان البادية، كأسد وغطفان ورهط عامر بن الطفيل، يطلبون الإذن بالتخلّف بدعوى الجهد والمخمصة، وقد يكونون معذورين حقاً وقد لا يكونون، وقعد الذين كذبوا الله ورسوله في دعوى الإيمان، سيصيب الذين كفروا منهم عذاب أليم في الدنيا والآخرة إن ماتوا على كفرهم.", "h": ["القرآن هو مصدر التشريع الإلهي الأول، والسنة الثاني.", "مشروعية الاستئذان للحاجة الملحّة.", "حرمة الاستئذان للتخلّف عن الجهاد مع القدرة عليه.", "حرمة التخلّف عن الجهاد بدون إذن من الإمام.", "فضل الجهاد بالمال والنفس في سبيل الله.", "بيان عظم الأجر وعظيم الجزاء لأهل الإيمان والجهاد."], "k": "«رضوا بأن يكونوا مع الخوالف»… في أي ميدان من ميادين الخير رضيت بالقعود وأنا قادر؟"}, {"lbl": "الآيتان ٩١ – ٩٢", "q": "لَّيۡسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلۡمَرۡضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُواْ لِلَّهِ وَرَسُولِهِۦۚ مَا عَلَى ٱلۡمُحۡسِنِينَ مِن سَبِيلٖۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٩١﴾ وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوۡكَ لِتَحۡمِلَهُمۡ قُلۡتَ لَآ أَجِدُ مَآ أَحۡمِلُكُمۡ عَلَيۡهِ تَوَلَّواْ وَّأَعۡيُنُهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ حَزَنًا أَلَّا يَجِدُواْ مَا يُنفِقُونَ ﴿٩٢﴾", "w": [["على الضعفاء", "كالشيوخ."], ["ولا على المرضى", "كالعمي والزمنى."], ["حرج", "إثم على التخلّف."], ["إذا نصحوا لله ورسوله", "لا حرج عليهم في التخلّف إذا نصحوا لله ورسوله، وذلك بطاعتهم لله ورسوله مع تركهم الإرجاف والتثبيط."], ["ما على المحسنين من سبيل", "من طريق إلى مؤاخذتهم."], ["لتحملهم", "على رواحل يركبونها."], ["تولّوا", "رجعوا إلى بيوتهم."], ["تفيض من الدمع", "تسيل بالدموع الغزيرة حزناً على عدم الخروج."]], "m": "لما ندّد الله بالمتخلّفين، ذكر أنه لا حرج على أصحاب الأعذار: ليس على الضعفاء كالشيوخ، ولا على المرضى والعميان وذوي العرج، ولا على الفقراء الذين لا يجدون ما ينفقون، حرج إذا نصحوا لله ورسوله، بطاعتهما في الأمر والنهي، وترك الإرجاف والتثبيط والدعاية المضادة، ما على المحسنين في تخلّفهم من سبيل إلى انتقاصهم أو أذيّتهم، لأنهم تخلّفوا بعذر شرعي، وهم مطيعون، وقلوبهم مع الله ورسوله وإن تخلّفت أجسادهم، والله غفور رحيم. ولا على الذين إذا ما أتوك لتحملهم على رواحل إلى الجهاد معك، قلت معتذراً: لا أجد ما أحملكم عليه، تولّوا إلى منازلهم وأعينهم تفيض من الدمع حزناً ألّا يجدوا ما ينفقون في سيرهم معكم، وهم نفر منهم العرباض بن سارية وبنو مقرّن من مزينة رضي الله عنهم.", "h": ["لا حرج على أصحاب الأعذار الذين ذكر الله تعالى في قوله: «ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج»، وفي هذه الآية: «ولا على الذين لا يجدون ما ينفقون حرج»، بشرط طاعة الله والرسول فيما يستطيعون، والنصح لله والرسول بالقول والعمل، وترك التثبيط والتخذيل والإرجاف.", "مظاهر الكمال المحمدي في تواضعه ورحمته وبرّه وإحسانه إلى المؤمنين.", "بيان ما كان عليه أصحاب الرسول ﷺ من المهاجرين والأنصار من الإيمان واليقين، والسمع والطاعة، والمحبة والولاء، ورقّة القلوب، وصفاء الأرواح."], "k": "«تولّوا وأعينهم تفيض من الدمع»… متى آخر مرة بكيت على طاعة فاتتني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 127;
insert into public.tdb_cards(topic, i, body) select 127, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٨٤ – ٨٥", "q": "وَلَا تُصَلِّ عَلَىٰٓ أَحَدٖ مِّنۡهُم مَّاتَ أَبَدٗا وَلَا تَقُمۡ عَلَىٰ قَبۡرِهِۦٓۖ إِنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُواْ وَهُمۡ فَٰسِقُونَ ﴿٨٤﴾ وَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَأَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِي ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ ﴿٨٥﴾", "w": [["ولا تصلّ على أحد", "أي صلاة الجنازة."], ["ولا تقم على قبره", "لا تتولّ دفنه والدعاء له كما تفعل مع المؤمنين."], ["وماتوا وهم فاسقون", "خارجون عن طاعة الله ورسوله."], ["وتزهق أنفسهم", "تخرج أرواحهم بالموت وهم كافرون."]], "m": "نزلت في شأن عبد الله بن أُبيّ بن سلول كبير المنافقين، لما مات جاء ولده، وكان اسمه الحباب فسمّاه رسول الله ﷺ عبد الله، وقال: الحباب اسم شيطان، فقال: يا رسول الله إن أبي قد مات فأعطني قميصك أكفّنه فيه، وصلّ عليه واستغفر له، فأعطاه القميص، فلما أراد أن يصلي عليه جذبه عمر وقال: أليس قد نهاك الله أن تصلي على المنافقين؟ فقال: «بل خيّرني فقال: استغفر لهم أو لا تستغفر لهم»، فصلى عليه، فأنزل الله: ولا تصلّ على أحد منهم مات أبداً، ولا تقم على قبره فتتولّى دفنه والدعاء له بالتثبيت عند المسألة، إنهم كفروا بالله ورسوله وماتوا وهم فاسقون. ولا تعجبك أموالهم وأولادهم فتصلي عليهم، إنما أعطاهم الله ذلك لا كرامة لهم، بل ليعذّبهم بها في الدنيا بالغموم والهموم، وتزهق أنفسهم وهم كافرون، فينتقلون إلى عذاب أبدي.", "h": ["حرمة الصلاة على الكافر مطلقاً.", "حرمة غسل الكافر والقيام على دفنه والدعاء له.", "كراهة الصلاة على أهل الفسق دون الكفر.", "حرمة الإعجاب بأحوال الكافرين المادية."], "k": "«ولا تعجبك أموالهم وأولادهم»… هل يبهرني ما عند أهل الدنيا، وأنسى أنه قد يكون عذاباً لهم؟"}, {"lbl": "الآيات ٨٦ – ٩٠", "q": "وَإِذَآ أُنزِلَتۡ سُورَةٌ أَنۡ ءَامِنُواْ بِٱللَّهِ وَجَٰهِدُواْ مَعَ رَسُولِهِ ٱسۡتَـٔۡذَنَكَ أُوْلُواْ ٱلطَّوۡلِ مِنۡهُمۡ وَقَالُواْ ذَرۡنَا نَكُن مَّعَ ٱلۡقَٰعِدِينَ ﴿٨٦﴾ رَضُواْ بِأَن يَكُونُواْ مَعَ ٱلۡخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَفۡقَهُونَ ﴿٨٧﴾ لَٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ جَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ وَأُوْلَـٰٓئِكَ لَهُمُ ٱلۡخَيۡرَٰتُۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿٨٨﴾ أَعَدَّ ٱللَّهُ لَهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٨٩﴾ وَجَآءَ ٱلۡمُعَذِّرُونَ مِنَ ٱلۡأَعۡرَابِ لِيُؤۡذَنَ لَهُمۡ وَقَعَدَ ٱلَّذِينَ كَذَبُواْ ٱللَّهَ وَرَسُولَهُۥۚ سَيُصِيبُ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابٌ أَلِيمٞ ﴿٩٠﴾", "w": [["سورة", "قطعة من القرآن، آية أو آيات."], ["استأذنك", "طلبوا إذنك لهم بالتخلّف."], ["أولو الطَّول منهم", "أولو الثروة والغنى."], ["ذرنا نكن مع القاعدين", "اتركنا مع المتخلّفين من العجزة والمرضى والأطفال."], ["مع الخوالف", "مع النساء، جمع خالفة: المرأة تخلف الرجل في البيت إذا غاب."], ["وطُبع على قلوبهم", "توالت ذنوبهم على قلوبهم فأصبحت طابعاً عليها فحجبتها عن الفهم."], ["لهم الخيرات", "في الدنيا بالنصر والغنيمة، وفي الآخرة بالجنة والكرامة."], ["وأولئك هم المفلحون", "الفائزون بالسلامة من المخوف والظفر بالمحبوب."], ["المعذّرون", "المعتذرون."], ["وقعد الذين كذبوا الله ورسوله", "ولم يأتوا إلى طلب الإذن بالقعود عن الجهاد منافقو الأعراب."]], "m": "ما زال السياق في كشف عورات المنافقين: وإذا أُنزلت سورة تأمر أن آمنوا بالله وجاهدوا مع رسوله استأذنك أولو الثروة منهم وقالوا: ذرنا نكن مع القاعدين، لجبنهم وهزيمتهم النفسية، رضوا بأن يكونوا مع النساء في البيوت، وصمة عار، وطُبع على قلوبهم بآثار ذنوبهم فهم لا يفقهون. لكن الرسول والذين آمنوا معه جاهدوا بأموالهم وأنفسهم، وأولئك لهم الخيرات في الدنيا بالانتصارات والغنائم، وفي الآخرة بالجنة ونعيمها ورضوان الله، وأولئك هم المفلحون، أعد الله لهم جنات تجري من تحتها الأنهار خالدين فيها، ذلك الفوز العظيم. وجاء المعذّرون من الأعراب سكان البادية، كأسد وغطفان ورهط عامر بن الطفيل، يطلبون الإذن بالتخلّف بدعوى الجهد والمخمصة، وقد يكونون معذورين حقاً وقد لا يكونون، وقعد الذين كذبوا الله ورسوله في دعوى الإيمان، سيصيب الذين كفروا منهم عذاب أليم في الدنيا والآخرة إن ماتوا على كفرهم.", "h": ["القرآن هو مصدر التشريع الإلهي الأول، والسنة الثاني.", "مشروعية الاستئذان للحاجة الملحّة.", "حرمة الاستئذان للتخلّف عن الجهاد مع القدرة عليه.", "حرمة التخلّف عن الجهاد بدون إذن من الإمام.", "فضل الجهاد بالمال والنفس في سبيل الله.", "بيان عظم الأجر وعظيم الجزاء لأهل الإيمان والجهاد."], "k": "«رضوا بأن يكونوا مع الخوالف»… في أي ميدان من ميادين الخير رضيت بالقعود وأنا قادر؟"}, {"lbl": "الآيتان ٩١ – ٩٢", "q": "لَّيۡسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلۡمَرۡضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُواْ لِلَّهِ وَرَسُولِهِۦۚ مَا عَلَى ٱلۡمُحۡسِنِينَ مِن سَبِيلٖۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٩١﴾ وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوۡكَ لِتَحۡمِلَهُمۡ قُلۡتَ لَآ أَجِدُ مَآ أَحۡمِلُكُمۡ عَلَيۡهِ تَوَلَّواْ وَّأَعۡيُنُهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ حَزَنًا أَلَّا يَجِدُواْ مَا يُنفِقُونَ ﴿٩٢﴾", "w": [["على الضعفاء", "كالشيوخ."], ["ولا على المرضى", "كالعمي والزمنى."], ["حرج", "إثم على التخلّف."], ["إذا نصحوا لله ورسوله", "لا حرج عليهم في التخلّف إذا نصحوا لله ورسوله، وذلك بطاعتهم لله ورسوله مع تركهم الإرجاف والتثبيط."], ["ما على المحسنين من سبيل", "من طريق إلى مؤاخذتهم."], ["لتحملهم", "على رواحل يركبونها."], ["تولّوا", "رجعوا إلى بيوتهم."], ["تفيض من الدمع", "تسيل بالدموع الغزيرة حزناً على عدم الخروج."]], "m": "لما ندّد الله بالمتخلّفين، ذكر أنه لا حرج على أصحاب الأعذار: ليس على الضعفاء كالشيوخ، ولا على المرضى والعميان وذوي العرج، ولا على الفقراء الذين لا يجدون ما ينفقون، حرج إذا نصحوا لله ورسوله، بطاعتهما في الأمر والنهي، وترك الإرجاف والتثبيط والدعاية المضادة، ما على المحسنين في تخلّفهم من سبيل إلى انتقاصهم أو أذيّتهم، لأنهم تخلّفوا بعذر شرعي، وهم مطيعون، وقلوبهم مع الله ورسوله وإن تخلّفت أجسادهم، والله غفور رحيم. ولا على الذين إذا ما أتوك لتحملهم على رواحل إلى الجهاد معك، قلت معتذراً: لا أجد ما أحملكم عليه، تولّوا إلى منازلهم وأعينهم تفيض من الدمع حزناً ألّا يجدوا ما ينفقون في سيرهم معكم، وهم نفر منهم العرباض بن سارية وبنو مقرّن من مزينة رضي الله عنهم.", "h": ["لا حرج على أصحاب الأعذار الذين ذكر الله تعالى في قوله: «ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج»، وفي هذه الآية: «ولا على الذين لا يجدون ما ينفقون حرج»، بشرط طاعة الله والرسول فيما يستطيعون، والنصح لله والرسول بالقول والعمل، وترك التثبيط والتخذيل والإرجاف.", "مظاهر الكمال المحمدي في تواضعه ورحمته وبرّه وإحسانه إلى المؤمنين.", "بيان ما كان عليه أصحاب الرسول ﷺ من المهاجرين والأنصار من الإيمان واليقين، والسمع والطاعة، والمحبة والولاء، ورقّة القلوب، وصفاء الأرواح."], "k": "«تولّوا وأعينهم تفيض من الدمع»… متى آخر مرة بكيت على طاعة فاتتني؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;